export async function buildResidualRiskInventory(
  repository: string,
  scanDirectory?: string,
): Promise<string> {
  const canonicalRepository = await realpath(repository);
  const inventoryPaths =
    scanDirectory === undefined
      ? []
      : await readModelInventoryPaths(scanDirectory, canonicalRepository);
  const paths =
    inventoryPaths.length > 0
      ? inventoryPaths
      : await discoverSourcePaths(canonicalRepository);
  const records: ResidualRiskRecord[] = [];
  const sourceFiles: SourceFileSnapshot[] = [];
  let totalBytes = 0;

  for (const candidatePath of paths.slice(0, MAX_FILES)) {
    const source = await readBoundedRepositoryFile(
      canonicalRepository,
      candidatePath,
    );
    if (source === null) continue;
    totalBytes += source.byteLength;
    if (totalBytes > MAX_TOTAL_BYTES) break;
    const text = source.toString("utf8");
    if (text.includes("\0")) continue;
    const lines = text.split(/\r?\n/u);
    const normalizedPath = candidatePath.replaceAll("\\", "/");
    sourceFiles.push({
      path: normalizedPath,
      extension: extname(normalizedPath).toLowerCase(),
      lines,
      text,
    });
    let fileRecords: ResidualRiskRecord[] = [];
    const retainedFileRecords: ResidualRiskRecord[] = [];
    for (let index = 0; index < lines.length; index += 1) {
      const matchingSignals = RISK_SIGNALS.filter(([, , expression]) =>
        expression.test(lines[index] ?? ""),
      );
      const categories = matchingSignals.map(([category]) => category);
      if (categories.length === 0) continue;
      const startLine = Math.max(1, index + 1 - CONTEXT_LINES_BEFORE);
      const endLine = Math.min(lines.length, index + 1 + CONTEXT_LINES_AFTER);
      mergeResidualRiskRecord(fileRecords, lines, {
        path: candidatePath.replaceAll("\\", "/"),
        line: index + 1,
        categories,
        priority: Math.max(...matchingSignals.map(([, priority]) => priority)),
        startLine,
        endLine,
        excerpt: "",
      });
      if (fileRecords.length >= MAX_CANDIDATES) {
        retainedFileRecords.push(
          ...selectResidualRiskRecords(fileRecords, MAX_SIGNALS_PER_FILE),
        );
        fileRecords = [];
      }
    }
    records.push(
      ...selectResidualRiskRecords(
        [...retainedFileRecords, ...fileRecords],
        MAX_SIGNALS_PER_FILE,
      ),
    );
  }

  sourceFiles.push(
    ...(await nearestNodePackageMetadataSnapshots(
      canonicalRepository,
      sourceFiles,
    )),
  );
  sourceFiles.push(
    ...(await nearestPythonRequirementSnapshots(
      canonicalRepository,
      sourceFiles,
    )),
  );
  sourceFiles.push(
    ...(await nearestPythonRuntimeSnapshots(canonicalRepository, sourceFiles)),
  );

  for (const file of sourceFiles) {
    records.push(
      ...sourceDisplayControlRiskRecords(file.path, file.lines),
      ...frameworkDataflowRecords(file.path, file.lines, sourceFiles),
      ...cloudFormationRiskRecords(file.path, file.lines, file.text),
      ...kubernetesRiskRecords(file.path, file.lines, file.text),
      ...terraformRiskRecords(file.path, file.lines, file.text),
      ...phpSqlInjectionRecords(file.path, file.lines, file.text),
      ...rubyCommandInjectionRecords(file.path, file.lines, file.text),
      ...rustCommandInjectionRecords(file.path, file.lines, file.text),
      ...kotlinKtorCommandInjectionRecords(file.path, file.lines, file.text),
      ...githubActionsPrivilegeRecords(file.path, file.lines, file.text),
      ...githubActionsSelfHostedPrRecords(file.path, file.lines, file.text),
      ...githubActionsWorkflowInjectionRecords(
        file.path,
        file.lines,
        file.text,
      ),
    );
  }
  records.push(...githubActionsArtifactPoisoningRecords(sourceFiles));
  records.push(...githubActionsReusableWorkflowInjectionRecords(sourceFiles));
  records.push(...githubActionsCompositeActionInjectionRecords(sourceFiles));
  records.push(...traefikReplacePathRegexRecords(sourceFiles));
  records.push(...goExecInjectionRecords(sourceFiles));
  records.push(...goHttpSsrfRecords(sourceFiles));
  records.push(...goPathTraversalRecords(sourceFiles));
  records.push(...goEchoEncodedSeparatorRecords(sourceFiles));
  records.push(...goTemplateInjectionRecords(sourceFiles));
  records.push(...goObjectAuthorizationRecords(sourceFiles));
  records.push(...goGormSqlInjectionRecords(sourceFiles));
  records.push(...goSqlInjectionRecords(sourceFiles));
  records.push(...goSqlxSqlInjectionRecords(sourceFiles));
  records.push(...goSquirrelSqlInjectionRecords(sourceFiles));
  records.push(...goPgxSqlInjectionRecords(sourceFiles));
  records.push(...goPgconnSqlInjectionRecords(sourceFiles));
  records.push(...nodeOpcuaCrossFileServerDosRecords(sourceFiles));
  records.push(...nodeOpcuaCrossFileServerAuthRecords(sourceFiles));
  records.push(...nodeDeepseekMcpHttpSessionAuthorizationRecords(sourceFiles));
  records.push(...pythonChainlitMcpStdioCommandInjectionRecords(sourceFiles));
  records.push(...nodeContentfulMcpManagementTokenLeakRecords(sourceFiles));
  records.push(...nodeNextJsDynamicRouteAuthorizationRecords(sourceFiles));
  records.push(...nodePlateMediaEmbedXssRecords(sourceFiles));
  records.push(...nodeDefuddleExtractorXssRecords(sourceFiles));
  records.push(...nodePickemTerminalInjectionRecords(sourceFiles));
  records.push(...nodeLogtapeSyslogInjectionRecords(sourceFiles));
  records.push(...nodeSunEditorEmbedXssRecords(sourceFiles));
  records.push(...nodeNxSelfHostedCacheArchiveEscapeRecords(sourceFiles));
  records.push(...nodeUndiciSocks5CrossOriginRoutingRecords(sourceFiles));
  records.push(...nodeAuthJsConfigurationErrorFailOpenRecords(sourceFiles));
  records.push(...nodeKeystoneNegativeTakeBypassRecords(sourceFiles));
  records.push(...frameworkCrossFileDataflowRecords(sourceFiles));
  records.push(...nodeAxiosPrototypeGadgetChainRecords(sourceFiles, records));
  records.push(
    ...nodeIpv6TransitionIncompleteGuardRecords(sourceFiles, records),
  );
  records.push(...nodeIpAddressLeadingZeroSsrfRecords(sourceFiles, records));
  records.push(...nodeFastUriHostPolicyConfusionRecords(sourceFiles, records));
  records.push(...nodeFastUriEncodedDotPathRecords(sourceFiles, records));
  records.push(...javaFileGetNamePathBoundaryRecords(sourceFiles, records));
  records.push(...javaPathGetFileNamePathBoundaryRecords(sourceFiles, records));

  return selectResidualRiskRecords(
    nodeAxiosConsolidatedPrototypeGadgetRecords(records),
    MAX_SIGNALS,
  )
    .map(({ priority: _priority, excerpt, sourceExcerpt, ...record }) =>
      JSON.stringify({
        ...record,
        excerptEncoding: "base64",
        excerptBase64: Buffer.from(excerpt, "utf8").toString("base64"),
        ...(sourceExcerpt === undefined
          ? {}
          : {
              sourceExcerptEncoding: "base64",
              sourceExcerptBase64: Buffer.from(sourceExcerpt, "utf8").toString(
                "base64",
              ),
            }),
      }),
    )
    .join("\n");
}

interface NodePrototypePollutionSink {
  keyExpressions: string[];
}

function nodePrototypePollutionSink(
  lines: readonly string[],
  line: number,
): NodePrototypePollutionSink | undefined {
  const original = javascriptCodeBeforeComment(lines[line - 1] ?? "");
  const structural = javascriptStructuralLines([original])[0] ?? "";
  const assignment =
    /\b([A-Za-z_$][\w$]*(?:\s*(?:\.\s*[A-Za-z_$][\w$]*|\[[^\]\r\n]+\]))+)\s*=(?!=|>)/gu;
  for (const candidate of structural.matchAll(assignment)) {
    if (candidate.index === undefined) continue;
    const leftStructural = candidate[1]!;
    const leftOriginal = original.slice(
      candidate.index,
      candidate.index + leftStructural.length,
    );
    const keyExpressions: string[] = [];
    const bracket = /\[([^\]\r\n]+)\]/gu;
    for (const match of leftStructural.matchAll(bracket)) {
      if (match.index === undefined) continue;
      const open = leftStructural.indexOf("[", match.index);
      const close = leftStructural.indexOf("]", open + 1);
      if (open < 0 || close < 0) continue;
      const expression = leftOriginal.slice(open + 1, close).trim();
      if (
        expression === "" ||
        /^(?:[+-]?\d+(?:\.\d+)?|["'`][\s\S]*["'`])$/u.test(expression)
      ) {
        continue;
      }
      keyExpressions.push(expression);
    }
    if (keyExpressions.length >= 2) return { keyExpressions };
  }
  return undefined;
}

