type NodeAxiosPrototypeGadgetStage =
  | "direct-prototype-gadget"
  | "interceptor-proxy-gadget";

interface NodeAxiosPrototypeGadgetUse {
  dependency: NodeRuntimeDependency;
  file: SourceFileSnapshot;
  interceptorLine?: number;
  ownProxyDisabled: Array<{ kind: string; line: number }>;
  receiver: string;
  sink: NodeHttpUrlSink;
  sinkKind: string;
  sinkLine: number;
  stage: NodeAxiosPrototypeGadgetStage;
}

function nodeAxiosPrototypeGadgetStage(
  version: string,
): NodeAxiosPrototypeGadgetStage | undefined {
  const parts = version.split(".").map(Number);
  if (parts.length !== 3 || parts.some((part) => !Number.isSafeInteger(part))) {
    return undefined;
  }
  const [major, minor, patch] = parts as [number, number, number];
  if (
    (major === 0 &&
      (minor > 19 || minor === 19) &&
      (minor < 31 || (minor === 31 && patch < 1))) ||
    (major === 1 && (minor < 15 || (minor === 15 && patch < 2)))
  ) {
    return "direct-prototype-gadget";
  }
  if (
    (major === 0 &&
      (minor > 31 || (minor === 31 && patch >= 1)) &&
      minor < 33) ||
    (major === 1 && (minor > 15 || (minor === 15 && patch >= 2)) && minor < 18)
  ) {
    return "interceptor-proxy-gadget";
  }
  return undefined;
}

function nodeAxiosPrototypePollutionCanSupplyObject(
  framework: NonNullable<ResidualRiskRecord["frameworkModel"]>,
): boolean {
  return (
    framework.id === "node-http-prototype-merge" ||
    framework.id === "node-http-js-toml-prototype-pollution" ||
    framework.id === "node-http-flat-unflatten-prototype-pollution" ||
    (framework.id === "node-http-dset-prototype-pollution" &&
      framework.sink.kind.endsWith("vulnerable-dset-merge-value"))
  );
}

function nodeAxiosOwnProxyDisabledControls(
  lines: readonly string[],
  sink: NodeHttpUrlSink,
): Array<{ kind: string; line: number }> {
  return nodeAxiosConfigurationControls(lines, sink, [
    {
      kind: "own-axios-proxy-disabled",
      expression: /(?:^|[{,])\s*(?:proxy|["']proxy["'])\s*:\s*false\b/u,
    },
  ]);
}

function nodeAxiosInterceptorReturnExpression(
  callback: string,
): { parameter: string; value: string } | undefined {
  const arrow =
    /^\s*(?:async\s+)?(?:\(\s*([A-Za-z_$][\w$]*)\s*\)|([A-Za-z_$][\w$]*))\s*=>\s*([\s\S]+)$/u.exec(
      callback,
    );
  if (arrow !== null) {
    const parameter = arrow[1] ?? arrow[2];
    let value = arrow[3]?.trim() ?? "";
    if (parameter === undefined || value === "") return undefined;
    if (value.startsWith("{")) {
      const returned = /\breturn\s+([\s\S]+?);?\s*\}\s*$/u.exec(value)?.[1];
      if (returned === undefined) return undefined;
      value = returned.trim();
    }
    while (value.startsWith("(") && value.endsWith(")")) {
      const close = matchingCallParenthesis(value, 0);
      if (close !== value.length - 1) break;
      value = value.slice(1, -1).trim();
    }
    return { parameter, value };
  }
  const classic =
    /^\s*(?:async\s+)?function(?:\s+[A-Za-z_$][\w$]*)?\s*\(\s*([A-Za-z_$][\w$]*)\s*\)\s*\{([\s\S]+)\}\s*$/u.exec(
      callback,
    );
  if (classic?.[1] === undefined || classic[2] === undefined) return undefined;
  const returned = /\breturn\s+([\s\S]+?);?\s*$/u.exec(classic[2])?.[1];
  return returned === undefined
    ? undefined
    : { parameter: classic[1], value: returned.trim() };
}

function nodeAxiosPlainObjectCopy(
  returnValue: string,
  parameter: string,
): { rematerializes: boolean; ownsProxyFalse: boolean } {
  const escapedParameter = escapeRegularExpression(parameter);
  const object = javascriptCompositePrefix(returnValue, "{", "}");
  if (object !== undefined && object.length === returnValue.trim().length) {
    const entries = javascriptDelimitedEntries(object.slice(1, -1));
    const rematerializes = entries.some((entry) =>
      new RegExp(`^\.\.\.\s*${escapedParameter}\s*$`, "u").test(entry.value),
    );
    const proxy = javascriptObjectPropertyValue(object, "proxy");
    return {
      rematerializes,
      ownsProxyFalse: /^false$/u.test(proxy?.trim() ?? ""),
    };
  }
  const assign = /^Object\s*\.\s*assign\s*\(([\s\S]*)\)\s*$/u.exec(
    returnValue.trim(),
  );
  if (assign?.[1] === undefined) {
    return { rematerializes: false, ownsProxyFalse: false };
  }
  const arguments_ = splitJavascriptArguments(assign[1]);
  const target = arguments_[0]?.trim() ?? "";
  const normalTarget =
    /^\{\s*\}$/u.test(target) ||
    /^Object\s*\.\s*create\s*\(\s*Object\s*\.\s*prototype\s*\)$/u.test(target);
  const rematerializes =
    normalTarget &&
    arguments_
      .slice(1)
      .some((argument) =>
        new RegExp(`^${escapedParameter}$`, "u").test(argument.trim()),
      );
  const ownsProxyFalse = arguments_.slice(1).some((argument) => {
    const proxy = javascriptObjectPropertyValue(argument, "proxy");
    return /^false$/u.test(proxy?.trim() ?? "");
  });
  return { rematerializes, ownsProxyFalse };
}

function nodeAxiosRematerializingInterceptorLine(
  lines: readonly string[],
  receiver: string,
  beforeLine: number,
): number | undefined {
  const callee = new RegExp(
    `\\b${escapeRegularExpression(receiver)}\\s*\\.\\s*interceptors\\s*\\.\\s*request\\s*\\.\\s*use\\s*\\(`,
    "u",
  );
  let selected: number | undefined;
  for (let line = 1; line < beforeLine; line += 1) {
    const arguments_ = javascriptCallArgumentsAtLine(lines, line, callee);
    const callbackExpression = arguments_?.[0]?.trim();
    if (callbackExpression === undefined || callbackExpression === "") continue;
    const callback = resolveJavascriptExpression(
      lines,
      callbackExpression,
      line,
    );
    if (callback === undefined) continue;
    const returned = nodeAxiosInterceptorReturnExpression(callback.value);
    if (returned === undefined) continue;
    const copy = nodeAxiosPlainObjectCopy(returned.value, returned.parameter);
    if (copy.rematerializes && !copy.ownsProxyFalse) selected = line;
  }
  return selected;
}

function nodeAxiosPrototypeGadgetUses(
  files: readonly SourceFileSnapshot[],
): NodeAxiosPrototypeGadgetUse[] {
  const uses: NodeAxiosPrototypeGadgetUse[] = [];
  for (const file of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path) ||
      !/["']axios["']/u.test(file.text)
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(files, file.path, "axios");
    if (dependency === undefined) continue;
    const stage = nodeAxiosPrototypeGadgetStage(dependency.version);
    if (stage === undefined) continue;
    const bindings = javascriptAxiosBindings(file.lines);
    const structuralLines = javascriptStructuralLines(file.lines);
    for (const [receiver, binding] of bindings) {
      const call = new RegExp(
        `\\b${escapeRegularExpression(receiver)}\\s*(?:\\.\\s*(?:delete|get|head|options|patch|post|put|request))?\\s*(?:<[^;(){}]+>)?\\s*\\(`,
        "u",
      );
      for (let index = 0; index < structuralLines.length; index += 1) {
        const sinkLine = index + 1;
        if (
          sinkLine <= binding.declarationLine ||
          !call.test(structuralLines[index] ?? "")
        ) {
          continue;
        }
        const sink = nodeAxiosUrlArgument(file.lines, sinkLine);
        if (
          sink?.axiosReceiver !== receiver ||
          javascriptAxiosReceiverShadowedInExport(
            file.lines,
            sinkLine,
            receiver,
          )
        ) {
          continue;
        }
        const ownProxyDisabled = nodeAxiosOwnProxyDisabledControls(
          file.lines,
          sink,
        );
        const interceptorLine =
          stage === "interceptor-proxy-gadget"
            ? nodeAxiosRematerializingInterceptorLine(
                file.lines,
                receiver,
                sinkLine,
              )
            : undefined;
        if (
          stage === "interceptor-proxy-gadget" &&
          (interceptorLine === undefined || ownProxyDisabled.length > 0)
        ) {
          continue;
        }
        const lockResolved = dependency.proof === "npm-lockfile";
        uses.push({
          dependency,
          file,
          ...(interceptorLine === undefined ? {} : { interceptorLine }),
          ownProxyDisabled,
          receiver,
          sink,
          sinkKind: `${lockResolved ? "lock-resolved-" : ""}vulnerable-axios-${stage}`,
          sinkLine,
          stage,
        });
        if (uses.length >= MAX_FRAMEWORK_CROSS_FILE_RECORDS) return uses;
      }
    }
  }
  return uses;
}

function nodeAxiosPrototypeGadgetChainRecords(
  files: readonly SourceFileSnapshot[],
  records: readonly ResidualRiskRecord[],
): ResidualRiskRecord[] {
  const filesByPath = new Map(files.map((file) => [file.path, file]));
  const uses = nodeAxiosPrototypeGadgetUses(files);
  if (uses.length === 0) return [];
  const specialized: ResidualRiskRecord[] = [];
  const emitted = new Set<string>();
  for (const record of records) {
    const framework = record.frameworkModel;
    if (
      framework === undefined ||
      !nodeAxiosPrototypePollutionCanSupplyObject(framework) ||
      javascriptTestOrExamplePath(framework.sink.path)
    ) {
      continue;
    }
    const sourceBoundary = nodeRuntimeDependency(
      files,
      framework.sink.path,
      "axios",
    );
    if (sourceBoundary === undefined) continue;
    for (const use of uses) {
      if (
        use.dependency.manifestPath !== sourceBoundary.manifestPath ||
        use.dependency.version !== sourceBoundary.version ||
        use.dependency.proof !== sourceBoundary.proof
      ) {
        continue;
      }
      const key = [
        framework.source.path,
        framework.source.line,
        framework.sink.path,
        framework.sink.line,
        use.file.path,
        use.sinkLine,
        use.stage,
      ].join("\0");
      if (emitted.has(key)) continue;
      emitted.add(key);
      const startLine = Math.max(1, use.sinkLine - CONTEXT_LINES_BEFORE);
      const endLine = Math.min(
        use.file.lines.length,
        use.sinkLine + CONTEXT_LINES_AFTER,
      );
      const sourceFile = filesByPath.get(framework.source.path);
      const sourceStart = Math.max(1, framework.source.line - 2);
      const sourceEnd = Math.min(
        sourceFile?.lines.length ?? framework.source.line,
        framework.source.line + 2,
      );
      const candidateControls = [
        ...framework.candidateControls,
        ...use.ownProxyDisabled.map((control) => ({
          ...control,
          path: use.file.path,
        })),
      ].filter(
        (control, index, all) =>
          all.findIndex(
            (candidate) =>
              candidate.kind === control.kind &&
              candidate.path === control.path &&
              candidate.line === control.line,
          ) === index,
      );
      specialized.push({
        path: use.file.path,
        line: use.sinkLine,
        categories: [
          "framework-dataflow:node-http-axios-prototype-gadget-chain",
          "framework-cross-component-attack-chain",
          `modeled-source:${framework.source.kind}`,
          `modeled-state-write:${framework.sink.kind}`,
          `modeled-sink:${use.sinkKind}`,
          ...candidateControls.map(
            (control) => `candidate-control:${control.kind}`,
          ),
        ],
        priority: 124,
        startLine,
        endLine,
        excerpt: sourceExcerpt(use.file.lines, startLine, endLine),
        sourceExcerpt:
          sourceFile === undefined
            ? record.sourceExcerpt
            : sourceExcerpt(sourceFile.lines, sourceStart, sourceEnd),
        frameworkModel: {
          schemaVersion: "1.2",
          id: "node-http-axios-prototype-gadget-chain",
          language: "javascript-typescript",
          scope: framework.scope,
          source: framework.source,
          sink: {
            kind: use.sinkKind,
            path: use.file.path,
            line: use.sinkLine,
            cweIds: ["CWE-1321", "CWE-441"],
          },
          propagators: [
            ...framework.propagators,
            {
              kind: "prototype-pollution-state-write",
              path: framework.sink.path,
              line: framework.sink.line,
              symbol: framework.sink.kind,
            },
            {
              kind: "axios-runtime-dependency",
              path: use.dependency.manifestPath,
              line: use.dependency.line,
              symbol: `axios@${use.dependency.version}:${use.dependency.proof}`,
            },
            ...(use.interceptorLine === undefined
              ? []
              : [
                  {
                    kind: "axios-request-interceptor-rematerialization",
                    path: use.file.path,
                    line: use.interceptorLine,
                    symbol: use.receiver,
                  },
                ]),
            {
              kind: "shared-object-prototype-state",
              path: use.file.path,
              line: use.sinkLine,
              symbol: "Object.prototype.proxy",
            },
          ],
          candidateControls,
        },
      });
      if (specialized.length >= MAX_FRAMEWORK_CROSS_FILE_RECORDS) {
        return specialized;
      }
    }
  }
  return specialized;
}

function nodeAxiosConsolidatedPrototypeGadgetRecords(
  records: readonly ResidualRiskRecord[],
): ResidualRiskRecord[] {
  const superseded = new Set<string>();
  for (const record of records) {
    const framework = record.frameworkModel;
    if (framework?.id !== "node-http-axios-prototype-gadget-chain") continue;
    for (const propagator of framework.propagators) {
      if (propagator.kind !== "prototype-pollution-state-write") continue;
      superseded.add(
        [
          framework.source.path,
          framework.source.line,
          propagator.path,
          propagator.line,
          propagator.symbol ?? "",
        ].join("\0"),
      );
    }
  }
  if (superseded.size === 0) return [...records];
  return records.filter((record) => {
    const framework = record.frameworkModel;
    if (framework === undefined) return true;
    return !superseded.has(
      [
        framework.source.path,
        framework.source.line,
        framework.sink.path,
        framework.sink.line,
        framework.sink.kind,
      ].join("\0"),
    );
  });
}

function nodeIpv6TransitionIncompleteGuardRecords(
  files: readonly SourceFileSnapshot[],
  records: readonly ResidualRiskRecord[],
): ResidualRiskRecord[] {
  const filesByPath = new Map(files.map((file) => [file.path, file]));
  const emitted = new Set<string>();
  const specialized: ResidualRiskRecord[] = [];
  for (const record of records) {
    const framework = record.frameworkModel;
    if (framework?.id !== "node-http-ssrf") continue;
    const sinkFile = filesByPath.get(framework.sink.path);
    if (
      sinkFile === undefined ||
      !JAVASCRIPT_EXTENSIONS.has(sinkFile.extension) ||
      javascriptTestOrExamplePath(sinkFile.path)
    ) {
      continue;
    }
    const sink =
      nodeNativeHttpUrlArgument(sinkFile.lines, framework.sink.line) ??
      nodeHttpUrlSink(sinkFile.lines, framework.sink.line);
    if (sink?.urlExpression === undefined) continue;
    const wrapper = exportedJavascriptFunctions(sinkFile.lines).find(
      (candidate) =>
        framework.sink.line >= candidate.startLine &&
        framework.sink.line <= candidate.endLine,
    );
    if (wrapper === undefined) continue;
    const guard = nodeIpv4OnlyHostGuard(
      sinkFile.lines,
      wrapper,
      framework.sink.line,
      sink.urlExpression,
    );
    if (guard === undefined) continue;
    const key = `${framework.source.path}\0${framework.source.line}\0${framework.sink.path}\0${framework.sink.line}`;
    if (emitted.has(key)) continue;
    emitted.add(key);
    specialized.push({
      ...record,
      categories: [
        "framework-dataflow:node-ssrf-ipv6-transition-incomplete-guard",
        `modeled-source:${framework.source.kind}`,
        `modeled-sink:${framework.sink.kind}`,
        "broken-control:ipv4-only-private-address-denylist",
      ],
      priority: Math.max(record.priority, 120),
      frameworkModel: {
        ...framework,
        id: "node-ssrf-ipv6-transition-incomplete-guard",
        sink: { ...framework.sink, cweIds: ["CWE-918", "CWE-1389"] },
        candidateControls: [
          ...framework.candidateControls.filter(
            (control) =>
              control.kind !== "network-address-validation-or-pinning",
          ),
          {
            kind: "incomplete-ipv6-transition-address-guard",
            path: sinkFile.path,
            line: guard.line,
          },
        ].filter(
          (control, index, all) =>
            all.findIndex(
              (candidate) =>
                candidate.kind === control.kind &&
                candidate.path === control.path &&
                candidate.line === control.line,
            ) === index,
        ),
      },
    });
  }
  return specialized;
}

interface NodeIpAddressBinding {
  kind: "direct" | "receiver";
  local: string;
  line: number;
}

function nodeIpAddressVersionIsVulnerable(version: string): boolean {
  const parts = version.split(".").map(Number);
  if (parts.length !== 3 || parts.some((part) => !Number.isSafeInteger(part))) {
    return false;
  }
  const [major, minor, patch] = parts as [number, number, number];
  return (
    (major > 3 || (major === 3 && minor >= 2)) &&
    (major < 10 ||
      (major === 10 && (minor < 3 || (minor === 3 && patch === 0))))
  );
}

function nodeIpAddressLeadingZeroGuard(
  lines: readonly string[],
  wrapper: ExportedJavascriptFunction,
  sinkLine: number,
  sinkExpression: string,
  version: string,
): { line: number; method: string } | undefined {
  const codeLines = javascriptCodeLinesWithoutComments(lines);
  const structuralLines = javascriptStructuralLines(lines);
  const aliases = new Set(
    javascriptExpressionIdentifiers(sinkExpression).filter(
      (identifier) =>
        !["fetch", "get", "got", "http", "https", "request", "undici"].includes(
          identifier,
        ),
    ),
  );
  if (aliases.size === 0) return undefined;
  for (
    let index = wrapper.startLine - 1;
    index < Math.min(sinkLine - 1, wrapper.endLine);
    index += 1
  ) {
    const assignment =
      /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*([\s\S]+)$/u.exec(
        structuralLines[index] ?? "",
      );
    if (
      assignment?.[1] !== undefined &&
      assignment[2] !== undefined &&
      [...aliases].some((identifier) =>
        lineReferencesIdentifier(assignment[2]!, identifier),
      ) &&
      /\b(?:host|hostname|new\s+URL|parse)\b|\.\s*(?:host|hostname)\b/iu.test(
        assignment[2],
      )
    ) {
      aliases.add(assignment[1]);
    }
  }
  for (
    let index = wrapper.startLine - 1;
    index < Math.min(sinkLine - 1, wrapper.endLine);
    index += 1
  ) {
    const code = codeLines[index] ?? "";
    if (
      !code.includes("^0\\d") ||
      ![...aliases].some((identifier) =>
        lineReferencesIdentifier(code, identifier),
      )
    ) {
      continue;
    }
    const rejectionWindow = codeLines
      .slice(index, Math.min(index + 5, sinkLine - 1))
      .join("\n");
    if (/\b(?:throw|return)\b/u.test(rejectionWindow)) return undefined;
  }

  const bindings: NodeIpAddressBinding[] = [];
  for (const imported of importedJavascriptSymbols(lines)) {
    if (
      imported.moduleSpecifier === "ip-address" &&
      imported.imported === "Address4"
    ) {
      bindings.push({
        kind: "direct",
        local: imported.local,
        line: imported.line,
      });
    }
  }
  for (let index = 0; index < codeLines.length; index += 1) {
    const code = codeLines[index] ?? "";
    const receiver =
      /^\s*import\s+\*\s+as\s+([A-Za-z_$][\w$]*)\s+from\s+['"]ip-address['"]/u.exec(
        code,
      ) ??
      /^\s*import\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*['"]ip-address['"]\s*\)/u.exec(
        code,
      ) ??
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*['"]ip-address['"]\s*\)/u.exec(
        code,
      );
    const destructured =
      /^\s*(?:const|let|var)\s*\{\s*Address4(?:\s*:\s*([A-Za-z_$][\w$]*))?\s*\}\s*=\s*require\s*\(\s*['"]ip-address['"]\s*\)/u.exec(
        code,
      );
    if (receiver?.[1] !== undefined) {
      bindings.push({ kind: "receiver", local: receiver[1], line: index + 1 });
    }
    if (destructured !== null) {
      bindings.push({
        kind: "direct",
        local: destructured[1] ?? "Address4",
        line: index + 1,
      });
    }
  }

  const modernClassifiers =
    /\.\s*(isPrivate|isLoopback|isLinkLocal|isCGNAT)\s*\(\s*\)/u;
  const versionParts = version.split(".").map(Number);
  const hasModernClassifiers =
    (versionParts[0] ?? 0) > 10 ||
    ((versionParts[0] ?? 0) === 10 && (versionParts[1] ?? 0) >= 2);
  for (const binding of bindings) {
    if (
      binding.line >= sinkLine ||
      javascriptIdentifierReassignedBetween(
        lines,
        binding.local,
        binding.line,
        sinkLine,
      )
    ) {
      continue;
    }
    const escaped = escapeRegularExpression(binding.local);
    const constructors =
      binding.kind === "direct"
        ? [`${escaped}`]
        : [
            `${escaped}\\s*\\.\\s*Address4`,
            `${escaped}\\s*\\.\\s*v4\\s*\\.\\s*Address`,
          ];
    for (const constructor of constructors) {
      const addressAliases = new Set<string>();
      for (
        let index = wrapper.startLine - 1;
        index < Math.min(sinkLine - 1, wrapper.endLine);
        index += 1
      ) {
        const structural = structuralLines[index] ?? "";
        const declaration = new RegExp(
          `\\b(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*new\\s+${constructor}\\s*\\(([^)]*)\\)`,
          "u",
        ).exec(structural);
        if (
          declaration?.[1] !== undefined &&
          declaration[2] !== undefined &&
          [...aliases].some((identifier) =>
            lineReferencesIdentifier(declaration[2]!, identifier),
          )
        ) {
          addressAliases.add(declaration[1]);
        }
        if (!/\bif\s*\(/u.test(structural)) continue;
        const window = structuralLines
          .slice(index, Math.min(index + 5, sinkLine - 1))
          .join("\n");
        const codeWindow = codeLines
          .slice(index, Math.min(index + 5, sinkLine - 1))
          .join("\n");
        if (!/\b(?:throw|return)\b/u.test(window)) continue;
        const inlineRemote = [...aliases].some((identifier) =>
          new RegExp(
            `new\\s+${constructor}\\s*\\([^)]*\\b${escapeRegularExpression(identifier)}\\b[^)]*\\)`,
            "u",
          ).test(window),
        );
        const addressReference = [...addressAliases].some((identifier) =>
          lineReferencesIdentifier(window, identifier),
        );
        if (!inlineRemote && !addressReference) continue;
        const modern = hasModernClassifiers
          ? modernClassifiers.exec(window)?.[1]
          : undefined;
        if (modern !== undefined) return { line: index + 1, method: modern };
        if (
          /\.\s*isInSubnet\s*\(/u.test(window) &&
          /10\.0\.0\.0\s*\/\s*8/u.test(codeWindow)
        ) {
          return { line: index + 1, method: "isInSubnet" };
        }
      }
    }
  }
  return undefined;
}

function nodeIpAddressLeadingZeroSsrfRecords(
  files: readonly SourceFileSnapshot[],
  records: readonly ResidualRiskRecord[],
): ResidualRiskRecord[] {
  const filesByPath = new Map(files.map((file) => [file.path, file]));
  const emitted = new Set<string>();
  const specialized: ResidualRiskRecord[] = [];
  for (const record of records) {
    const framework = record.frameworkModel;
    if (framework?.id !== "node-http-ssrf") continue;
    const sinkFile = filesByPath.get(framework.sink.path);
    if (
      sinkFile === undefined ||
      !JAVASCRIPT_EXTENSIONS.has(sinkFile.extension) ||
      javascriptTestOrExamplePath(sinkFile.path)
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(
      files,
      sinkFile.path,
      "ip-address",
    );
    if (
      dependency === undefined ||
      !nodeIpAddressVersionIsVulnerable(dependency.version)
    ) {
      continue;
    }
    const sink =
      nodeNativeHttpUrlArgument(sinkFile.lines, framework.sink.line) ??
      nodeHttpUrlSink(sinkFile.lines, framework.sink.line);
    if (sink?.urlExpression === undefined) continue;
    const wrapper = exportedJavascriptFunctions(sinkFile.lines).find(
      (candidate) =>
        framework.sink.line >= candidate.startLine &&
        framework.sink.line <= candidate.endLine,
    );
    if (wrapper === undefined) continue;
    const guard = nodeIpAddressLeadingZeroGuard(
      sinkFile.lines,
      wrapper,
      framework.sink.line,
      sink.urlExpression,
      dependency.version,
    );
    if (guard === undefined) continue;
    const key = `${framework.source.path}\0${framework.source.line}\0${framework.sink.path}\0${framework.sink.line}`;
    if (emitted.has(key)) continue;
    emitted.add(key);
    specialized.push({
      ...record,
      categories: [
        "framework-dataflow:node-ssrf-ip-address-leading-zero-guard-bypass",
        `modeled-source:${framework.source.kind}`,
        `modeled-sink:${framework.sink.kind}`,
        "broken-control:decimal-octal-ipv4-parser-disagreement",
      ],
      priority: Math.max(record.priority, 121),
      frameworkModel: {
        ...framework,
        id: "node-ssrf-ip-address-leading-zero-guard-bypass",
        sink: { ...framework.sink, cweIds: ["CWE-918", "CWE-20"] },
        propagators: [
          ...framework.propagators,
          {
            kind: "ip-address-runtime-dependency",
            path: dependency.manifestPath,
            line: dependency.line,
            symbol: `ip-address@${dependency.version}:${dependency.proof}`,
          },
        ],
        candidateControls: [
          ...framework.candidateControls.filter(
            (control) =>
              control.kind !== "network-address-validation-or-pinning",
          ),
          {
            kind: `vulnerable-ip-address-leading-zero-${guard.method}-guard`,
            path: sinkFile.path,
            line: guard.line,
          },
        ],
      },
    });
  }
  return specialized;
}

type NodeFastUriHostPolicyCause = "authority-introducer" | "literal-backslash";

interface NodeFastUriBinding {
  kind: "direct" | "receiver";
  local: string;
  member: "normalize" | "parse" | "resolve";
  line: number;
}

interface NodeFastUriGuard {
  cause: NodeFastUriHostPolicyCause;
  line: number;
}

function nodeFastUriVersionIsVulnerable(
  version: string,
  cause: NodeFastUriHostPolicyCause,
): boolean {
  const parts = version.split(".").map(Number);
  if (parts.length !== 3 || parts.some((part) => !Number.isSafeInteger(part))) {
    return false;
  }
  const [major, minor, patch] = parts as [number, number, number];
  if (cause === "literal-backslash") {
    return (
      (major === 2 &&
        (minor > 3 || (minor === 3 && patch >= 1)) &&
        (minor < 4 || (minor === 4 && patch <= 2))) ||
      (major === 3 && (minor < 1 || (minor === 1 && patch <= 3))) ||
      (major === 4 && (minor < 1 || (minor === 1 && patch === 0)))
    );
  }
  return (
    major < 2 ||
    (major === 2 && (minor < 4 || (minor === 4 && patch < 4))) ||
    (major === 3 && (minor < 1 || (minor === 1 && patch < 5))) ||
    (major === 4 && (minor < 1 || (minor === 1 && patch < 2)))
  );
}

function nodeFastUriBindings(lines: readonly string[]): NodeFastUriBinding[] {
  const bindings: NodeFastUriBinding[] = [];
  for (const imported of importedJavascriptSymbols(lines)) {
    if (
      imported.moduleSpecifier === "fast-uri" &&
      (imported.imported === "normalize" ||
        imported.imported === "parse" ||
        imported.imported === "resolve")
    ) {
      bindings.push({
        kind: "direct",
        local: imported.local,
        member: imported.imported,
        line: imported.line,
      });
    }
  }
  const codeLines = javascriptCodeLinesWithoutComments(lines);
  for (let index = 0; index < codeLines.length; index += 1) {
    const code = codeLines[index] ?? "";
    const receiver =
      /^\s*import\s+\*\s+as\s+([A-Za-z_$][\w$]*)\s+from\s+['"]fast-uri['"]/u.exec(
        code,
      ) ??
      /^\s*import\s+([A-Za-z_$][\w$]*)\s+from\s+['"]fast-uri['"]/u.exec(code) ??
      /^\s*import\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*['"]fast-uri['"]\s*\)/u.exec(
        code,
      ) ??
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*['"]fast-uri['"]\s*\)/u.exec(
        code,
      );
    if (receiver?.[1] === undefined) continue;
    for (const member of ["normalize", "parse", "resolve"] as const) {
      bindings.push({
        kind: "receiver",
        local: receiver[1],
        member,
        line: index + 1,
      });
    }
  }
  return bindings;
}

function nodeFastUriCallArguments(
  structural: string,
  binding: NodeFastUriBinding,
): string[] | undefined {
  const escaped = escapeRegularExpression(binding.local);
  const expression =
    binding.kind === "direct"
      ? new RegExp(`\\b${escaped}\\s*\\(`, "u")
      : new RegExp(`\\b${escaped}\\s*\\.\\s*${binding.member}\\s*\\(`, "u");
  const call = expression.exec(structural);
  if (call?.index === undefined) return undefined;
  const open = structural.indexOf("(", call.index);
  const close = matchingCallParenthesis(structural, open);
  if (open < 0 || close < 0) return undefined;
  return splitJavascriptArguments(structural.slice(open + 1, close)).map(
    (argument) => argument.trim(),
  );
}

function nodeJavascriptExpressionKey(expression: string): string {
  return javascriptStructuralLines(expression.split(/\r?\n/u))
    .join("")
    .replace(/\s+/gu, "");
}

function nodeStaticStringValue(
  lines: readonly string[],
  expression: string,
  beforeLine: number,
): string | undefined {
  let value = expression.trim();
  const identifier = /^([A-Za-z_$][\w$]*)$/u.exec(value)?.[1];
  if (identifier !== undefined) {
    const initializer = javascriptVariableInitializer(
      lines,
      identifier,
      beforeLine,
    );
    if (initializer === undefined) return undefined;
    value = initializer.value.trim();
  }
  const literal =
    /^(?:"([^"\\]*(?:\\.[^"\\]*)*)"|'([^'\\]*(?:\\.[^'\\]*)*)')$/u.exec(value);
  const raw = literal?.[1] ?? literal?.[2];
  return raw === undefined || /\\/u.test(raw) ? undefined : raw;
}

function nodeStaticUrlHostname(
  lines: readonly string[],
  expression: string,
  beforeLine: number,
): string | undefined {
  const raw = nodeStaticStringValue(lines, expression, beforeLine);
  if (raw === undefined) return undefined;
  try {
    const parsed = new URL(raw);
    return parsed.protocol === "http:" || parsed.protocol === "https:"
      ? parsed.hostname
      : undefined;
  } catch {
    return undefined;
  }
}

function nodeFastUriFailClosedAllowlistGuard(
  structuralLines: readonly string[],
  codeLines: readonly string[],
  hostExpression: string,
  expectedHost: string | undefined,
  startLine: number,
  sinkLine: number,
): number | undefined {
  const escapedExpression = escapeRegularExpression(
    nodeJavascriptExpressionKey(hostExpression),
  );
  for (
    let index = startLine - 1;
    index < Math.min(sinkLine - 1, structuralLines.length);
    index += 1
  ) {
    const code = (codeLines[index] ?? "").replace(/\s+/gu, "");
    const comparison = new RegExp(
      `(?:${escapedExpression}(?:!==|!=)(["'])([^"']+)\\1|(["'])([^"']+)\\3(?:!==|!=)${escapedExpression})`,
      "u",
    ).exec(code);
    const comparedHost = comparison?.[2] ?? comparison?.[4];
    if (
      comparedHost === undefined ||
      (expectedHost !== undefined && comparedHost !== expectedHost)
    ) {
      continue;
    }
    const window = structuralLines
      .slice(index, Math.min(index + 5, sinkLine - 1))
      .join("\n");
    const codeWindow = codeLines
      .slice(index, Math.min(index + 5, sinkLine - 1))
      .join("\n");
    if (/\bif\s*\(/u.test(window) && /\b(?:throw|return)\b/u.test(codeWindow)) {
      return index + 1;
    }
  }
  return undefined;
}

function nodeWhatwgResolutionArguments(
  expression: string,
): [string, string] | undefined {
  const structural = javascriptStructuralLines(expression.split(/\r?\n/u)).join(
    "\n",
  );
  const call = /\bnew\s+URL\s*\(/u.exec(structural);
  if (call?.index === undefined) return undefined;
  const open = structural.indexOf("(", call.index);
  const close = matchingCallParenthesis(structural, open);
  if (open < 0 || close < 0) return undefined;
  const arguments_ = splitJavascriptArguments(
    structural.slice(open + 1, close),
  ).map((argument) => argument.trim());
  return arguments_.length === 2 ? [arguments_[0]!, arguments_[1]!] : undefined;
}

function nodeFastUriHostPolicyGuard(
  lines: readonly string[],
  wrapper: ExportedJavascriptFunction,
  sinkLine: number,
  sinkExpression: string,
  version: string,
): NodeFastUriGuard | undefined {
  const remoteParameters = wrapper.parameters.filter((parameter) =>
    lineReferencesIdentifier(sinkExpression, parameter),
  );
  if (remoteParameters.length !== 1) return undefined;
  const remote = remoteParameters[0]!;
  const structuralLines = javascriptStructuralLines(lines);
  const codeLines = javascriptCodeLinesWithoutComments(lines);
  const bindings = nodeFastUriBindings(lines).filter(
    (binding) =>
      binding.line < sinkLine &&
      !javascriptIdentifierReassignedBetween(
        lines,
        binding.local,
        binding.line,
        sinkLine,
      ),
  );
  const parseBindings = bindings.filter(
    (binding) => binding.member === "parse",
  );

  const whatwgArguments = nodeWhatwgResolutionArguments(sinkExpression);
  if (
    whatwgArguments !== undefined &&
    lineReferencesIdentifier(whatwgArguments[0], remote) &&
    nodeFastUriVersionIsVulnerable(version, "authority-introducer")
  ) {
    const baseKey = nodeJavascriptExpressionKey(whatwgArguments[1]);
    const baseHost = nodeStaticUrlHostname(lines, whatwgArguments[1], sinkLine);
    if (baseHost !== undefined) {
      for (
        let index = wrapper.startLine - 1;
        index < sinkLine - 1;
        index += 1
      ) {
        const structural = structuralLines[index] ?? "";
        const declaration =
          /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*([\s\S]+)$/u.exec(
            structural,
          );
        if (declaration?.[1] === undefined || declaration[2] === undefined) {
          continue;
        }
        for (const resolveBinding of bindings.filter(
          (binding) => binding.member === "resolve",
        )) {
          const arguments_ = nodeFastUriCallArguments(
            declaration[2],
            resolveBinding,
          );
          if (
            arguments_?.length !== 2 ||
            nodeJavascriptExpressionKey(arguments_[0]!) !== baseKey ||
            !lineReferencesIdentifier(arguments_[1]!, remote)
          ) {
            continue;
          }
          const resolvedUrl = declaration[1];
          for (
            let parseIndex = index;
            parseIndex < sinkLine - 1;
            parseIndex += 1
          ) {
            const parseDeclaration =
              /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*([\s\S]+)$/u.exec(
                structuralLines[parseIndex] ?? "",
              );
            if (
              parseDeclaration?.[1] === undefined ||
              parseDeclaration[2] === undefined
            ) {
              continue;
            }
            for (const parseBinding of parseBindings) {
              const parseArguments = nodeFastUriCallArguments(
                parseDeclaration[2],
                parseBinding,
              );
              if (
                parseArguments?.length !== 1 ||
                !lineReferencesIdentifier(parseArguments[0]!, resolvedUrl)
              ) {
                continue;
              }
              const inlineHost = /\.\s*host\b/u.test(parseDeclaration[2]);
              const hostExpression = inlineHost
                ? parseDeclaration[1]
                : `${parseDeclaration[1]}.host`;
              const guardLine = nodeFastUriFailClosedAllowlistGuard(
                structuralLines,
                codeLines,
                hostExpression,
                baseHost,
                parseIndex + 1,
                sinkLine,
              );
              if (guardLine !== undefined) {
                return { cause: "authority-introducer", line: guardLine };
              }
            }
          }
        }
      }
    }
  }

  if (
    nodeJavascriptExpressionKey(sinkExpression) ===
      nodeJavascriptExpressionKey(remote) &&
    nodeFastUriVersionIsVulnerable(version, "literal-backslash")
  ) {
    for (let index = wrapper.startLine - 1; index < sinkLine - 1; index += 1) {
      const declaration =
        /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*([\s\S]+)$/u.exec(
          structuralLines[index] ?? "",
        );
      if (declaration?.[1] === undefined || declaration[2] === undefined) {
        continue;
      }
      for (const parseBinding of parseBindings) {
        const parseArguments = nodeFastUriCallArguments(
          declaration[2],
          parseBinding,
        );
        if (
          parseArguments?.length !== 1 ||
          !lineReferencesIdentifier(parseArguments[0]!, remote)
        ) {
          continue;
        }
        const inlineHost = /\.\s*host\b/u.test(declaration[2]);
        const hostExpression = inlineHost
          ? declaration[1]
          : `${declaration[1]}.host`;
        const guardLine = nodeFastUriFailClosedAllowlistGuard(
          structuralLines,
          codeLines,
          hostExpression,
          undefined,
          index + 1,
          sinkLine,
        );
        if (guardLine !== undefined) {
          return { cause: "literal-backslash", line: guardLine };
        }
      }
    }
  }
  return undefined;
}

function nodeFastUriHostPolicyConfusionRecords(
  files: readonly SourceFileSnapshot[],
  records: readonly ResidualRiskRecord[],
): ResidualRiskRecord[] {
  const filesByPath = new Map(files.map((file) => [file.path, file]));
  const emitted = new Set<string>();
  const specialized: ResidualRiskRecord[] = [];
  for (const record of records) {
    const framework = record.frameworkModel;
    if (framework?.id !== "node-http-ssrf") continue;
    const sinkFile = filesByPath.get(framework.sink.path);
    if (
      sinkFile === undefined ||
      !JAVASCRIPT_EXTENSIONS.has(sinkFile.extension) ||
      javascriptTestOrExamplePath(sinkFile.path)
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(files, sinkFile.path, "fast-uri");
    if (dependency === undefined) continue;
    const sink =
      nodeNativeHttpUrlArgument(sinkFile.lines, framework.sink.line) ??
      nodeHttpUrlSink(sinkFile.lines, framework.sink.line);
    if (sink?.urlExpression === undefined) continue;
    const wrapper = exportedJavascriptFunctions(sinkFile.lines).find(
      (candidate) =>
        framework.sink.line >= candidate.startLine &&
        framework.sink.line <= candidate.endLine,
    );
    if (wrapper === undefined) continue;
    const guard = nodeFastUriHostPolicyGuard(
      sinkFile.lines,
      wrapper,
      framework.sink.line,
      sink.urlExpression,
      dependency.version,
    );
    if (guard === undefined) continue;
    const key = `${framework.source.path}\0${framework.source.line}\0${framework.sink.path}\0${framework.sink.line}`;
    if (emitted.has(key)) continue;
    emitted.add(key);
    specialized.push({
      ...record,
      categories: [
        "framework-dataflow:node-ssrf-fast-uri-host-policy-confusion",
        `modeled-source:${framework.source.kind}`,
        `modeled-sink:${framework.sink.kind}`,
        `broken-control:fast-uri-${guard.cause}-parser-disagreement`,
      ],
      priority: Math.max(record.priority, 122),
      frameworkModel: {
        ...framework,
        id: "node-ssrf-fast-uri-host-policy-confusion",
        sink: { ...framework.sink, cweIds: ["CWE-918", "CWE-436"] },
        propagators: [
          ...framework.propagators,
          {
            kind: "fast-uri-runtime-dependency",
            path: dependency.manifestPath,
            line: dependency.line,
            symbol: `fast-uri@${dependency.version}:${dependency.proof}:${guard.cause}`,
          },
        ],
        candidateControls: [
          ...framework.candidateControls.filter(
            (control) =>
              control.kind !== "network-address-validation-or-pinning",
          ),
          {
            kind: `vulnerable-fast-uri-${guard.cause}-host-guard`,
            path: sinkFile.path,
            line: guard.line,
          },
        ],
      },
    });
  }
  return specialized;
}

interface NodePathConstructionBinding {
  kind: "direct" | "receiver";
  local: string;
  member: "join" | "resolve";
  line: number;
}

interface NodeFastUriEncodedDotPathGuard {
  line: number;
  prefix: string;
}

function nodeFastUriEncodedDotVersionIsVulnerable(version: string): boolean {
  const parts = version.split(".").map(Number);
  if (parts.length !== 3 || parts.some((part) => !Number.isSafeInteger(part))) {
    return false;
  }
  const [major, minor, patch] = parts as [number, number, number];
  return (
    major < 2 ||
    (major === 2 && (minor < 4 || (minor === 4 && patch === 0))) ||
    (major === 3 && (minor < 1 || (minor === 1 && patch === 0)))
  );
}

function nodeFastUriExactCallArguments(
  expression: string,
  binding: NodeFastUriBinding,
): string[] | undefined {
  const structural = javascriptStructuralLines(expression.split(/\r?\n/u)).join(
    "\n",
  );
  const escaped = escapeRegularExpression(binding.local);
  const callExpression =
    binding.kind === "direct"
      ? new RegExp(`\\b${escaped}\\s*\\(`, "u")
      : new RegExp(`\\b${escaped}\\s*\\.\\s*${binding.member}\\s*\\(`, "u");
  const call = callExpression.exec(structural);
  if (
    call?.index === undefined ||
    structural.slice(0, call.index).trim() !== ""
  ) {
    return undefined;
  }
  const open = structural.indexOf("(", call.index);
  const close = matchingCallParenthesis(structural, open);
  if (open < 0 || close < 0 || structural.slice(close + 1).trim() !== "") {
    return undefined;
  }
  return splitJavascriptArguments(structural.slice(open + 1, close)).map(
    (argument) => argument.trim(),
  );
}

function nodePathConstructionBindings(
  lines: readonly string[],
): NodePathConstructionBinding[] {
  const bindings: NodePathConstructionBinding[] = [];
  for (const imported of importedJavascriptSymbols(lines)) {
    if (
      /^(?:node:)?path$/u.test(imported.moduleSpecifier) &&
      (imported.imported === "join" || imported.imported === "resolve")
    ) {
      bindings.push({
        kind: "direct",
        local: imported.local,
        member: imported.imported,
        line: imported.line,
      });
    }
  }
  const codeLines = javascriptCodeLinesWithoutComments(lines);
  for (let index = 0; index < codeLines.length; index += 1) {
    const code = codeLines[index] ?? "";
    const receiver =
      /^\s*import\s+\*\s+as\s+([A-Za-z_$][\w$]*)\s+from\s+['"](?:node:)?path['"]/u.exec(
        code,
      ) ??
      /^\s*import\s+([A-Za-z_$][\w$]*)\s+from\s+['"](?:node:)?path['"]/u.exec(
        code,
      ) ??
      /^\s*import\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*['"](?:node:)?path['"]\s*\)/u.exec(
        code,
      ) ??
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*['"](?:node:)?path['"]\s*\)/u.exec(
        code,
      );
    if (receiver?.[1] === undefined) continue;
    for (const member of ["join", "resolve"] as const) {
      bindings.push({
        kind: "receiver",
        local: receiver[1],
        member,
        line: index + 1,
      });
    }
  }
  return bindings;
}

function nodePathExactCallArguments(
  expression: string,
  binding: NodePathConstructionBinding,
): string[] | undefined {
  const structural = javascriptStructuralLines(expression.split(/\r?\n/u)).join(
    "\n",
  );
  const escaped = escapeRegularExpression(binding.local);
  const callExpression =
    binding.kind === "direct"
      ? new RegExp(`\\b${escaped}\\s*\\(`, "u")
      : new RegExp(`\\b${escaped}\\s*\\.\\s*${binding.member}\\s*\\(`, "u");
  const call = callExpression.exec(structural);
  if (
    call?.index === undefined ||
    structural.slice(0, call.index).trim() !== ""
  ) {
    return undefined;
  }
  const open = structural.indexOf("(", call.index);
  const close = matchingCallParenthesis(structural, open);
  if (open < 0 || close < 0 || structural.slice(close + 1).trim() !== "") {
    return undefined;
  }
  return splitJavascriptArguments(structural.slice(open + 1, close)).map(
    (argument) => argument.trim(),
  );
}

function nodeFastUriParsePathUsesNormalizedRemote(
  expression: string,
  remote: string,
  bindings: readonly NodeFastUriBinding[],
): boolean {
  const structural = javascriptStructuralLines(expression.split(/\r?\n/u)).join(
    "\n",
  );
  for (const parseBinding of bindings.filter(
    (binding) => binding.member === "parse",
  )) {
    const escaped = escapeRegularExpression(parseBinding.local);
    const callExpression =
      parseBinding.kind === "direct"
        ? new RegExp(`\\b${escaped}\\s*\\(`, "u")
        : new RegExp(`\\b${escaped}\\s*\\.\\s*parse\\s*\\(`, "u");
    const call = callExpression.exec(structural);
    if (call?.index === undefined) continue;
    const open = structural.indexOf("(", call.index);
    const close = matchingCallParenthesis(structural, open);
    if (
      open < 0 ||
      close < 0 ||
      !/^\s*\.\s*path\b/u.test(structural.slice(close + 1))
    ) {
      continue;
    }
    const parseArguments = splitJavascriptArguments(
      structural.slice(open + 1, close),
    ).map((argument) => argument.trim());
    if (parseArguments.length !== 1) continue;
    for (const normalizeBinding of bindings.filter(
      (binding) => binding.member === "normalize",
    )) {
      const normalizeArguments = nodeFastUriExactCallArguments(
        parseArguments[0]!,
        normalizeBinding,
      );
      if (
        normalizeArguments?.length === 1 &&
        nodeJavascriptExpressionKey(normalizeArguments[0]!) === remote
      ) {
        return true;
      }
    }
  }
  return false;
}

function nodeFastUriPublicPrefixGuard(
  lines: readonly string[],
  wrapper: ExportedJavascriptFunction,
  remote: string,
  sinkLine: number,
): NodeFastUriEncodedDotPathGuard | undefined {
  const codeLines = javascriptCodeLinesWithoutComments(lines);
  const escapedRemote = escapeRegularExpression(remote);
  const guardStart = new RegExp(
    `\\bif\\s*\\(\\s*!\\s*${escapedRemote}\\s*\\.\\s*startsWith\\s*\\(`,
    "u",
  );
  for (
    let index = wrapper.startLine - 1;
    index < Math.min(sinkLine - 1, codeLines.length);
    index += 1
  ) {
    const window = codeLines
      .slice(index, Math.min(index + 6, sinkLine))
      .join("\n");
    const guard = guardStart.exec(window);
    if (guard?.index === undefined) continue;
    const guardLine =
      index + (window.slice(0, guard.index).match(/\n/gu)?.length ?? 0) + 1;
    const open = window.indexOf("(", window.indexOf("startsWith", guard.index));
    const close = matchingCallParenthesis(window, open);
    if (open < 0 || close < 0) continue;
    const prefixArguments = splitJavascriptArguments(
      window.slice(open + 1, close),
    ).map((argument) => argument.trim());
    if (
      prefixArguments.length !== 1 ||
      !nodeFastUriGuardBranchFailsClosed(window.slice(close + 1))
    ) {
      continue;
    }
    const prefix = nodeStaticStringValue(lines, prefixArguments[0]!, guardLine);
    if (prefix === undefined) continue;
    try {
      const parsed = new URL(prefix);
      if (
        !["http:", "https:"].includes(parsed.protocol) ||
        parsed.username !== "" ||
        parsed.password !== "" ||
        parsed.search !== "" ||
        parsed.hash !== "" ||
        parsed.pathname === "/" ||
        !parsed.pathname.endsWith("/") ||
        parsed.href !== prefix
      ) {
        continue;
      }
    } catch {
      continue;
    }
    if (
      javascriptIdentifierReassignedBetween(lines, remote, guardLine, sinkLine)
    ) {
      return undefined;
    }
    return { line: guardLine, prefix };
  }
  return undefined;
}

function nodeFastUriGuardBranchFailsClosed(tail: string): boolean {
  let branch = tail.trimStart();
  if (!branch.startsWith(")")) return false;
  branch = branch.slice(1).trimStart();
  if (/^(?:throw|return)\b/u.test(branch)) return true;
  if (!branch.startsWith("{")) return false;
  let depth = 0;
  let close = -1;
  for (let index = 0; index < branch.length; index += 1) {
    if (branch[index] === "{") depth += 1;
    else if (branch[index] === "}") {
      depth -= 1;
      if (depth === 0) {
        close = index;
        break;
      }
    }
  }
  if (close < 0) return false;
  const body = branch.slice(1, close).trim();
  return /(?:^|[;\n])\s*(?:throw|return)\b[^{}]*;?\s*$/u.test(body);
}

function nodeFastUriEncodedDotPathGuard(
  lines: readonly string[],
  wrapper: ExportedJavascriptFunction,
  sinkLine: number,
  sinkExpressions: readonly string[],
): NodeFastUriEncodedDotPathGuard | undefined {
  const fastUriBindings = nodeFastUriBindings(lines).filter(
    (binding) =>
      binding.line < sinkLine &&
      !wrapper.parameters.includes(binding.local) &&
      !javascriptIdentifierReassignedBetween(
        lines,
        binding.local,
        binding.line,
        sinkLine,
      ),
  );
  if (
    !fastUriBindings.some((binding) => binding.member === "normalize") ||
    !fastUriBindings.some((binding) => binding.member === "parse")
  ) {
    return undefined;
  }
  const pathBindings = nodePathConstructionBindings(lines).filter(
    (binding) =>
      binding.line < sinkLine &&
      !wrapper.parameters.includes(binding.local) &&
      !javascriptIdentifierReassignedBetween(
        lines,
        binding.local,
        binding.line,
        sinkLine,
      ),
  );
  for (const remote of wrapper.parameters) {
    const guard = nodeFastUriPublicPrefixGuard(
      lines,
      wrapper,
      remote,
      sinkLine,
    );
    if (guard === undefined) continue;
    for (const sinkExpression of sinkExpressions) {
      for (const pathBinding of pathBindings) {
        const arguments_ = nodePathExactCallArguments(
          sinkExpression,
          pathBinding,
        );
        if (arguments_ === undefined || arguments_.length < 2) continue;
        const root = nodeStaticStringValue(lines, arguments_[0]!, sinkLine);
        if (root === undefined || root.trim() === "") continue;
        if (
          arguments_
            .slice(1)
            .some((argument) =>
              nodeFastUriParsePathUsesNormalizedRemote(
                argument,
                remote,
                fastUriBindings,
              ),
            )
        ) {
          return guard;
        }
      }
    }
  }
  return undefined;
}

function nodeFastUriEncodedDotPathRecords(
  files: readonly SourceFileSnapshot[],
  records: readonly ResidualRiskRecord[],
): ResidualRiskRecord[] {
  const filesByPath = new Map(files.map((file) => [file.path, file]));
  const emitted = new Set<string>();
  const specialized: ResidualRiskRecord[] = [];
  for (const record of records) {
    const framework = record.frameworkModel;
    if (framework?.id !== "node-http-path") continue;
    const sinkFile = filesByPath.get(framework.sink.path);
    if (
      sinkFile === undefined ||
      !JAVASCRIPT_EXTENSIONS.has(sinkFile.extension) ||
      javascriptTestOrExamplePath(sinkFile.path)
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(files, sinkFile.path, "fast-uri");
    if (
      dependency === undefined ||
      !nodeFastUriEncodedDotVersionIsVulnerable(dependency.version)
    ) {
      continue;
    }
    const sink = nodeFilesystemPathSink(sinkFile.lines, framework.sink.line);
    if (sink === undefined) continue;
    const wrapper = exportedJavascriptFunctions(sinkFile.lines).find(
      (candidate) =>
        framework.sink.line >= candidate.startLine &&
        framework.sink.line <= candidate.endLine,
    );
    if (wrapper === undefined) continue;
    const guard = nodeFastUriEncodedDotPathGuard(
      sinkFile.lines,
      wrapper,
      framework.sink.line,
      sink.expressions,
    );
    if (guard === undefined) continue;
    const key = `${framework.source.path}\0${framework.source.line}\0${framework.sink.path}\0${framework.sink.line}`;
    if (emitted.has(key)) continue;
    emitted.add(key);
    specialized.push({
      ...record,
      categories: [
        "framework-dataflow:node-path-fast-uri-encoded-dot-segment-policy-bypass",
        `modeled-source:${framework.source.kind}`,
        `modeled-sink:${framework.sink.kind}`,
        "broken-control:fast-uri-encoded-dot-segment-normalization",
      ],
      priority: Math.max(record.priority, 122),
      frameworkModel: {
        ...framework,
        id: "node-path-fast-uri-encoded-dot-segment-policy-bypass",
        sink: { ...framework.sink, cweIds: ["CWE-22"] },
        propagators: [
          ...framework.propagators,
          {
            kind: "fast-uri-runtime-dependency",
            path: dependency.manifestPath,
            line: dependency.line,
            symbol: `fast-uri@${dependency.version}:${dependency.proof}:encoded-dot-segment-normalization`,
          },
        ],
        candidateControls: [
          ...framework.candidateControls,
          {
            kind: "vulnerable-fast-uri-encoded-dot-segment-path-policy",
            path: sinkFile.path,
            line: guard.line,
          },
        ],
      },
    });
  }
  return specialized;
}

function javascriptTestOrExamplePath(path: string): boolean {
  return (
    /(?:^|\/)(?:__tests__|examples?|test|tests|tests-ts)(?:\/|$)/iu.test(
      path,
    ) || /\.(?:spec|test)\.[^./]+$/iu.test(path)
  );
}

function javaFileGetNamePathBoundaryRecords(
  files: readonly SourceFileSnapshot[],
  records: readonly ResidualRiskRecord[],
): ResidualRiskRecord[] {
  const filesByPath = new Map(files.map((file) => [file.path, file]));
  const projectGraph = javaBasenameProjectGraph(files);
  const packageTypes = javaPackageTypeIndex(files);
  const helperSummaries = javaFileBasenameHelperSummaries(
    files,
    packageTypes,
    projectGraph,
  );
  const emitted = new Set<string>();
  const specialized: ResidualRiskRecord[] = [];
  for (const record of records) {
    const framework = record.frameworkModel;
    if (framework?.id !== "spring-http-path") continue;
    const sinkFile = filesByPath.get(framework.sink.path);
    if (
      sinkFile?.extension !== ".java" ||
      javaTestOrExamplePath(sinkFile.path)
    ) {
      continue;
    }
    const boundary = javaFileGetNamePathBoundary(
      sinkFile,
      files,
      framework.sink.line,
      new Set(
        framework.propagators
          .filter(
            (propagator) =>
              propagator.kind === "wrapper-parameter" &&
              propagator.path === sinkFile.path,
          )
          .flatMap((propagator) =>
            propagator.symbol === undefined ? [] : [propagator.symbol],
          ),
      ),
      javaSamePackageTopLevelTypes(packageTypes, files, sinkFile, projectGraph),
      helperSummaries,
      projectGraph,
    );
    if (boundary === undefined) continue;
    const key = `${framework.source.path}\0${framework.source.line}\0${framework.sink.path}\0${framework.sink.line}`;
    if (emitted.has(key)) continue;
    emitted.add(key);
    specialized.push({
      ...record,
      categories: [
        "framework-dataflow:java-file-getname-path-boundary",
        `modeled-source:${framework.source.kind}`,
        `modeled-sink:${framework.sink.kind}`,
        "broken-control:java-io-file-basename-reduction",
        ...(boundary.parentRejectionLine === undefined
          ? []
          : ["candidate-control:parent-path-component-rejection"]),
      ],
      priority: Math.max(record.priority, 121),
      frameworkModel: {
        ...framework,
        id: "java-file-getname-path-boundary",
        candidateControls: [
          ...framework.candidateControls,
          {
            kind: "incomplete-java-io-file-getname-reduction",
            path: boundary.reductionPath,
            line: boundary.reductionLine,
          },
          ...(boundary.parentRejectionLine === undefined
            ? []
            : [
                {
                  kind: "parent-path-component-rejection",
                  path: sinkFile.path,
                  line: boundary.parentRejectionLine,
                },
              ]),
        ].filter(
          (control, index, all) =>
            all.findIndex(
              (candidate) =>
                candidate.kind === control.kind &&
                candidate.path === control.path &&
                candidate.line === control.line,
            ) === index,
        ),
      },
    });
  }
  return specialized;
}

function javaTestOrExamplePath(path: string): boolean {
  return (
    /(?:^|\/)(?:examples|test|tests)(?:\/|$)/iu.test(path) ||
    /(?:^|\/)src\/test(?:\/|$)/iu.test(path) ||
    /(?:Test|Tests)\.java$/u.test(path)
  );
}

function javaLexicalBlockContext(structuralLines: readonly string[]): {
  paths: string[];
  switchAncestors: boolean[];
} {
  const paths: string[] = [];
  const switchAncestors: boolean[] = [];
  const stack: Array<{ id: number; switchBlock: boolean }> = [];
  let nextBlock = 1;
  let word = "";
  let awaitingSwitchParenthesis = false;
  let switchParenthesisDepth: number | undefined;
  for (const line of structuralLines) {
    paths.push(stack.map(({ id }) => id).join("."));
    switchAncestors.push(stack.some(({ switchBlock }) => switchBlock));
    for (const character of line) {
      if (/[A-Za-z0-9_$]/u.test(character)) {
        word += character;
        continue;
      }
      if (word === "switch" && switchParenthesisDepth === undefined) {
        awaitingSwitchParenthesis = true;
      }
      word = "";
      if (character === "(") {
        if (awaitingSwitchParenthesis) {
          switchParenthesisDepth = 1;
          awaitingSwitchParenthesis = false;
        } else if (switchParenthesisDepth !== undefined) {
          switchParenthesisDepth += 1;
        }
      } else if (character === ")" && switchParenthesisDepth !== undefined) {
        switchParenthesisDepth = Math.max(0, switchParenthesisDepth - 1);
      }
      if (character === "{") {
        const switchBlock = switchParenthesisDepth !== undefined;
        stack.push({
          id: nextBlock,
          switchBlock,
        });
        nextBlock += 1;
        if (switchParenthesisDepth === 0) {
          switchParenthesisDepth = undefined;
        }
      } else if (character === "}") {
        stack.pop();
      } else if (character === ";" && switchParenthesisDepth === undefined) {
        awaitingSwitchParenthesis = false;
      }
    }
    if (word === "switch" && switchParenthesisDepth === undefined) {
      awaitingSwitchParenthesis = true;
    }
    word = "";
  }
  return { paths, switchAncestors };
}

function matchingStructuralBrace(value: string, open: number): number {
  if (open < 0 || value[open] !== "{") return -1;
  let depth = 0;
  for (let index = open; index < value.length; index += 1) {
    if (value[index] === "{") depth += 1;
    else if (value[index] === "}") {
      depth -= 1;
      if (depth === 0) return index;
    }
  }
  return -1;
}

function stripBalancedOuterParentheses(value: string): string {
  let result = value.trim();
  while (
    result.startsWith("(") &&
    matchingCallParenthesis(result, 0) === result.length - 1
  ) {
    result = result.slice(1, -1).trim();
  }
  return result;
}

function javaSimpleBranchCompletesAbruptly(
  branch: string,
  braced: boolean,
): boolean {
  const structural = cFamilyStructuralLines(branch.split(/\r?\n/u))
    .join("\n")
    .trim();
  if (!braced) {
    return /^(?:return\b[^;]*|throw\b[^;]+)\s*;/u.test(structural);
  }
  if (
    structural === "" ||
    /[{}]|->|\b(?:if|else|switch|try|catch|finally|for|while|do|synchronized)\b/u.test(
      structural,
    )
  ) {
    return false;
  }
  const statements = structural
    .split(";")
    .map((statement) => statement.trim())
    .filter((statement) => statement !== "");
  const finalStatement = statements.at(-1) ?? "";
  return /^(?:return\b|throw\b)/u.test(finalStatement);
}

function javaDominatingEqualityRejection(
  lines: readonly string[],
  structuralLines: readonly string[],
  startLine: number,
  sinkLine: number,
  identifiers: ReadonlySet<string>,
  rejectedValuePattern: string,
): number | undefined {
  const blockContext = javaLexicalBlockContext(structuralLines);
  const sinkIndex = sinkLine - 1;
  const identifierPattern = [...identifiers]
    .map((identifier) => escapeRegularExpression(identifier))
    .join("|");
  if (identifierPattern === "") return undefined;
  const equality = new RegExp(
    String.raw`^(?:(?:${identifierPattern})\s*\.\s*equals\s*\(\s*${rejectedValuePattern}\s*\)|${rejectedValuePattern}\s*\.\s*equals\s*\(\s*(?:${identifierPattern})\s*\))$`,
    "u",
  );

  for (
    let index = startLine;
    index < Math.min(sinkIndex, structuralLines.length);
    index += 1
  ) {
    const firstLine = structuralLines[index] ?? "";
    const ifMatch = /\bif\s*\(/u.exec(firstLine);
    if (
      ifMatch === null ||
      firstLine.slice(0, ifMatch.index).trim() !== "" ||
      blockContext.paths[index] !== blockContext.paths[sinkIndex] ||
      blockContext.switchAncestors[index] === true
    ) {
      continue;
    }
    const endIndex = Math.min(sinkIndex, index + 16);
    const rawWindow = lines.slice(index, endIndex).join("\n");
    const structuralWindow = structuralLines.slice(index, endIndex).join("\n");
    const structuralIf = /\bif\s*\(/u.exec(structuralWindow);
    if (structuralIf === null) continue;
    const open = structuralWindow.indexOf("(", structuralIf.index);
    const close = matchingCallParenthesis(structuralWindow, open);
    if (open < 0 || close < 0) continue;
    const condition = stripBalancedOuterParentheses(
      rawWindow.slice(open + 1, close),
    );
    if (!equality.test(condition)) continue;

    let consequent = close + 1;
    while (/\s/u.test(structuralWindow[consequent] ?? "")) consequent += 1;
    const braced = structuralWindow[consequent] === "{";
    if (braced) {
      const endBrace = matchingStructuralBrace(structuralWindow, consequent);
      if (endBrace < 0) continue;
      if (
        javaSimpleBranchCompletesAbruptly(
          rawWindow.slice(consequent + 1, endBrace),
          true,
        )
      ) {
        return index + 1;
      }
      continue;
    }
    const statementEnd = structuralWindow.indexOf(";", consequent);
    if (
      statementEnd >= 0 &&
      javaSimpleBranchCompletesAbruptly(
        rawWindow.slice(consequent, statementEnd + 1),
        false,
      )
    ) {
      return index + 1;
    }
  }
  return undefined;
}

function javaExpressionIsExactIdentifier(
  expression: string,
  identifiers: Iterable<string>,
): boolean {
  return [...identifiers].some((identifier) =>
    new RegExp(
      String.raw`^\s*\(?\s*${escapeRegularExpression(identifier)}\s*\)?\s*$`,
      "u",
    ).test(expression),
  );
}

function javaDeclaredParameterType(parameter: {
  name: string;
  declaration: string;
}): string {
  return parameter.declaration
    .replace(
      new RegExp(
        `${escapeRegularExpression(parameter.name)}\\s*(?:\\[\\s*\\])?\\s*$`,
        "u",
      ),
      "",
    )
    .replace(/@[A-Za-z_$][\w$.]*(?:\([^)]*\))?/gu, " ")
    .replace(/\b(?:final|volatile|transient)\b/gu, " ")
    .replace(/\s*\.\s*/gu, ".")
    .replace(/\s+/gu, " ")
    .trim();
}

function javaStraightLineReturn(
  lines: readonly string[],
  method: JavaMethodDeclaration,
):
  | {
      beforeReturn: string;
      expression: string;
      returnLine: number;
      bodyLineOffset: number;
    }
  | undefined {
  const methodLines = lines.slice(method.startLine - 1, method.endLine);
  const rawMethod = methodLines.join("\n");
  const structuralMethod = cFamilyStructuralLines(methodLines).join("\n");
  const open = structuralMethod.indexOf("{");
  const close = matchingStructuralBrace(structuralMethod, open);
  if (open < 0 || close < 0) return undefined;
  const structuralBody = structuralMethod.slice(open + 1, close);
  if (
    /[{}]|->|\b(?:if|else|switch|try|catch|finally|for|while|do|synchronized|throw|break|continue|yield)\b/u.test(
      structuralBody,
    )
  ) {
    return undefined;
  }
  const returns = [...structuralBody.matchAll(/\breturn\b([\s\S]*?);/gu)];
  if (returns.length !== 1 || returns[0]?.index === undefined) {
    return undefined;
  }
  const returnMatch = returns[0];
  const returnEnd = returnMatch.index + returnMatch[0].length;
  if (structuralBody.slice(returnEnd).trim() !== "") return undefined;
  const rawBody = rawMethod.slice(open + 1, close);
  const expressionStart =
    returnMatch.index + returnMatch[0].indexOf("return") + "return".length;
  const expressionEnd = returnEnd - 1;
  const bodyLineOffset = rawMethod.slice(0, open + 1).split("\n").length - 1;
  return {
    beforeReturn: rawBody.slice(0, returnMatch.index),
    expression: rawBody.slice(expressionStart, expressionEnd),
    returnLine:
      method.startLine +
      bodyLineOffset +
      rawBody.slice(0, returnMatch.index).split("\n").length -
      1,
    bodyLineOffset,
  };
}

function javaBasenameHelperSummaries(
  lines: readonly string[],
  source: {
    path: string;
    packageName?: string;
    projectRoot: string;
  },
  returnTypePattern: string,
  inputTypes: ReadonlyArray<{
    kind: JavaBasenameHelperSummary["inputKind"];
    pattern: string;
  }>,
  constructions: (
    expression: string,
  ) => Array<{ argument: string; reduced: boolean }>,
  reductionMethod: "getFileName" | "getName",
): JavaBasenameHelperSummary[] {
  const methods = javaMethodDeclarations(lines);
  const summaries: JavaBasenameHelperSummary[] = [];
  for (const method of methods) {
    if (
      methods.filter((candidate) => candidate.symbol === method.symbol)
        .length !== 1 ||
      !new RegExp(String.raw`^(?:${returnTypePattern})$`, "u").test(
        method.returnType,
      )
    ) {
      continue;
    }
    const body = javaStraightLineReturn(lines, method);
    if (body === undefined) continue;
    for (const [parameterIndex, parameter] of method.parameters.entries()) {
      const parameterType = javaDeclaredParameterType(parameter);
      const inputKind = inputTypes.find(({ pattern }) =>
        new RegExp(String.raw`^(?:${pattern})$`, "u").test(parameterType),
      )?.kind;
      if (inputKind === undefined) continue;
      const aliases = new Set([parameter.name]);
      const receivers = new Set<string>(
        inputKind === "path" || inputKind === "file" ? [parameter.name] : [],
      );
      const reductions = new Map<string, number>();
      const assignment = /\b([A-Za-z_$][\w$]*)\s*=(?!=)\s*([^;]+);/gu;
      for (const match of body.beforeReturn.matchAll(assignment)) {
        const target = match[1];
        const value = match[2];
        if (target === undefined || value === undefined) continue;
        const line =
          method.startLine +
          body.bodyLineOffset +
          body.beforeReturn.slice(0, match.index ?? 0).split("\n").length -
          1;
        const exactAlias = javaExpressionIsExactIdentifier(value, aliases);
        const exactReceiverAlias = javaExpressionIsExactIdentifier(
          value,
          receivers,
        );
        const factoryResults = constructions(value);
        const directConstruction = factoryResults.some(({ argument }) =>
          javaExpressionIsExactIdentifier(argument, aliases),
        );
        const directReduction = factoryResults.some(
          ({ argument, reduced }) =>
            reduced && javaExpressionIsExactIdentifier(argument, aliases),
        );
        const receiverReduction = [...receivers].some((identifier) =>
          new RegExp(
            String.raw`^\s*${escapeRegularExpression(identifier)}\s*\.\s*${reductionMethod}\s*\(\s*\)\s*$`,
            "u",
          ).test(value),
        );
        const inheritedOrigin = [...reductions].find(([identifier]) =>
          javaExpressionIsExactIdentifier(value, [identifier]),
        )?.[1];

        if (exactAlias) aliases.add(target);
        else aliases.delete(target);
        if (directConstruction || exactReceiverAlias) receivers.add(target);
        else receivers.delete(target);
        if (directReduction || receiverReduction) reductions.set(target, line);
        else if (inheritedOrigin !== undefined)
          reductions.set(target, inheritedOrigin);
        else reductions.delete(target);
      }

      const returnedFactories = constructions(body.expression);
      const directReturnReduction = returnedFactories.some(
        ({ argument, reduced }) =>
          reduced && javaExpressionIsExactIdentifier(argument, aliases),
      );
      const receiverReturnReduction = [...receivers].some((identifier) =>
        new RegExp(
          String.raw`^\s*${escapeRegularExpression(identifier)}\s*\.\s*${reductionMethod}\s*\(\s*\)\s*$`,
          "u",
        ).test(body.expression),
      );
      const returnedOrigin = [...reductions].find(([identifier]) =>
        javaExpressionIsExactIdentifier(body.expression, [identifier]),
      )?.[1];
      const reductionLine =
        directReturnReduction || receiverReturnReduction
          ? body.returnLine
          : returnedOrigin;
      if (reductionLine === undefined) continue;
      summaries.push({
        ownerType: method.ownerType,
        access: method.access,
        isStatic: method.isStatic,
        symbol: method.symbol,
        parameterIndex,
        parameterCount: method.parameters.length,
        inputKind,
        reductionLine,
        sourcePath: source.path,
        ...(source.packageName === undefined
          ? {}
          : { packageName: source.packageName }),
        projectRoot: source.projectRoot,
      });
    }
  }
  return summaries;
}

function javaExactBasenameHelperCall(
  expression: string,
  ownerType: string,
  summaries: readonly JavaBasenameHelperSummary[],
  stringInputs: ReadonlySet<string>,
  pathInputs: ReadonlySet<string>,
  fileInputs: ReadonlySet<string>,
): JavaBasenameHelperSummary | undefined {
  const structural = cFamilyStructuralLines(expression.split(/\r?\n/u)).join(
    "\n",
  );
  const matches = summaries.filter((summary) => {
    const call = new RegExp(
      String.raw`^\s*(?:(?:this|${escapeRegularExpression(ownerType)})\s*\.\s*)?${escapeRegularExpression(summary.symbol)}\s*\(`,
      "u",
    ).exec(structural);
    if (call === null) return false;
    const open = structural.indexOf("(", call.index);
    const close = matchingCallParenthesis(structural, open);
    if (open < 0 || close < 0 || structural.slice(close + 1).trim() !== "") {
      return false;
    }
    const arguments_ = splitJavascriptArguments(
      expression.slice(open + 1, close),
    );
    if (arguments_.length !== summary.parameterCount) return false;
    const inputs =
      summary.inputKind === "path"
        ? pathInputs
        : summary.inputKind === "file"
          ? fileInputs
          : stringInputs;
    return javaExpressionIsExactIdentifier(
      arguments_[summary.parameterIndex] ?? "",
      inputs,
    );
  });
  return matches.length === 1 ? matches[0] : undefined;
}

function javaSingleTypeImports(lines: readonly string[]): string[] {
  const structural = cFamilyStructuralLines(lines)
    .join("\n")
    .replace(/\s*\.\s*/gu, ".");
  return [
    ...structural.matchAll(
      /^\s*import\s+(?!static\b)([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)+)\s*;/gmu,
    ),
  ].flatMap((match) =>
    match[1] === undefined || match[1].endsWith(".*") ? [] : [match[1]],
  );
}

function javaExternalHelperOwnerIsUnique(
  files: readonly SourceFileSnapshot[],
  summary: JavaBasenameHelperSummary,
  sinkProjectRoot: string,
  projectGraph: JavaBasenameProjectGraph,
): boolean {
  const visibleRoots = javaBasenameVisibleProjectRoots(
    projectGraph,
    sinkProjectRoot,
  );
  return (
    files.filter(
      (file) =>
        file.extension === ".java" &&
        !javaTestOrExamplePath(file.path) &&
        visibleRoots.has(javaBasenameProjectRootForPath(files, file.path)) &&
        javaPackageName(file.lines) === summary.packageName &&
        javaTopLevelTypeNames(file.lines).has(summary.ownerType),
    ).length === 1
  );
}

function javaExactExternalBasenameHelperCall(
  expression: string,
  sinkFile: SourceFileSnapshot,
  files: readonly SourceFileSnapshot[],
  projectGraph: JavaBasenameProjectGraph,
  summaries: readonly JavaBasenameHelperSummary[],
  stringInputs: ReadonlySet<string>,
  pathInputs: ReadonlySet<string>,
  fileInputs: ReadonlySet<string>,
): JavaBasenameHelperSummary | undefined {
  const sinkPackage = javaPackageName(sinkFile.lines);
  const sinkProjectRoot = javaBasenameProjectRootForPath(files, sinkFile.path);
  const imports = javaSingleTypeImports(sinkFile.lines);
  const structural = cFamilyStructuralLines(expression.split(/\r?\n/u)).join(
    "\n",
  );
  const matches = summaries.filter((summary) => {
    if (
      summary.sourcePath === sinkFile.path ||
      !javaBasenameProjectCanRead(
        projectGraph,
        sinkProjectRoot,
        summary.projectRoot,
        sinkFile.path,
        summary.sourcePath,
      ) ||
      !summary.isStatic ||
      summary.access === "private" ||
      !javaExternalHelperOwnerIsUnique(
        files,
        summary,
        sinkProjectRoot,
        projectGraph,
      )
    ) {
      return false;
    }
    const samePackage = summary.packageName === sinkPackage;
    if (!samePackage) {
      if (summary.access !== "public") return false;
      const helperFile = files.find((file) => file.path === summary.sourcePath);
      if (
        helperFile === undefined ||
        !new RegExp(
          String.raw`\bpublic\s+(?:final\s+|abstract\s+)?(?:class|record)\s+${escapeRegularExpression(summary.ownerType)}\b`,
          "u",
        ).test(cFamilyStructuralLines(helperFile.lines).join("\n"))
      ) {
        return false;
      }
    }
    const qualifiedOwner =
      summary.packageName === undefined
        ? summary.ownerType
        : `${summary.packageName}.${summary.ownerType}`;
    const sameSimpleImports = imports.filter(
      (candidate) => candidate.split(".").at(-1) === summary.ownerType,
    );
    const simpleOwnerEligible = samePackage
      ? sameSimpleImports.every((candidate) => candidate === qualifiedOwner)
      : sameSimpleImports.length === 1 &&
        sameSimpleImports[0] === qualifiedOwner;
    const ownerPatterns = [
      ...(summary.packageName === undefined
        ? []
        : [
            qualifiedOwner
              .split(".")
              .map(escapeRegularExpression)
              .join(String.raw`\s*\.\s*`),
          ]),
      ...(simpleOwnerEligible
        ? [escapeRegularExpression(summary.ownerType)]
        : []),
    ];
    if (ownerPatterns.length === 0) return false;
    const call = new RegExp(
      String.raw`^\s*(?:${ownerPatterns.join("|")})\s*\.\s*${escapeRegularExpression(summary.symbol)}\s*\(`,
      "u",
    ).exec(structural);
    if (call === null) return false;
    const open = structural.indexOf("(", call.index);
    const close = matchingCallParenthesis(structural, open);
    if (open < 0 || close < 0 || structural.slice(close + 1).trim() !== "") {
      return false;
    }
    const arguments_ = splitJavascriptArguments(
      expression.slice(open + 1, close),
    );
    if (arguments_.length !== summary.parameterCount) return false;
    const inputs =
      summary.inputKind === "path"
        ? pathInputs
        : summary.inputKind === "file"
          ? fileInputs
          : stringInputs;
    return javaExpressionIsExactIdentifier(
      arguments_[summary.parameterIndex] ?? "",
      inputs,
    );
  });
  return matches.length === 1 ? matches[0] : undefined;
}

function javaFileGetNamePathBoundary(
  sinkFile: SourceFileSnapshot,
  files: readonly SourceFileSnapshot[],
  sinkLine: number,
  provenSinkParameters: ReadonlySet<string>,
  samePackageTopLevelTypes: ReadonlySet<string>,
  helperSummaries: readonly JavaBasenameHelperSummary[],
  projectGraph: JavaBasenameProjectGraph,
): JavaBasenameBoundary | undefined {
  const lines = sinkFile.lines;
  const method = exportedJavaMethods(lines).find(
    (candidate) =>
      sinkLine >= candidate.startLine && sinkLine <= candidate.endLine,
  );
  if (method === undefined) return undefined;
  const structuralLines = cFamilyStructuralLines(lines);
  const structuralText = structuralLines.join("\n");
  const fileSingleImported = /^\s*import\s+java\.io\.File\s*;/mu.test(
    structuralText,
  );
  const ioWildcardImported = /^\s*import\s+java\.io\.\*\s*;/mu.test(
    structuralText,
  );
  const fileShadowed = /\b(?:class|enum|interface|record)\s+File\b/u.test(
    structuralText,
  );
  const simpleFileIsOfficial =
    !fileShadowed &&
    (fileSingleImported ||
      (ioWildcardImported && !samePackageTopLevelTypes.has("File")));
  const fileType = simpleFileIsOfficial
    ? String.raw`(?:(?:java\s*\.\s*io\s*\.\s*)?File)`
    : String.raw`(?:java\s*\.\s*io\s*\.\s*File)`;
  const sinkExpression = javaCallExpression(lines, sinkLine, method.endLine);
  const bodyLines = structuralLines.slice(method.startLine - 1, sinkLine - 1);
  const body = bodyLines.join("\n");
  const eligibleParameters =
    provenSinkParameters.size === 0
      ? method.parameters
      : method.parameters.filter((parameter) =>
          provenSinkParameters.has(parameter.name),
        );
  if (eligibleParameters.length === 0) return undefined;
  const tainted = new Set(
    eligibleParameters.map((parameter) => parameter.name),
  );
  const fileReceivers = new Set<string>();
  const pathReceivers = new Set<string>();
  const basenameOrigins = new Map<string, JavaBasenameOrigin>();
  const referencesAny = (
    expression: string,
    identifiers: Iterable<string>,
  ): boolean =>
    [...identifiers].some((identifier) =>
      cFamilyLineReferencesIdentifier(expression, identifier),
    );
  const fileConstructions = (
    expression: string,
  ): Array<{ argument: string; reduced: boolean }> => {
    const starts = expression.matchAll(
      new RegExp(String.raw`\bnew\s+${fileType}\s*\(`, "gu"),
    );
    return [...starts].flatMap((match) => {
      if (match.index === undefined) return [];
      const relativeOpen = match[0].lastIndexOf("(");
      const open = match.index + relativeOpen;
      const close = matchingCallParenthesis(expression, open);
      if (relativeOpen < 0 || close < 0) return [];
      return [
        {
          argument: expression.slice(open + 1, close),
          reduced: /^\s*\.\s*getName\s*\(\s*\)/u.test(
            expression.slice(close + 1),
          ),
        },
      ];
    });
  };
  const localHelperSummaries = helperSummaries.filter(
    (summary) => summary.sourcePath === sinkFile.path,
  );
  const assignment = /\b([A-Za-z_$][\w$]*)\s*=(?!=)\s*([^;]+);/gu;
  for (const match of body.matchAll(assignment)) {
    const target = match[1];
    const value = match[2];
    if (target === undefined || value === undefined) continue;
    const line =
      method.startLine + body.slice(0, match.index ?? 0).split("\n").length - 1;
    const derivesFromTaint = referencesAny(value, tainted);
    const priorFileReceiver = [...fileReceivers].find((identifier) =>
      cFamilyLineReferencesIdentifier(value, identifier),
    );
    const constructions = fileConstructions(value);
    const localHelperSummary = javaExactBasenameHelperCall(
      value,
      method.ownerType,
      localHelperSummaries,
      tainted,
      pathReceivers,
      fileReceivers,
    );
    const helperSummary =
      localHelperSummary ??
      javaExactExternalBasenameHelperCall(
        value,
        sinkFile,
        files,
        projectGraph,
        helperSummaries,
        tainted,
        pathReceivers,
        fileReceivers,
      );
    const directFileConstruction = constructions.some(({ argument }) =>
      referencesAny(argument, tainted),
    );
    const directReduction = constructions.some(
      ({ argument, reduced }) => reduced && referencesAny(argument, tainted),
    );
    const receiverReduction = [...fileReceivers].some((identifier) =>
      new RegExp(
        String.raw`\b${escapeRegularExpression(identifier)}\s*\.\s*getName\s*\(\s*\)`,
        "u",
      ).test(value),
    );
    const inheritedOrigin = [...basenameOrigins].find(([identifier]) =>
      cFamilyLineReferencesIdentifier(value, identifier),
    )?.[1];

    if (derivesFromTaint) tainted.add(target);
    else tainted.delete(target);

    if (
      (directFileConstruction && derivesFromTaint) ||
      priorFileReceiver !== undefined
    ) {
      fileReceivers.add(target);
    } else {
      fileReceivers.delete(target);
    }

    if (helperSummary !== undefined) {
      basenameOrigins.set(target, {
        evidenceLine: helperSummary.reductionLine,
        evidencePath: helperSummary.sourcePath,
        guardStartLine: line,
      });
    } else if (directReduction || receiverReduction) {
      basenameOrigins.set(target, {
        evidenceLine: line,
        evidencePath: sinkFile.path,
        guardStartLine: line,
      });
    } else if (inheritedOrigin !== undefined) {
      basenameOrigins.set(target, inheritedOrigin);
    } else {
      basenameOrigins.delete(target);
    }
  }

  const directSinkReduction = fileConstructions(sinkExpression).some(
    ({ argument, reduced }) => reduced && referencesAny(argument, tainted),
  );
  if (directSinkReduction) {
    return {
      reductionLine: sinkLine,
      reductionPath: sinkFile.path,
    };
  }
  const reachingBasenames = [...basenameOrigins].filter(([identifier]) =>
    cFamilyLineReferencesIdentifier(sinkExpression, identifier),
  );
  if (reachingBasenames.length === 0) return undefined;
  const selectedOrigin = reachingBasenames
    .map(([, origin]) => origin)
    .sort(
      (left, right) =>
        left.evidencePath.localeCompare(right.evidencePath) ||
        left.evidenceLine - right.evidenceLine ||
        left.guardStartLine - right.guardStartLine,
    )[0]!;
  const originKey = (origin: JavaBasenameOrigin): string =>
    `${origin.evidencePath}\0${origin.evidenceLine}\0${origin.guardStartLine}`;
  const selectedOriginKey = originKey(selectedOrigin);
  const basenameIdentifiers = new Set(
    [...basenameOrigins]
      .filter(([, origin]) => originKey(origin) === selectedOriginKey)
      .map(([identifier]) => identifier),
  );
  const parentRejectionLine = javaDominatingEqualityRejection(
    lines,
    structuralLines,
    selectedOrigin.guardStartLine,
    sinkLine,
    basenameIdentifiers,
    String.raw`"\.\."`,
  );
  return parentRejectionLine === undefined
    ? {
        reductionLine: selectedOrigin.evidenceLine,
        reductionPath: selectedOrigin.evidencePath,
      }
    : {
        reductionLine: selectedOrigin.evidenceLine,
        reductionPath: selectedOrigin.evidencePath,
        parentRejectionLine,
      };
}

function javaBraceSurface(
  lines: readonly string[],
  maximumDepth: number,
): string {
  const structural = cFamilyStructuralLines(lines).join("\n");
  let depth = 0;
  let surface = "";
  for (const character of structural) {
    if (character === "{") {
      if (depth <= maximumDepth) surface += character;
      depth += 1;
      continue;
    }
    if (character === "}") {
      depth = Math.max(0, depth - 1);
      if (depth <= maximumDepth) surface += character;
      continue;
    }
    if (depth <= maximumDepth) {
      surface += character;
    } else if (character === "\n") {
      surface += "\n";
    }
  }
  return surface;
}

function javaPackageName(lines: readonly string[]): string | undefined {
  const structural = cFamilyStructuralLines(lines).join("\n");
  const declaration =
    /^\s*package\s+([A-Za-z_$][\w$]*(?:\s*\.\s*[A-Za-z_$][\w$]*)*)\s*;/mu.exec(
      structural,
    )?.[1];
  return declaration?.replace(/\s+/gu, "");
}

function javaTopLevelTypeNames(lines: readonly string[]): Set<string> {
  const surface = javaBraceSurface(lines, 0);
  return new Set(
    [
      ...surface.matchAll(
        /\b(?:class|enum|interface|record)\s+([A-Za-z_$][\w$]*)\b/gu,
      ),
    ].flatMap((match) => (match[1] === undefined ? [] : [match[1]])),
  );
}

function javaPackageTypeIndex(
  files: readonly SourceFileSnapshot[],
): ReadonlyMap<string, ReadonlySet<string>> {
  const projectRoots = files
    .filter((file) => javaProjectBoundaryFile(file.path))
    .map((file) => posix.dirname(file.path))
    .sort((left, right) => right.length - left.length);
  const mutable = new Map<string, Set<string>>();
  for (const file of files) {
    if (file.extension !== ".java" || javaTestOrExamplePath(file.path)) {
      continue;
    }
    const projectRoot =
      projectRoots.find((candidate) =>
        pathWithinDirectory(file.path, candidate),
      ) ?? ".";
    const key = `${projectRoot}\0${javaPackageName(file.lines) ?? "<unnamed>"}`;
    const types = mutable.get(key) ?? new Set<string>();
    for (const name of javaTopLevelTypeNames(file.lines)) types.add(name);
    mutable.set(key, types);
  }
  return mutable;
}

function javaSamePackageTopLevelTypes(
  index: ReadonlyMap<string, ReadonlySet<string>>,
  files: readonly SourceFileSnapshot[],
  sinkFile: SourceFileSnapshot,
  projectGraph: JavaBasenameProjectGraph,
): ReadonlySet<string> {
  const projectRoot = javaBasenameProjectRootForPath(files, sinkFile.path);
  const packageName = javaPackageName(sinkFile.lines) ?? "<unnamed>";
  const types = new Set<string>();
  for (const visibleRoot of javaBasenameVisibleProjectRoots(
    projectGraph,
    projectRoot,
  )) {
    const key = `${visibleRoot}\0${packageName}`;
    for (const type of index.get(key) ?? []) types.add(type);
  }
  return types;
}

function javaFileBasenameHelperSummaries(
  files: readonly SourceFileSnapshot[],
  packageTypes: ReadonlyMap<string, ReadonlySet<string>>,
  projectGraph: JavaBasenameProjectGraph,
): JavaBasenameHelperSummary[] {
  return files.flatMap((file) => {
    if (file.extension !== ".java" || javaTestOrExamplePath(file.path)) {
      return [];
    }
    const structuralText = cFamilyStructuralLines(file.lines).join("\n");
    const samePackageTypes = javaSamePackageTopLevelTypes(
      packageTypes,
      files,
      file,
      projectGraph,
    );
    const fileSingleImported = /^\s*import\s+java\.io\.File\s*;/mu.test(
      structuralText,
    );
    const ioWildcardImported = /^\s*import\s+java\.io\.\*\s*;/mu.test(
      structuralText,
    );
    const fileShadowed = /\b(?:class|enum|interface|record)\s+File\b/u.test(
      structuralText,
    );
    const simpleFileIsOfficial =
      !fileShadowed &&
      (fileSingleImported ||
        (ioWildcardImported && !samePackageTypes.has("File")));
    const fileType = simpleFileIsOfficial
      ? String.raw`(?:(?:java\s*\.\s*io\s*\.\s*)?File)`
      : String.raw`(?:java\s*\.\s*io\s*\.\s*File)`;
    const stringType = !samePackageTypes.has("String")
      ? String.raw`(?:(?:java\s*\.\s*lang\s*\.\s*)?String)`
      : String.raw`(?:java\s*\.\s*lang\s*\.\s*String)`;
    const constructions = (
      expression: string,
    ): Array<{ argument: string; reduced: boolean }> =>
      [
        ...expression.matchAll(
          new RegExp(String.raw`\bnew\s+${fileType}\s*\(`, "gu"),
        ),
      ].flatMap((match) => {
        if (match.index === undefined) return [];
        const relativeOpen = match[0].lastIndexOf("(");
        const open = match.index + relativeOpen;
        const close = matchingCallParenthesis(expression, open);
        if (relativeOpen < 0 || close < 0) return [];
        return [
          {
            argument: expression.slice(open + 1, close),
            reduced: /^\s*\.\s*getName\s*\(\s*\)/u.test(
              expression.slice(close + 1),
            ),
          },
        ];
      });
    return javaBasenameHelperSummaries(
      file.lines,
      {
        path: file.path,
        ...(javaPackageName(file.lines) === undefined
          ? {}
          : { packageName: javaPackageName(file.lines) }),
        projectRoot: javaBasenameProjectRootForPath(files, file.path),
      },
      stringType,
      [
        { kind: "string", pattern: stringType },
        { kind: "file", pattern: fileType },
      ],
      constructions,
      "getName",
    );
  });
}

function javaPathBasenameHelperSummaries(
  files: readonly SourceFileSnapshot[],
  packageTypes: ReadonlyMap<string, ReadonlySet<string>>,
  projectGraph: JavaBasenameProjectGraph,
): JavaBasenameHelperSummary[] {
  return files.flatMap((file) => {
    if (file.extension !== ".java" || javaTestOrExamplePath(file.path)) {
      return [];
    }
    const structuralLines = cFamilyStructuralLines(file.lines);
    const structuralText = structuralLines.join("\n");
    const samePackageTypes = javaSamePackageTopLevelTypes(
      packageTypes,
      files,
      file,
      projectGraph,
    );
    const pathSingleImported = /^\s*import\s+java\.nio\.file\.Path\s*;/mu.test(
      structuralText,
    );
    const pathsSingleImported =
      /^\s*import\s+java\.nio\.file\.Paths\s*;/mu.test(structuralText);
    const wildcardImported = /^\s*import\s+java\.nio\.file\.\*\s*;/mu.test(
      structuralText,
    );
    const pathShadowed = /\b(?:class|enum|interface|record)\s+Path\b/u.test(
      structuralText,
    );
    const pathsShadowed = /\b(?:class|enum|interface|record)\s+Paths\b/u.test(
      structuralText,
    );
    const simplePathIsOfficial =
      !pathShadowed &&
      (pathSingleImported ||
        (wildcardImported && !samePackageTypes.has("Path")));
    const simplePathsIsOfficial =
      !pathsShadowed &&
      (pathsSingleImported ||
        (wildcardImported && !samePackageTypes.has("Paths")));
    const staticPathOfImported = javaStaticFactoryImportIsExact(
      structuralText,
      "java.nio.file.Path",
      "of",
    );
    const staticPathsGetImported = javaStaticFactoryImportIsExact(
      structuralText,
      "java.nio.file.Paths",
      "get",
    );
    const factoryTypes = [
      String.raw`java\s*\.\s*nio\s*\.\s*file\s*\.\s*Path\s*\.\s*of`,
      String.raw`java\s*\.\s*nio\s*\.\s*file\s*\.\s*Paths\s*\.\s*get`,
      ...(simplePathIsOfficial ? [String.raw`Path\s*\.\s*of`] : []),
      ...(simplePathsIsOfficial ? [String.raw`Paths\s*\.\s*get`] : []),
      ...(staticPathOfImported &&
      !javaCompilationUnitDeclaresMethod(structuralLines, "of")
        ? [String.raw`(?<![A-Za-z0-9_$.])of`]
        : []),
      ...(staticPathsGetImported &&
      !javaCompilationUnitDeclaresMethod(structuralLines, "get")
        ? [String.raw`(?<![A-Za-z0-9_$.])get`]
        : []),
    ];
    const factoryStart = new RegExp(
      String.raw`\b(?:${factoryTypes.join("|")})\s*\(`,
      "gu",
    );
    const constructions = (
      expression: string,
    ): Array<{ argument: string; reduced: boolean }> => {
      expression = expression.replace(/\s*\.\s*/gu, ".");
      factoryStart.lastIndex = 0;
      return [...expression.matchAll(factoryStart)].flatMap((match) => {
        if (match.index === undefined) return [];
        const relativeOpen = match[0].lastIndexOf("(");
        const open = match.index + relativeOpen;
        const close = matchingCallParenthesis(expression, open);
        if (relativeOpen < 0 || close < 0) return [];
        return [
          {
            argument: expression.slice(open + 1, close),
            reduced: /^\s*\.\s*getFileName\s*\(\s*\)/u.test(
              expression.slice(close + 1),
            ),
          },
        ];
      });
    };
    const pathType = simplePathIsOfficial
      ? String.raw`(?:(?:java\s*\.\s*nio\s*\.\s*file\s*\.\s*)?Path)`
      : String.raw`(?:java\s*\.\s*nio\s*\.\s*file\s*\.\s*Path)`;
    const stringType = !samePackageTypes.has("String")
      ? String.raw`(?:(?:java\s*\.\s*lang\s*\.\s*)?String)`
      : String.raw`(?:java\s*\.\s*lang\s*\.\s*String)`;
    return javaBasenameHelperSummaries(
      file.lines,
      {
        path: file.path,
        ...(javaPackageName(file.lines) === undefined
          ? {}
          : { packageName: javaPackageName(file.lines) }),
        projectRoot: javaBasenameProjectRootForPath(files, file.path),
      },
      pathType,
      [
        { kind: "string", pattern: stringType },
        { kind: "path", pattern: pathType },
      ],
      constructions,
      "getFileName",
    );
  });
}

function javaCompilationUnitDeclaresMethod(
  lines: readonly string[],
  methodName: string,
): boolean {
  const surface = javaBraceSurface(lines, 1);
  const escaped = escapeRegularExpression(methodName);
  return new RegExp(
    String.raw`(?:^|[;{}])\s*(?:(?:@[A-Za-z_$][\w$.]*(?:\([^;{}]*\))?)\s*)*(?:(?:public|protected|private|abstract|default|final|native|static|strictfp|synchronized)\s+)*(?:<[^;{}]+>\s+)?[A-Za-z_$][\w$.[\]<>?,]*(?:\s*\[\s*\])?\s+${escaped}\s*\(`,
    "mu",
  ).test(surface);
}

function javaStaticFactoryImportIsExact(
  structuralText: string,
  owner: string,
  methodName: string,
): boolean {
  const normalized = structuralText.replace(/\s*\.\s*/gu, ".");
  const imports = [
    ...normalized.matchAll(
      /^\s*import\s+static\s+([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*|\.\*)+)\s*;/gmu,
    ),
  ].flatMap((match) => (match[1] === undefined ? [] : [match[1]]));
  const exact = `${owner}.${methodName}`;
  const wildcard = `${owner}.*`;
  if (!imports.includes(exact) && !imports.includes(wildcard)) return false;
  return !imports.some(
    (candidate) =>
      candidate !== exact &&
      candidate !== wildcard &&
      (candidate.endsWith(`.${methodName}`) || candidate.endsWith(".*")),
  );
}

function javaPathGetFileNamePathBoundaryRecords(
  files: readonly SourceFileSnapshot[],
  records: readonly ResidualRiskRecord[],
): ResidualRiskRecord[] {
  const filesByPath = new Map(files.map((file) => [file.path, file]));
  const projectGraph = javaBasenameProjectGraph(files);
  const packageTypes = javaPackageTypeIndex(files);
  const helperSummaries = javaPathBasenameHelperSummaries(
    files,
    packageTypes,
    projectGraph,
  );
  const emitted = new Set<string>();
  const specialized: ResidualRiskRecord[] = [];
  for (const record of records) {
    const framework = record.frameworkModel;
    if (framework?.id !== "spring-http-path") continue;
    const sinkFile = filesByPath.get(framework.sink.path);
    if (
      sinkFile?.extension !== ".java" ||
      javaTestOrExamplePath(sinkFile.path)
    ) {
      continue;
    }
    const boundary = javaPathGetFileNamePathBoundary(
      sinkFile,
      files,
      framework.sink.line,
      new Set(
        framework.propagators
          .filter(
            (propagator) =>
              propagator.kind === "wrapper-parameter" &&
              propagator.path === sinkFile.path,
          )
          .flatMap((propagator) =>
            propagator.symbol === undefined ? [] : [propagator.symbol],
          ),
      ),
      javaSamePackageTopLevelTypes(packageTypes, files, sinkFile, projectGraph),
      helperSummaries,
      projectGraph,
    );
    if (boundary === undefined) continue;
    const key = `${framework.source.path}\0${framework.source.line}\0${framework.sink.path}\0${framework.sink.line}`;
    if (emitted.has(key)) continue;
    emitted.add(key);
    specialized.push({
      ...record,
      categories: [
        "framework-dataflow:java-path-getfilename-path-boundary",
        `modeled-source:${framework.source.kind}`,
        `modeled-sink:${framework.sink.kind}`,
        "broken-control:java-nio-path-basename-reduction",
        ...(boundary.parentRejectionLine === undefined
          ? []
          : ["candidate-control:parent-path-component-rejection"]),
      ],
      priority: Math.max(record.priority, 122),
      frameworkModel: {
        ...framework,
        id: "java-path-getfilename-path-boundary",
        candidateControls: [
          ...framework.candidateControls.filter(
            (control) => control.kind !== "single-path-component-validation",
          ),
          {
            kind: "incomplete-java-nio-path-getfilename-reduction",
            path: boundary.reductionPath,
            line: boundary.reductionLine,
          },
          ...(boundary.parentRejectionLine === undefined
            ? []
            : [
                {
                  kind: "parent-path-component-rejection",
                  path: sinkFile.path,
                  line: boundary.parentRejectionLine,
                },
              ]),
        ].filter(
          (control, index, all) =>
            all.findIndex(
              (candidate) =>
                candidate.kind === control.kind &&
                candidate.path === control.path &&
                candidate.line === control.line,
            ) === index,
        ),
      },
    });
  }
  return specialized;
}

function javaPathGetFileNamePathBoundary(
  sinkFile: SourceFileSnapshot,
  files: readonly SourceFileSnapshot[],
  sinkLine: number,
  provenSinkParameters: ReadonlySet<string>,
  samePackageTopLevelTypes: ReadonlySet<string>,
  helperSummaries: readonly JavaBasenameHelperSummary[],
  projectGraph: JavaBasenameProjectGraph,
): JavaBasenameBoundary | undefined {
  const lines = sinkFile.lines;
  const method = exportedJavaMethods(lines).find(
    (candidate) =>
      sinkLine >= candidate.startLine && sinkLine <= candidate.endLine,
  );
  if (method === undefined) return undefined;
  const structuralLines = cFamilyStructuralLines(lines);
  const structuralText = structuralLines.join("\n");
  const pathSingleImported = /^\s*import\s+java\.nio\.file\.Path\s*;/mu.test(
    structuralText,
  );
  const pathsSingleImported = /^\s*import\s+java\.nio\.file\.Paths\s*;/mu.test(
    structuralText,
  );
  const nioFileWildcardImported = /^\s*import\s+java\.nio\.file\.\*\s*;/mu.test(
    structuralText,
  );
  const pathShadowed = /\b(?:class|enum|interface|record)\s+Path\b/u.test(
    structuralText,
  );
  const pathsShadowed = /\b(?:class|enum|interface|record)\s+Paths\b/u.test(
    structuralText,
  );
  const simplePathIsOfficial =
    !pathShadowed &&
    (pathSingleImported ||
      (nioFileWildcardImported && !samePackageTopLevelTypes.has("Path")));
  const simplePathsIsOfficial =
    !pathsShadowed &&
    (pathsSingleImported ||
      (nioFileWildcardImported && !samePackageTopLevelTypes.has("Paths")));
  const localOfMethod = javaCompilationUnitDeclaresMethod(
    structuralLines,
    "of",
  );
  const localGetMethod = javaCompilationUnitDeclaresMethod(
    structuralLines,
    "get",
  );
  const staticPathOfImported = javaStaticFactoryImportIsExact(
    structuralText,
    "java.nio.file.Path",
    "of",
  );
  const staticPathsGetImported = javaStaticFactoryImportIsExact(
    structuralText,
    "java.nio.file.Paths",
    "get",
  );
  const pathType = simplePathIsOfficial
    ? String.raw`(?:(?:java\s*\.\s*nio\s*\.\s*file\s*\.\s*)?Path)`
    : String.raw`(?:java\s*\.\s*nio\s*\.\s*file\s*\.\s*Path)`;
  const factoryTypes = [
    String.raw`java\s*\.\s*nio\s*\.\s*file\s*\.\s*Path\s*\.\s*of`,
    String.raw`java\s*\.\s*nio\s*\.\s*file\s*\.\s*Paths\s*\.\s*get`,
    ...(simplePathIsOfficial ? [String.raw`Path\s*\.\s*of`] : []),
    ...(simplePathsIsOfficial ? [String.raw`Paths\s*\.\s*get`] : []),
    ...(staticPathOfImported && !localOfMethod
      ? [String.raw`(?<![A-Za-z0-9_$.])of`]
      : []),
    ...(staticPathsGetImported && !localGetMethod
      ? [String.raw`(?<![A-Za-z0-9_$.])get`]
      : []),
  ];
  const factoryStart = new RegExp(
    String.raw`\b(?:${factoryTypes.join("|")})\s*\(`,
    "gu",
  );
  const sinkExpression = javaCallExpression(lines, sinkLine, method.endLine);
  const bodyLines = structuralLines.slice(method.startLine - 1, sinkLine - 1);
  const body = bodyLines.join("\n");
  const eligibleParameters =
    provenSinkParameters.size === 0
      ? method.parameters
      : method.parameters.filter((parameter) =>
          provenSinkParameters.has(parameter.name),
        );
  if (eligibleParameters.length === 0) return undefined;
  const tainted = new Set(
    eligibleParameters.map((parameter) => parameter.name),
  );
  const pathReceivers = new Set(
    eligibleParameters
      .filter((parameter) =>
        new RegExp(
          String.raw`\b${pathType}\s+${escapeRegularExpression(parameter.name)}\b`,
          "u",
        ).test(parameter.declaration),
      )
      .map((parameter) => parameter.name),
  );
  const fileReceivers = new Set<string>();
  const basenameOrigins = new Map<string, JavaBasenameOrigin>();
  const referencesAny = (
    expression: string,
    identifiers: Iterable<string>,
  ): boolean =>
    [...identifiers].some((identifier) =>
      cFamilyLineReferencesIdentifier(expression, identifier),
    );
  const exactAliasOf = (
    expression: string,
    identifiers: Iterable<string>,
  ): boolean =>
    [...identifiers].some((identifier) =>
      new RegExp(
        String.raw`^\s*\(?\s*${escapeRegularExpression(identifier)}\s*\)?\s*$`,
        "u",
      ).test(expression),
    );
  const pathFactories = (
    expression: string,
  ): Array<{ argument: string; reduced: boolean }> => {
    expression = expression.replace(/\s*\.\s*/gu, ".");
    factoryStart.lastIndex = 0;
    return [...expression.matchAll(factoryStart)].flatMap((match) => {
      if (match.index === undefined) return [];
      const relativeOpen = match[0].lastIndexOf("(");
      const open = match.index + relativeOpen;
      const close = matchingCallParenthesis(expression, open);
      if (relativeOpen < 0 || close < 0) return [];
      return [
        {
          argument: expression.slice(open + 1, close),
          reduced: /^\s*\.\s*getFileName\s*\(\s*\)/u.test(
            expression.slice(close + 1),
          ),
        },
      ];
    });
  };
  const localHelperSummaries = helperSummaries.filter(
    (summary) => summary.sourcePath === sinkFile.path,
  );
  const assignment = /\b([A-Za-z_$][\w$]*)\s*=(?!=)\s*([^;]+);/gu;
  for (const match of body.matchAll(assignment)) {
    const target = match[1];
    const value = match[2];
    if (target === undefined || value === undefined) continue;
    const line =
      method.startLine + body.slice(0, match.index ?? 0).split("\n").length - 1;
    const derivesFromTaint = referencesAny(value, tainted);
    const constructions = pathFactories(value);
    const localHelperSummary = javaExactBasenameHelperCall(
      value,
      method.ownerType,
      localHelperSummaries,
      tainted,
      pathReceivers,
      fileReceivers,
    );
    const helperSummary =
      localHelperSummary ??
      javaExactExternalBasenameHelperCall(
        value,
        sinkFile,
        files,
        projectGraph,
        helperSummaries,
        tainted,
        pathReceivers,
        fileReceivers,
      );
    const directPathConstruction = constructions.some(({ argument }) =>
      referencesAny(argument, tainted),
    );
    const directReduction = constructions.some(
      ({ argument, reduced }) => reduced && referencesAny(argument, tainted),
    );
    const receiverReduction = [...pathReceivers].some((identifier) =>
      new RegExp(
        String.raw`\b${escapeRegularExpression(identifier)}\s*\.\s*getFileName\s*\(\s*\)`,
        "u",
      ).test(value),
    );
    const inheritedOrigin = [...basenameOrigins].find(([identifier]) =>
      cFamilyLineReferencesIdentifier(value, identifier),
    )?.[1];

    if (derivesFromTaint) tainted.add(target);
    else tainted.delete(target);

    if (
      directPathConstruction ||
      exactAliasOf(value, pathReceivers) ||
      helperSummary !== undefined
    ) {
      pathReceivers.add(target);
    } else {
      pathReceivers.delete(target);
    }

    if (helperSummary !== undefined) {
      basenameOrigins.set(target, {
        evidenceLine: helperSummary.reductionLine,
        evidencePath: helperSummary.sourcePath,
        guardStartLine: line,
      });
    } else if (directReduction || receiverReduction) {
      basenameOrigins.set(target, {
        evidenceLine: line,
        evidencePath: sinkFile.path,
        guardStartLine: line,
      });
    } else if (inheritedOrigin !== undefined) {
      basenameOrigins.set(target, inheritedOrigin);
    } else {
      basenameOrigins.delete(target);
    }
  }

  const directSinkReduction = pathFactories(sinkExpression).some(
    ({ argument, reduced }) => reduced && referencesAny(argument, tainted),
  );
  const receiverSinkReduction = [...pathReceivers].some((identifier) =>
    new RegExp(
      String.raw`\b${escapeRegularExpression(identifier)}\s*\.\s*getFileName\s*\(\s*\)`,
      "u",
    ).test(sinkExpression),
  );
  if (directSinkReduction || receiverSinkReduction) {
    return {
      reductionLine: sinkLine,
      reductionPath: sinkFile.path,
    };
  }
  const reachingBasenames = [...basenameOrigins].filter(([identifier]) =>
    cFamilyLineReferencesIdentifier(sinkExpression, identifier),
  );
  if (reachingBasenames.length === 0) return undefined;
  const selectedOrigin = reachingBasenames
    .map(([, origin]) => origin)
    .sort(
      (left, right) =>
        left.evidencePath.localeCompare(right.evidencePath) ||
        left.evidenceLine - right.evidenceLine ||
        left.guardStartLine - right.guardStartLine,
    )[0]!;
  const originKey = (origin: JavaBasenameOrigin): string =>
    `${origin.evidencePath}\0${origin.evidenceLine}\0${origin.guardStartLine}`;
  const selectedOriginKey = originKey(selectedOrigin);
  const basenameIdentifiers = new Set(
    [...basenameOrigins]
      .filter(([, origin]) => originKey(origin) === selectedOriginKey)
      .map(([identifier]) => identifier),
  );
  const parentFactories = factoryTypes.join("|");
  const parentRejectionLine = javaDominatingEqualityRejection(
    lines,
    structuralLines,
    selectedOrigin.guardStartLine,
    sinkLine,
    basenameIdentifiers,
    String.raw`(?:${parentFactories})\s*\(\s*"\.\."\s*\)`,
  );
  return parentRejectionLine === undefined
    ? {
        reductionLine: selectedOrigin.evidenceLine,
        reductionPath: selectedOrigin.evidencePath,
      }
    : {
        reductionLine: selectedOrigin.evidenceLine,
        reductionPath: selectedOrigin.evidencePath,
        parentRejectionLine,
      };
}

function nodeIpv4OnlyHostGuard(
  lines: readonly string[],
  wrapper: ExportedJavascriptFunction,
  sinkLine: number,
  sinkExpression: string,
): { line: number } | undefined {
  const codeLines = javascriptCodeLinesWithoutComments(lines);
  const structuralLines = javascriptStructuralLines(lines);
  const valueIdentifiers = new Set(
    javascriptExpressionIdentifiers(sinkExpression).filter(
      (identifier) =>
        !["fetch", "get", "got", "http", "https", "request", "undici"].includes(
          identifier,
        ),
    ),
  );
  if (valueIdentifiers.size === 0) return undefined;

  const aliases = new Set(valueIdentifiers);
  for (
    let index = wrapper.startLine - 1;
    index < Math.min(sinkLine - 1, wrapper.endLine);
    index += 1
  ) {
    const code = structuralLines[index] ?? "";
    const assignment =
      /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*([\s\S]+)$/u.exec(code);
    if (
      assignment?.[1] !== undefined &&
      assignment[2] !== undefined &&
      [...aliases].some((identifier) =>
        lineReferencesIdentifier(assignment[2]!, identifier),
      ) &&
      /\b(?:host|hostname|new\s+URL|parse|process)\b|\.\s*(?:host|hostname)\b/iu.test(
        assignment[2],
      )
    ) {
      aliases.add(assignment[1]);
    }
  }

  const wrapperText = codeLines
    .slice(wrapper.startLine - 1, Math.min(sinkLine, wrapper.endLine))
    .join("\n");

  for (
    let index = wrapper.startLine - 1;
    index < Math.min(sinkLine - 1, wrapper.endLine);
    index += 1
  ) {
    const structural = structuralLines[index] ?? "";
    const original = codeLines[index] ?? "";
    if (!/\bif\s*\(/u.test(structural)) continue;
    if (
      ![...aliases].some((identifier) =>
        lineReferencesIdentifier(structural, identifier),
      )
    ) {
      continue;
    }
    const explicitIpv4Classifier =
      /\b(?:isPrivate|isReserved|isRfc1918|isLoopback)(?:DottedQuad|IPv?4)|\b(?:dottedQuad|ipv4)(?:Address)?IsPrivate\b/iu.test(
        structural,
      );
    const ipv4LiteralGuard =
      /(?:10\.|127\.|169\.254\.|172\.(?:1[6-9]|2\d|3[01])\.|192\.168\.)/u.test(
        original,
      );
    if (!explicitIpv4Classifier && !ipv4LiteralGuard) continue;
    const failClosedWindow = structuralLines
      .slice(index, Math.min(index + 4, sinkLine - 1))
      .join("\n");
    if (!/\b(?:return|throw)\b/u.test(failClosedWindow)) continue;
    if (
      nodeHasCompleteIpv6TransitionCanonicalization(
        lines,
        wrapperText,
        structural,
      )
    ) {
      continue;
    }
    return { line: index + 1 };
  }
  return undefined;
}

function nodeHasCompleteIpv6TransitionCanonicalization(
  lines: readonly string[],
  wrapperText: string,
  guardExpression: string,
): boolean {
  const assignment =
    /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*([A-Za-z_$][\w$]*(?:canonical|normalize|unwrap|transition)[A-Za-z_$\d]*)\s*\(/iu.exec(
      wrapperText,
    );
  const canonicalValue = assignment?.[1];
  const canonicalizer = assignment?.[2];
  if (
    canonicalValue === undefined ||
    canonicalizer === undefined ||
    !lineReferencesIdentifier(guardExpression, canonicalValue)
  ) {
    return false;
  }
  const structuralLines = javascriptStructuralLines(lines);
  const declaration = new RegExp(
    `(?:\\bfunction\\s+${escapeRegularExpression(canonicalizer)}\\s*\\(|\\b(?:const|let|var)\\s+${escapeRegularExpression(canonicalizer)}\\s*=)`,
    "u",
  );
  const declarationIndex = structuralLines.findIndex((line) =>
    declaration.test(line),
  );
  if (declarationIndex < 0) return false;
  const endLine = javascriptFunctionEndLine(lines, declarationIndex);
  const definition = javascriptCodeLinesWithoutComments(
    lines.slice(declarationIndex, endLine),
  ).join("\n");
  const mapped = /::ffff:|isIPv4MappedAddress|ipv4Mapped|mappedIpv4/iu.test(
    definition,
  );
  const nat64 = /64:ff9b:|nat64/iu.test(definition);
  const sixToFour = /2002:|6to4|sixToFour/iu.test(definition);
  const extractsEmbeddedAddress =
    /toIPv4Address|embeddedIpv4|extract[A-Za-z_$\d]*Ipv4|(?:slice|substring)\s*\(/iu.test(
      definition,
    );
  return mapped && nat64 && sixToFour && extractsEmbeddedAddress;
}

interface NodeDeepseekMcpHttpLaunch {
  dependency: NodeRuntimeDependency;
  file: SourceFileSnapshot;
  route: "module-dynamic-import" | "operational-npm-script";
  sourceLine: number;
  sinkLine: number;
}

function nodeDeepseekMcpVersionHasHttpSessionAuthorizationBypass(
  version: string,
): boolean {
  if (version.includes("-")) return false;
  const parts = version.split(".").map(Number);
  if (parts.length !== 3 || parts.some((part) => !Number.isSafeInteger(part))) {
    return false;
  }
  const [major, minor, patch] = parts as [number, number, number];
  return major === 1 && (minor > 4 || (minor === 4 && patch >= 2)) && minor < 7;
}

function nodeDeepseekMcpTransportAssignment(
  structuralLine: string,
): "http" | "stdio" | "other" | undefined {
  const assignment =
    /\bprocess\s*\.\s*env\s*(?:\.\s*TRANSPORT|\[\s*["']TRANSPORT["']\s*\])\s*=\s*([^;\r\n]+)/u.exec(
      structuralLine,
    );
  if (assignment?.[1] !== undefined) {
    const value = assignment[1].trim();
    if (/^["']http["']$/u.test(value)) return "http";
    if (/^["']stdio["']$/u.test(value)) return "stdio";
    return "other";
  }
  const property = String.raw`process\s*\.\s*env\s*(?:\.\s*TRANSPORT|\[\s*["']TRANSPORT["']\s*\])`;
  if (
    new RegExp(
      String.raw`(?:\bdelete\s+${property}|${property}\s*(?:\+\+|--|(?:\?\?|\|\||&&|[+*/%-])?=)|\bObject\s*\.\s*assign\s*\(\s*process\s*\.\s*env\b|\bReflect\s*\.\s*set\s*\(\s*process\s*\.\s*env\s*,\s*["']TRANSPORT["'])`,
      "u",
    ).test(structuralLine)
  ) {
    return "other";
  }
  return undefined;
}

function nodeDeepseekMcpDynamicLaunches(
  files: readonly SourceFileSnapshot[],
): NodeDeepseekMcpHttpLaunch[] {
  const launches: NodeDeepseekMcpHttpLaunch[] = [];
  for (const file of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path) ||
      !file.text.includes("@arikusi/deepseek-mcp-server")
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(
      files,
      file.path,
      "@arikusi/deepseek-mcp-server",
    );
    if (
      dependency === undefined ||
      !nodeDeepseekMcpVersionHasHttpSessionAuthorizationBypass(
        dependency.version,
      )
    ) {
      continue;
    }
    const codeLines = javascriptCodeLinesWithoutComments(file.lines);
    const structuralLines = javascriptStructuralLines(file.lines);
    for (let index = 0; index < structuralLines.length; index += 1) {
      const code = codeLines[index] ?? "";
      if (
        !/\bimport\s*\(\s*["']@arikusi\/deepseek-mcp-server["']\s*\)/u.test(
          code,
        ) ||
        !javascriptModuleScopeLine(structuralLines, index + 1)
      ) {
        continue;
      }
      let sourceLine: number | undefined;
      let transport: "http" | "stdio" | "other" | undefined;
      for (let prior = 0; prior < index; prior += 1) {
        const candidate = nodeDeepseekMcpTransportAssignment(
          codeLines[prior] ?? "",
        );
        if (
          candidate !== undefined &&
          javascriptModuleScopeLine(structuralLines, prior + 1)
        ) {
          transport = candidate;
          sourceLine = prior + 1;
        }
      }
      if (transport !== "http" || sourceLine === undefined) continue;
      launches.push({
        dependency,
        file,
        route: "module-dynamic-import",
        sourceLine,
        sinkLine: index + 1,
      });
    }
  }
  return launches;
}

function nodeDeepseekMcpOperationalScriptCommand(command: string): boolean {
  const packageInvocation = String.raw`(?:deepseek-mcp-server|npx(?:\s+--yes)?\s+@arikusi/deepseek-mcp-server|npm\s+exec(?:\s+--yes)?\s+(?:--\s+)?@arikusi/deepseek-mcp-server)`;
  const posix = new RegExp(
    String.raw`^(?:(?:cross-env(?:-shell)?|env)\s+)?(?:(?:[A-Za-z_][A-Za-z0-9_]*=(?:[^\s;&|]+|"[^"]*"|'[^']*'))\s+)*${packageInvocation}(?:\s|$)`,
    "u",
  );
  if (
    posix.test(command.trim()) &&
    /(?:^|\s)TRANSPORT=(?:http|["']http["'])(?:\s|$)/u.test(command)
  ) {
    return true;
  }
  const windows = new RegExp(
    String.raw`^set\s+(?:"TRANSPORT=http"|TRANSPORT=http)\s*&&\s*(?:call\s+)?${packageInvocation}(?:\s|$)`,
    "u",
  );
  return windows.test(command.trim());
}

function nodeDeepseekMcpScriptLaunches(
  files: readonly SourceFileSnapshot[],
): NodeDeepseekMcpHttpLaunch[] {
  const launches: NodeDeepseekMcpHttpLaunch[] = [];
  for (const file of files) {
    if (
      posix.basename(file.path) !== "package.json" ||
      javascriptTestOrExamplePath(file.path)
    ) {
      continue;
    }
    let root: Record<string, unknown>;
    try {
      const parsed = JSON.parse(file.text) as unknown;
      if (
        typeof parsed !== "object" ||
        parsed === null ||
        Array.isArray(parsed)
      ) {
        continue;
      }
      root = parsed as Record<string, unknown>;
    } catch {
      continue;
    }
    const scripts = root["scripts"];
    if (
      typeof scripts !== "object" ||
      scripts === null ||
      Array.isArray(scripts)
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(
      files,
      file.path,
      "@arikusi/deepseek-mcp-server",
    );
    if (
      dependency === undefined ||
      !nodeDeepseekMcpVersionHasHttpSessionAuthorizationBypass(
        dependency.version,
      )
    ) {
      continue;
    }
    for (const [name, value] of Object.entries(
      scripts as Record<string, unknown>,
    ).sort(([left], [right]) => left.localeCompare(right))) {
      if (
        typeof value !== "string" ||
        !/^(?:mcp|serve|server|start)(?::[A-Za-z0-9._-]+)?$/u.test(name) ||
        !nodeDeepseekMcpOperationalScriptCommand(value)
      ) {
        continue;
      }
      const serializedName = JSON.stringify(name);
      const line =
        file.lines.findIndex(
          (candidate) =>
            candidate.includes(serializedName) && candidate.includes(":"),
        ) + 1;
      launches.push({
        dependency,
        file,
        route: "operational-npm-script",
        sourceLine: Math.max(1, line),
        sinkLine: Math.max(1, line),
      });
    }
  }
  return launches;
}

function nodeDeepseekMcpHttpSessionAuthorizationRecords(
  files: readonly SourceFileSnapshot[],
): ResidualRiskRecord[] {
  const launches = [
    ...nodeDeepseekMcpDynamicLaunches(files),
    ...nodeDeepseekMcpScriptLaunches(files),
  ].filter(
    (launch, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.file.path === launch.file.path &&
          candidate.sourceLine === launch.sourceLine &&
          candidate.sinkLine === launch.sinkLine,
      ) === index,
  );
  return launches.map((launch) => {
    const sinkStart = Math.max(1, launch.sinkLine - CONTEXT_LINES_BEFORE);
    const sinkEnd = Math.min(
      launch.file.lines.length,
      launch.sinkLine + CONTEXT_LINES_AFTER,
    );
    const sourceStart = Math.max(1, launch.sourceLine - 2);
    const sourceEnd = Math.min(launch.file.lines.length, launch.sourceLine + 2);
    const prefix =
      launch.dependency.proof === "npm-lockfile" ? "lock-resolved-" : "";
    const sinkKind = `${prefix}vulnerable-deepseek-mcp-process-global-caller-keyed-session-store`;
    return {
      path: launch.file.path,
      line: launch.sinkLine,
      categories: [
        "framework-dataflow:node-deepseek-mcp-http-cross-session-authorization-bypass",
        "modeled-source:unauthenticated-multi-client-http-mcp-session",
        `modeled-sink:${sinkKind}`,
      ],
      priority: 122,
      startLine: sinkStart,
      endLine: sinkEnd,
      excerpt: sourceExcerpt(launch.file.lines, sinkStart, sinkEnd),
      sourceExcerpt: sourceExcerpt(launch.file.lines, sourceStart, sourceEnd),
      frameworkModel: {
        schemaVersion: "1.2",
        id: "node-deepseek-mcp-http-cross-session-authorization-bypass",
        language: "javascript-typescript",
        scope: "same-file",
        source: {
          kind: "unauthenticated-multi-client-http-mcp-session",
          path: launch.file.path,
          line: launch.sourceLine,
        },
        sink: {
          kind: sinkKind,
          path: launch.file.path,
          line: launch.sinkLine,
          cweIds: ["CWE-639"],
        },
        propagators: [
          {
            kind: "deepseek-mcp-http-launch-configuration",
            path: launch.file.path,
            line: launch.sourceLine,
            symbol: `${launch.route}:TRANSPORT=http`,
          },
          {
            kind: "deepseek-mcp-runtime-dependency",
            path: launch.dependency.manifestPath,
            line: launch.dependency.line,
            symbol: `@arikusi/deepseek-mcp-server@${launch.dependency.version}:${launch.dependency.proof}:process-global-session-store`,
          },
        ],
        candidateControls: [],
      },
    };
  });
}

interface PythonChainlitApplicationImport {
  file: SourceFileSnapshot;
  line: number;
  symbol: string;
}

interface PythonChainlitMcpConfig {
  file: SourceFileSnapshot;
  enabledLine: number;
  stdioLine: number;
  allowedLine: number;
  executablePolicy: string;
}

const PYTHON_CHAINLIT_COMMAND_CAPABLE_EXECUTABLES = new Set([
  "bash",
  "bun",
  "cmd",
  "deno",
  "node",
  "npm",
  "npx",
  "pnpm",
  "powershell",
  "pwsh",
  "python",
  "python3",
  "sh",
  "uv",
  "uvx",
  "yarn",
]);

function pythonChainlitVersionHasMcpStdioCommandInjection(
  version: string,
): boolean {
  if (!/^\d+\.\d+\.\d+$/u.test(version)) return false;
  return (
    pythonPackageVersionAtLeast(version, [2, 4, 0]) &&
    pythonPackageVersionAtMost(version, [2, 11, 1])
  );
}

function tomlTableKeyLine(
  file: SourceFileSnapshot,
  table: string,
  key: string,
): number | undefined {
  const normalizedTable = table.replaceAll(/\s+/gu, "").toLowerCase();
  const normalizedKey = key.toLowerCase();
  let activeTable = "";
  let tableLine: number | undefined;
  for (let index = 0; index < file.lines.length; index += 1) {
    const line = file.lines[index] ?? "";
    const header = /^\s*\[\s*([^\]]+?)\s*\]\s*(?:#.*)?$/u.exec(line);
    if (header?.[1] !== undefined) {
      activeTable = header[1].replaceAll(/\s+/gu, "").toLowerCase();
      if (activeTable === normalizedTable) tableLine = index + 1;
      continue;
    }
    const direct = new RegExp(
      `^\\s*${escapeRegularExpression(table)}\\s*\\.\\s*${escapeRegularExpression(key)}\\s*=`,
      "iu",
    );
    if (direct.test(line)) return index + 1;
    if (
      activeTable === normalizedTable &&
      new RegExp(
        `^\\s*${escapeRegularExpression(normalizedKey)}\\s*=`,
        "iu",
      ).test(line)
    ) {
      return index + 1;
    }
  }
  return tableLine;
}

function pythonChainlitMcpConfig(
  files: readonly SourceFileSnapshot[],
  sourcePath: string,
): PythonChainlitMcpConfig | undefined {
  let directory = posix.dirname(sourcePath.replaceAll("\\", "/"));
  while (true) {
    const prefix = directory === "." ? "" : `${directory}/`;
    const configPath = `${prefix}.chainlit/config.toml`.toLowerCase();
    const candidates = files.filter(
      (file) => file.path.replaceAll("\\", "/").toLowerCase() === configPath,
    );
    if (candidates.length > 0) {
      if (candidates.length !== 1) return undefined;
      const file = candidates[0]!;
      let parsed: unknown;
      try {
        parsed = parseToml(file.text);
      } catch {
        return undefined;
      }
      if (!isRecord(parsed)) return undefined;
      const features = parsed["features"];
      if (!isRecord(features)) return undefined;
      const mcp = features["mcp"];
      if (!isRecord(mcp) || mcp["enabled"] !== true) return undefined;
      const stdio = mcp["stdio"];
      if (stdio !== undefined && !isRecord(stdio)) return undefined;
      if (isRecord(stdio) && stdio["enabled"] === false) return undefined;
      if (
        isRecord(stdio) &&
        stdio["enabled"] !== undefined &&
        typeof stdio["enabled"] !== "boolean"
      ) {
        return undefined;
      }
      const allowed = isRecord(stdio)
        ? stdio["allowed_executables"]
        : undefined;
      let executablePolicy: string;
      if (allowed === undefined) {
        executablePolicy =
          "allowed_executables omitted: all executables allowed";
      } else {
        if (
          !Array.isArray(allowed) ||
          allowed.length === 0 ||
          allowed.some((entry) => typeof entry !== "string")
        ) {
          return undefined;
        }
        const commandCapable = allowed
          .map((entry) => entry.toLowerCase())
          .filter((entry) =>
            PYTHON_CHAINLIT_COMMAND_CAPABLE_EXECUTABLES.has(entry),
          );
        if (commandCapable.length === 0) return undefined;
        executablePolicy = `command-capable allowlist: ${commandCapable.join(",")}`;
      }
      const enabledLine = tomlTableKeyLine(file, "features.mcp", "enabled");
      const stdioLine =
        tomlTableKeyLine(file, "features.mcp.stdio", "enabled") ?? enabledLine;
      const allowedLine =
        tomlTableKeyLine(file, "features.mcp.stdio", "allowed_executables") ??
        stdioLine;
      if (
        enabledLine === undefined ||
        stdioLine === undefined ||
        allowedLine === undefined
      ) {
        return undefined;
      }
      return {
        file,
        enabledLine,
        stdioLine,
        allowedLine,
        executablePolicy,
      };
    }
    if (directory === ".") break;
    const parent = posix.dirname(directory);
    if (parent === directory) break;
    directory = parent;
  }
  return undefined;
}

function pythonChainlitApplicationImports(
  files: readonly SourceFileSnapshot[],
): PythonChainlitApplicationImport[] {
  const imports: PythonChainlitApplicationImport[] = [];
  for (const file of files) {
    if (
      !PYTHON_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path) ||
      !file.text.includes("chainlit") ||
      pythonLocalModuleCouldShadow(files, file.path, "chainlit")
    ) {
      continue;
    }
    const structuralLines = pythonStructuralLines(file.lines);
    for (let index = 0; index < structuralLines.length; index += 1) {
      const structural = structuralLines[index] ?? "";
      if (/^\s/u.test(structural)) continue;
      const moduleImport =
        /^import\s+chainlit(?:\s+as\s+([A-Za-z_]\w*))?\s*$/u.exec(structural);
      if (moduleImport !== null) {
        imports.push({
          file,
          line: index + 1,
          symbol: `import chainlit as ${moduleImport[1] ?? "chainlit"}`,
        });
        break;
      }
      const fromImport = /^from\s+chainlit\s+import\s+(.+?)\s*$/u.exec(
        structural,
      );
      if (fromImport?.[1] !== undefined && fromImport[1] !== "*") {
        imports.push({
          file,
          line: index + 1,
          symbol: `from chainlit import ${fromImport[1]}`,
        });
        break;
      }
    }
  }
  return imports;
}

function pythonChainlitMcpStdioCommandInjectionRecords(
  files: readonly SourceFileSnapshot[],
): ResidualRiskRecord[] {
  const records: ResidualRiskRecord[] = [];
  for (const application of pythonChainlitApplicationImports(files)) {
    const dependency = pythonPinnedRequirement(
      files,
      application.file.path,
      "chainlit",
    );
    if (
      dependency === undefined ||
      !pythonChainlitVersionHasMcpStdioCommandInjection(dependency.version)
    ) {
      continue;
    }
    const config = pythonChainlitMcpConfig(files, application.file.path);
    if (config === undefined) continue;
    const startLine = Math.max(1, application.line - CONTEXT_LINES_BEFORE);
    const endLine = Math.min(
      application.file.lines.length,
      application.line + CONTEXT_LINES_AFTER,
    );
    const sourceStart = Math.max(1, config.enabledLine - 2);
    const sourceEnd = Math.min(
      config.file.lines.length,
      config.allowedLine + 2,
    );
    records.push({
      path: application.file.path,
      line: application.line,
      categories: [
        "framework-dataflow:python-chainlit-mcp-stdio-command-injection",
        "modeled-source:remote-chainlit-mcp-fullcommand-request",
        "modeled-sink:chainlit-affected-mcp-stdio-client-command-spawn",
        "broken-control:chainlit-mcp-executable-only-allowlist",
      ],
      priority: 126,
      startLine,
      endLine,
      excerpt: sourceExcerpt(application.file.lines, startLine, endLine),
      sourceExcerpt: sourceExcerpt(config.file.lines, sourceStart, sourceEnd),
      frameworkModel: {
        schemaVersion: "1.2",
        id: "python-chainlit-mcp-stdio-command-injection",
        language: "python",
        scope: "cross-file",
        source: {
          kind: "remote-chainlit-mcp-fullcommand-request",
          path: config.file.path,
          line: config.enabledLine,
        },
        sink: {
          kind: "chainlit-affected-mcp-stdio-client-command-spawn",
          path: application.file.path,
          line: application.line,
          cweIds: ["CWE-78"],
        },
        propagators: [
          {
            kind: "chainlit-application-import",
            path: application.file.path,
            line: application.line,
            symbol: application.symbol,
          },
          {
            kind: "chainlit-runtime-dependency",
            path: dependency.path,
            line: dependency.line,
            symbol: `chainlit@${dependency.version}:requirements-exact:mcp-fullcommand`,
          },
          {
            kind: "chainlit-mcp-enabled-configuration",
            path: config.file.path,
            line: config.enabledLine,
            symbol: "features.mcp.enabled=true",
          },
          {
            kind: "chainlit-mcp-stdio-command-capability",
            path: config.file.path,
            line: config.allowedLine,
            symbol: config.executablePolicy,
          },
          {
            kind: "intrinsic-chainlit-mcp-request-command-source",
            path: config.file.path,
            line: config.stdioLine,
            symbol: "POST /mcp clientType=stdio fullCommand",
          },
          {
            kind: "intrinsic-chainlit-executable-only-validation",
            path: config.file.path,
            line: config.allowedLine,
            symbol: "shlex.split -> allowed executable; arguments unchecked",
          },
          {
            kind: "intrinsic-chainlit-stdio-process-spawn",
            path: application.file.path,
            line: application.line,
            symbol: "StdioServerParameters -> stdio_client",
          },
        ],
        candidateControls: [],
      },
    });
  }
  return records;
}

interface NodeContentfulMcpLaunch {
  dependency: NodeRuntimeDependency;
  file: SourceFileSnapshot;
  line: number;
  route: "module-import" | "operational-npm-script";
}

function nodeContentfulMcpVersionLeaksManagementToken(
  version: string,
): boolean {
  const match = /^(\d+)\.(\d+)\.(\d+)$/u.exec(version);
  if (match === null) return false;
  const [major, minor, patch] = match.slice(1).map(Number) as [
    number,
    number,
    number,
  ];
  return (
    major < 1 || (major === 1 && (minor < 7 || (minor === 7 && patch < 19)))
  );
}

function nodeContentfulMcpOperationalScriptCommand(command: string): boolean {
  const invocation = String.raw`(?:contentful-mcp-server|npx(?:\s+--yes)?\s+@contentful/mcp-server|npm\s+exec(?:\s+--yes)?\s+(?:--\s+)?@contentful/mcp-server)`;
  const posix = new RegExp(
    String.raw`^(?:(?:cross-env(?:-shell)?|env)\s+)?(?:(?:[A-Za-z_][A-Za-z0-9_]*=(?:[^\s;&|]+|"[^"]*"|'[^']*'))\s+)*${invocation}(?:\s|$)`,
    "u",
  );
  if (posix.test(command.trim())) return true;
  return new RegExp(
    String.raw`^set\s+(?:"[A-Za-z_][A-Za-z0-9_]*=[^"]*"|[A-Za-z_][A-Za-z0-9_]*=[^&|]*)\s*&&\s*(?:call\s+)?${invocation}(?:\s|$)`,
    "u",
  ).test(command.trim());
}

function nodeContentfulMcpModuleLaunches(
  files: readonly SourceFileSnapshot[],
): NodeContentfulMcpLaunch[] {
  const launches: NodeContentfulMcpLaunch[] = [];
  for (const file of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path) ||
      !file.text.includes("@contentful/mcp-server")
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(
      files,
      file.path,
      "@contentful/mcp-server",
    );
    if (
      dependency === undefined ||
      !nodeContentfulMcpVersionLeaksManagementToken(dependency.version)
    ) {
      continue;
    }
    const codeLines = javascriptCodeLinesWithoutComments(file.lines);
    const structuralLines = javascriptStructuralLines(file.lines);
    for (let index = 0; index < codeLines.length; index += 1) {
      const code = codeLines[index] ?? "";
      if (
        !javascriptModuleScopeLine(structuralLines, index + 1) ||
        !(
          /^\s*import\s*["']@contentful\/mcp-server["']\s*;?\s*$/u.test(code) ||
          /\b(?:await\s+)?import\s*\(\s*["']@contentful\/mcp-server["']\s*\)/u.test(
            code,
          )
        )
      ) {
        continue;
      }
      launches.push({
        dependency,
        file,
        line: index + 1,
        route: "module-import",
      });
    }
  }
  return launches;
}

function nodeContentfulMcpScriptLaunches(
  files: readonly SourceFileSnapshot[],
): NodeContentfulMcpLaunch[] {
  const launches: NodeContentfulMcpLaunch[] = [];
  for (const file of files) {
    if (
      posix.basename(file.path) !== "package.json" ||
      javascriptTestOrExamplePath(file.path)
    ) {
      continue;
    }
    let root: Record<string, unknown>;
    try {
      const parsed = JSON.parse(file.text) as unknown;
      if (
        typeof parsed !== "object" ||
        parsed === null ||
        Array.isArray(parsed)
      ) {
        continue;
      }
      root = parsed as Record<string, unknown>;
    } catch {
      continue;
    }
    const scripts = root["scripts"];
    if (
      typeof scripts !== "object" ||
      scripts === null ||
      Array.isArray(scripts)
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(
      files,
      file.path,
      "@contentful/mcp-server",
    );
    if (
      dependency === undefined ||
      !nodeContentfulMcpVersionLeaksManagementToken(dependency.version)
    ) {
      continue;
    }
    for (const [name, value] of Object.entries(
      scripts as Record<string, unknown>,
    ).sort(([left], [right]) => left.localeCompare(right))) {
      if (
        typeof value !== "string" ||
        !/^(?:mcp|serve|server|start)(?::[A-Za-z0-9._-]+)?$/u.test(name) ||
        !nodeContentfulMcpOperationalScriptCommand(value)
      ) {
        continue;
      }
      const serializedName = JSON.stringify(name);
      const line =
        file.lines.findIndex(
          (candidate) =>
            candidate.includes(serializedName) && candidate.includes(":"),
        ) + 1;
      launches.push({
        dependency,
        file,
        line: Math.max(1, line),
        route: "operational-npm-script",
      });
    }
  }
  return launches;
}

function nodeContentfulMcpManagementTokenLeakRecords(
  files: readonly SourceFileSnapshot[],
): ResidualRiskRecord[] {
  const launches = [
    ...nodeContentfulMcpModuleLaunches(files),
    ...nodeContentfulMcpScriptLaunches(files),
  ].filter(
    (launch, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.file.path === launch.file.path &&
          candidate.line === launch.line,
      ) === index,
  );
  return launches.map((launch) => {
    const startLine = Math.max(1, launch.line - CONTEXT_LINES_BEFORE);
    const endLine = Math.min(
      launch.file.lines.length,
      launch.line + CONTEXT_LINES_AFTER,
    );
    const prefix =
      launch.dependency.proof === "npm-lockfile" ? "lock-resolved-" : "";
    const sinkKind = `${prefix}vulnerable-contentful-mcp-management-token-authorized-request`;
    return {
      path: launch.file.path,
      line: launch.line,
      categories: [
        "framework-dataflow:node-contentful-mcp-management-token-host-redirect",
        "modeled-source:llm-controlled-contentful-migration-network-options",
        `modeled-sink:${sinkKind}`,
        "broken-control:mcp-tool-network-destination-not-pinned",
      ],
      priority: 124,
      startLine,
      endLine,
      excerpt: sourceExcerpt(launch.file.lines, startLine, endLine),
      frameworkModel: {
        schemaVersion: "1.2",
        id: "node-contentful-mcp-management-token-host-redirect",
        language: "javascript-typescript",
        scope: "same-file",
        source: {
          kind: "llm-controlled-contentful-migration-network-options",
          path: launch.file.path,
          line: launch.line,
        },
        sink: {
          kind: sinkKind,
          path: launch.file.path,
          line: launch.line,
          cweIds: ["CWE-918", "CWE-441"],
        },
        propagators: [
          {
            kind: "contentful-mcp-operational-launch",
            path: launch.file.path,
            line: launch.line,
            symbol: launch.route,
          },
          {
            kind: "contentful-mcp-runtime-dependency",
            path: launch.dependency.manifestPath,
            line: launch.dependency.line,
            symbol: `@contentful/mcp-server@${launch.dependency.version}:${launch.dependency.proof}:unpinned-migration-cma-host`,
          },
        ],
        candidateControls: [],
      },
    };
  });
}

interface NodeNextJsRouteSegment {
  kind: "dynamic" | "static";
  value: string;
}

interface NodeNextJsDynamicRoute {
  file: SourceFileSnapshot;
  parameter: string;
  segments: NodeNextJsRouteSegment[];
  sinkLine: number;
  sinkSymbol: string;
}

interface NodeNextJsMiddlewareGate {
  deniedPath: string;
  file: SourceFileSnapshot;
  line: number;
}

function nodeNextJsVersionHasDynamicRouteAuthorizationBypass(
  version: string,
): boolean {
  if (version.includes("-")) return false;
  const parts = version.split(".").map(Number);
  if (parts.length !== 3 || parts.some((part) => !Number.isSafeInteger(part))) {
    return false;
  }
  const [major, minor, patch] = parts as [number, number, number];
  if (major === 15) {
    return minor === 4 || (minor === 5 && patch < 16);
  }
  return major === 16 && (minor < 2 || (minor === 2 && patch < 5));
}

function nodeNextJsRouteSegments(
  path: string,
): { parameter: string; segments: NodeNextJsRouteSegment[] } | undefined {
  const parts = path.replaceAll("\\", "/").split("/");
  const extension = extname(parts.at(-1) ?? "").toLowerCase();
  if (!JAVASCRIPT_EXTENSIONS.has(extension)) return undefined;
  let routeParts: string[] | undefined;
  const appIndex = parts.lastIndexOf("app");
  if (appIndex >= 0 && /^page\.(?:[cm]?[jt]sx?)$/u.test(parts.at(-1) ?? "")) {
    routeParts = parts.slice(appIndex + 1, -1);
  } else {
    const pagesIndex = parts.lastIndexOf("pages");
    if (pagesIndex < 0) return undefined;
    routeParts = parts.slice(pagesIndex + 1);
    const filename = routeParts.pop();
    if (filename === undefined) return undefined;
    const stem = filename.slice(0, -extension.length);
    if (stem !== "index") routeParts.push(stem);
  }
  routeParts = routeParts.filter(
    (part) => !/^\(.+\)$/u.test(part) && !part.startsWith("@"),
  );
  const segments: NodeNextJsRouteSegment[] = [];
  const parameters: string[] = [];
  for (const part of routeParts) {
    const dynamic =
      /^\[(?:\.\.\.)?([A-Za-z_$][\w$]*)\]$/u.exec(part) ??
      /^\[\[\.\.\.([A-Za-z_$][\w$]*)\]\]$/u.exec(part);
    if (dynamic?.[1] !== undefined) {
      parameters.push(dynamic[1]);
      segments.push({ kind: "dynamic", value: dynamic[1] });
    } else if (part !== "") {
      segments.push({ kind: "static", value: part });
    }
  }
  if (parameters.length !== 1 || segments.length === 0) return undefined;
  return { parameter: parameters[0]!, segments };
}

function nodeNextJsRouteLocalAuthorization(file: SourceFileSnapshot): boolean {
  return /\b(?:auth|getServerSession|getSession|getToken|requireAuth|authorize|authorized|checkPermission|canAccess|canRead|cookies|headers)\s*(?:\(|\.)|\b(?:redirect|unauthorized|forbidden)\s*\(/iu.test(
    javascriptCodeLinesWithoutComments(file.lines).join("\n"),
  );
}

function nodeNextJsSensitiveRouteParamSink(
  file: SourceFileSnapshot,
  parameter: string,
): { line: number; symbol: string } | undefined {
  if (nodeNextJsRouteLocalAuthorization(file)) return undefined;
  const codeLines = javascriptCodeLinesWithoutComments(file.lines);
  const structuralLines = javascriptStructuralLines(file.lines);
  const escapedParameter = escapeRegularExpression(parameter);
  const references = new Map<string, number>([
    [`params.${parameter}`, 0],
    [`params?.${parameter}`, 0],
    [`params["${parameter}"]`, 0],
    [`params['${parameter}']`, 0],
    [`(await params).${parameter}`, 0],
  ]);
  const destructure = new RegExp(
    String.raw`\b(?:const|let|var)\s*\{\s*${escapedParameter}(?:\s*:\s*([A-Za-z_$][\w$]*))?\s*\}\s*=\s*(?:await\s+)?params\b`,
    "u",
  );
  for (let index = 0; index < codeLines.length; index += 1) {
    const match = destructure.exec(codeLines[index] ?? "");
    if (match !== null) references.set(match[1] ?? parameter, index + 1);
  }
  const nestedParameter = new RegExp(
    String.raw`\bparams\s*:\s*\{[^}]*\b${escapedParameter}(?:\s*:\s*([A-Za-z_$][\w$]*))?\b`,
    "u",
  ).exec(codeLines.join("\n"));
  if (nestedParameter !== null)
    references.set(nestedParameter[1] ?? parameter, 1);
  const sensitiveCall =
    /\b(?:fetch|query|retrieve|lookup|open|read|find|get|load)[A-Za-z0-9_$]*(?:\s*\.\s*(?:findUnique|findFirst|findMany|findOne|get|query|select))?\s*\(|\.\s*(?:findUnique|findFirst|findMany|findOne|query|select)\s*\(/iu;
  for (let index = 0; index < structuralLines.length; index += 1) {
    const currentLine = structuralLines[index] ?? "";
    const currentCall = sensitiveCall.exec(currentLine);
    if (
      /\b(?:async\s+)?function\s+[A-Za-z_$][\w$]*\s*\(/u.test(currentLine) ||
      currentCall === null
    ) {
      continue;
    }
    const callLines: string[] = [];
    let depth = 0;
    let started = false;
    let complete = false;
    for (
      let callIndex = index;
      callIndex < Math.min(structuralLines.length, index + 8);
      callIndex += 1
    ) {
      const line = structuralLines[callIndex] ?? "";
      callLines.push(codeLines[callIndex] ?? "");
      const startColumn = callIndex === index ? currentCall.index : 0;
      for (let column = startColumn; column < line.length; column += 1) {
        if (line[column] === "(") {
          depth += 1;
          started = true;
        } else if (line[column] === ")" && started) {
          depth -= 1;
          if (depth === 0) {
            complete = true;
            break;
          }
        }
      }
      if (complete) break;
    }
    if (!complete) continue;
    const window = callLines.join("\n");
    const reference = [...references].find(([candidate]) =>
      candidate.includes(".") || candidate.includes("[")
        ? window.includes(candidate)
        : new RegExp(`\\b${escapeRegularExpression(candidate)}\\b`, "u").test(
            window,
          ),
    );
    if (reference === undefined) continue;
    if (
      /^[A-Za-z_$][\w$]*$/u.test(reference[0]) &&
      javascriptIdentifierReassignedBetween(
        file.lines,
        reference[0],
        reference[1],
        index + 2,
      )
    ) {
      continue;
    }
    const call = sensitiveCall.exec(window)?.[0]?.replace(/\s+/gu, " ").trim();
    return { line: index + 1, symbol: `${parameter}:${call ?? "data-access"}` };
  }
  return undefined;
}

function nodeNextJsDynamicRoutes(
  files: readonly SourceFileSnapshot[],
): NodeNextJsDynamicRoute[] {
  const routes: NodeNextJsDynamicRoute[] = [];
  for (const file of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path)
    ) {
      continue;
    }
    const route = nodeNextJsRouteSegments(file.path);
    if (route === undefined) continue;
    const sink = nodeNextJsSensitiveRouteParamSink(file, route.parameter);
    if (sink === undefined) continue;
    routes.push({
      file,
      parameter: route.parameter,
      segments: route.segments,
      sinkLine: sink.line,
      sinkSymbol: sink.symbol,
    });
  }
  return routes;
}

function nodeNextJsDeniedRouteValue(
  route: NodeNextJsDynamicRoute,
  deniedPath: string,
): string | undefined {
  if (!deniedPath.startsWith("/") || /[?#]/u.test(deniedPath)) return undefined;
  const pathSegments = deniedPath.split("/").filter(Boolean);
  if (pathSegments.length !== route.segments.length) return undefined;
  let dynamicValue: string | undefined;
  for (let index = 0; index < route.segments.length; index += 1) {
    const segment = route.segments[index]!;
    const value = pathSegments[index]!;
    if (segment.kind === "static" && segment.value !== value) return undefined;
    if (segment.kind === "dynamic") dynamicValue = value;
  }
  return dynamicValue === "" ? undefined : dynamicValue;
}

function nodeNextJsMatcherCoversRoute(
  file: SourceFileSnapshot,
  route: NodeNextJsDynamicRoute,
): boolean {
  const text = javascriptCodeLinesWithoutComments(file.lines).join("\n");
  const matcherIndex = text.search(/\bmatcher\s*:/u);
  if (matcherIndex < 0) return true;
  const matcherText = text.slice(matcherIndex, matcherIndex + 1000);
  const literals = [...matcherText.matchAll(/["']([^"']+)["']/gu)].map(
    (match) => match[1] ?? "",
  );
  const dynamicIndex = route.segments.findIndex(
    (segment) => segment.kind === "dynamic",
  );
  const staticPrefix =
    "/" +
    route.segments
      .slice(0, dynamicIndex)
      .map((segment) => segment.value)
      .join("/");
  return literals.some(
    (literal) =>
      literal === staticPrefix ||
      literal.startsWith(`${staticPrefix}/`) ||
      literal.includes(`${staticPrefix}/:`),
  );
}

function nodeNextJsMiddlewareGates(
  files: readonly SourceFileSnapshot[],
  route: NodeNextJsDynamicRoute,
): NodeNextJsMiddlewareGate[] {
  const gates: NodeNextJsMiddlewareGate[] = [];
  for (const file of files) {
    const basename = posix.basename(file.path);
    if (
      !/^(?:middleware|proxy)\.[cm]?[jt]sx?$/u.test(basename) ||
      javascriptTestOrExamplePath(file.path) ||
      !/["']next\/server["']/u.test(file.text) ||
      !nodeNextJsMatcherCoversRoute(file, route)
    ) {
      continue;
    }
    const codeLines = javascriptCodeLinesWithoutComments(file.lines);
    const aliases = new Set<string>();
    for (const line of codeLines) {
      const alias =
        /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*[A-Za-z_$][\w$]*\s*\.\s*nextUrl\s*\.\s*pathname\b/u.exec(
          line,
        );
      if (alias?.[1] !== undefined) aliases.add(alias[1]);
    }
    const pathname = String.raw`(?:[A-Za-z_$][\w$]*\s*\.\s*nextUrl\s*\.\s*pathname${
      aliases.size === 0
        ? ""
        : `|${[...aliases].map(escapeRegularExpression).join("|")}`
    })`;
    const condition = new RegExp(
      String.raw`\bif\s*\([^)]*(?:${pathname}\s*={2,3}\s*["']([^"']+)["']|["']([^"']+)["']\s*={2,3}\s*${pathname})[^)]*\)`,
      "u",
    );
    for (let index = 0; index < codeLines.length; index += 1) {
      if (!/\bif\s*\(/u.test(codeLines[index] ?? "")) continue;
      const conditionWindow = codeLines
        .slice(index, Math.min(codeLines.length, index + 4))
        .join(" ");
      const match = condition.exec(conditionWindow);
      const deniedPath = match?.[1] ?? match?.[2];
      if (deniedPath === undefined) continue;
      const denialWindow = codeLines
        .slice(index, Math.min(codeLines.length, index + 10))
        .join("\n");
      if (
        !/\breturn\b/u.test(denialWindow) ||
        !/(?:NextResponse|new\s+Response|Response\s*\.\s*redirect)/u.test(
          denialWindow,
        ) ||
        !/(?:status\s*:\s*(?:401|403)\b|Unauthorized|Forbidden|["']\/(?:login|signin)(?:[/?"']))/iu.test(
          denialWindow,
        )
      ) {
        continue;
      }
      gates.push({ deniedPath, file, line: index + 1 });
    }
  }
  return gates;
}

function nodeNextJsDynamicRouteAuthorizationRecords(
  files: readonly SourceFileSnapshot[],
): ResidualRiskRecord[] {
  const records: ResidualRiskRecord[] = [];
  const emitted = new Set<string>();
  for (const route of nodeNextJsDynamicRoutes(files)) {
    const dependency = nodeRuntimeDependency(files, route.file.path, "next");
    if (
      dependency === undefined ||
      !nodeNextJsVersionHasDynamicRouteAuthorizationBypass(dependency.version)
    ) {
      continue;
    }
    for (const gate of nodeNextJsMiddlewareGates(files, route)) {
      const deniedValue = nodeNextJsDeniedRouteValue(route, gate.deniedPath);
      if (deniedValue === undefined) continue;
      const gateDependency = nodeRuntimeDependency(
        files,
        gate.file.path,
        "next",
      );
      if (
        gateDependency === undefined ||
        gateDependency.manifestPath !== dependency.manifestPath ||
        gateDependency.version !== dependency.version ||
        gateDependency.proof !== dependency.proof
      ) {
        continue;
      }
      const key = `${gate.file.path}\0${gate.line}\0${route.file.path}\0${route.sinkLine}`;
      if (emitted.has(key)) continue;
      emitted.add(key);
      const prefix =
        dependency.proof === "npm-lockfile" ? "lock-resolved-" : "";
      const sinkKind = `${prefix}vulnerable-nextjs-dynamic-route-param-data-access`;
      const startLine = Math.max(1, route.sinkLine - CONTEXT_LINES_BEFORE);
      const endLine = Math.min(
        route.file.lines.length,
        route.sinkLine + CONTEXT_LINES_AFTER,
      );
      const sourceStart = Math.max(1, gate.line - 2);
      const sourceEnd = Math.min(gate.file.lines.length, gate.line + 5);
      records.push({
        path: route.file.path,
        line: route.sinkLine,
        categories: [
          "framework-dataflow:node-nextjs-dynamic-route-param-authorization-bypass",
          "modeled-source:external-next-internal-route-param-query-injection",
          `modeled-sink:${sinkKind}`,
          "broken-control:visible-pathname-only-middleware-authorization",
        ],
        priority: 126,
        startLine,
        endLine,
        excerpt: sourceExcerpt(route.file.lines, startLine, endLine),
        sourceExcerpt: sourceExcerpt(gate.file.lines, sourceStart, sourceEnd),
        frameworkModel: {
          schemaVersion: "1.2",
          id: "node-nextjs-dynamic-route-param-authorization-bypass",
          language: "javascript-typescript",
          scope: "cross-file",
          source: {
            kind: "external-next-internal-route-param-query-injection",
            path: gate.file.path,
            line: gate.line,
          },
          sink: {
            kind: sinkKind,
            path: route.file.path,
            line: route.sinkLine,
            cweIds: ["CWE-288"],
          },
          propagators: [
            {
              kind: "nextjs-visible-pathname-authorization-gate",
              path: gate.file.path,
              line: gate.line,
              symbol: gate.deniedPath,
            },
            {
              kind: "nextjs-dynamic-route-parameter",
              path: route.file.path,
              line: 1,
              symbol: `${route.parameter}:nxtP${route.parameter}:${deniedValue}`,
            },
            {
              kind: "nextjs-server-data-access",
              path: route.file.path,
              line: route.sinkLine,
              symbol: route.sinkSymbol,
            },
            {
              kind: "nextjs-runtime-dependency",
              path: dependency.manifestPath,
              line: dependency.line,
              symbol: `next@${dependency.version}:${dependency.proof}:external-nxtP-route-param-normalization`,
            },
          ],
          candidateControls: [],
        },
      });
      if (records.length >= MAX_FRAMEWORK_CROSS_FILE_RECORDS) return records;
    }
  }
  return records;
}

interface NodePlateMediaReactBinding {
  line: number;
  local: string;
  member?: "MediaEmbedPlugin" | "useMediaState";
}

interface NodePlateExportedComponent {
  endLine: number;
  parameters: string;
  startLine: number;
  symbol: string;
}

interface NodePlateMediaIframeSink {
  component: NodePlateExportedComponent;
  dependency: NodeRuntimeDependency;
  file: SourceFileSnapshot;
  hookLine: number;
  iframeLine: number;
  parserSymbol: string;
}

interface NodePlateMediaRenderer {
  component: NodePlateExportedComponent;
  componentImportLine: number;
  dependency: NodeRuntimeDependency;
  file: SourceFileSnapshot;
  mediaComponentSymbol: string;
  plateLine: number;
  pluginLine: number;
  pluginSymbol: string;
  propName: string;
  sink: NodePlateMediaIframeSink;
}

interface NodePlateMediaSource {
  file: SourceFileSnapshot;
  line: number;
  renderer: NodePlateMediaRenderer;
  rendererImportLine: number;
  rendererUseLine: number;
  symbol: string;
}

function nodePlateMediaVersionHasEmbedMetadataXss(version: string): boolean {
  const match = /^(\d+)\.(\d+)\.(\d+)$/u.exec(version);
  if (match === null) return false;
  const [major, minor, patch] = match.slice(1).map(Number);
  return (
    major === 53 &&
    ((minor === 0 && patch !== undefined) ||
      (minor === 1 && patch !== undefined && patch < 4))
  );
}

function nodePlateMediaBindingPattern(
  binding: NodePlateMediaReactBinding,
): string {
  const local = escapeRegularExpression(binding.local);
  return binding.member === undefined
    ? local
    : `${local}\\s*\\.\\s*${binding.member}`;
}

function nodePlateMediaReactBindings(
  lines: readonly string[],
  imported: "MediaEmbedPlugin" | "useMediaState",
): NodePlateMediaReactBinding[] {
  const bindings: NodePlateMediaReactBinding[] = importedJavascriptSymbols(
    lines,
  )
    .filter(
      (binding) =>
        binding.moduleSpecifier === "@platejs/media/react" &&
        binding.imported === imported,
    )
    .map((binding) => ({ line: binding.line, local: binding.local }));
  for (let index = 0; index < lines.length; index += 1) {
    const code = javascriptCodeBeforeComment(lines[index] ?? "");
    const receiver =
      /^\s*import\s+\*\s+as\s+([A-Za-z_$][\w$]*)\s+from\s+["']@platejs\/media\/react["']/u.exec(
        code,
      ) ??
      /^\s*import\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["']@platejs\/media\/react["']\s*\)/u.exec(
        code,
      ) ??
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["']@platejs\/media\/react["']\s*\)\s*;?\s*$/u.exec(
        code,
      );
    if (receiver?.[1] !== undefined) {
      bindings.push({ line: index + 1, local: receiver[1], member: imported });
    }
    const direct = new RegExp(
      `^\\s*(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*require\\s*\\(\\s*["']@platejs/media/react["']\\s*\\)\\s*\\.\\s*${imported}\\s*;?\\s*$`,
      "u",
    ).exec(code);
    if (direct?.[1] !== undefined) {
      bindings.push({ line: index + 1, local: direct[1] });
    }
  }
  return bindings.filter(
    (binding, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.line === binding.line &&
          candidate.local === binding.local &&
          candidate.member === binding.member,
      ) === index,
  );
}

function nodePlateMediaBindingUsable(
  lines: readonly string[],
  binding: NodePlateMediaReactBinding,
  useLine: number,
): boolean {
  if (
    binding.line >= useLine ||
    javascriptIdentifierReassignedBetween(
      lines,
      binding.local,
      binding.line,
      useLine + 1,
    )
  ) {
    return false;
  }
  const wrapper = exportedJavascriptFunctions(lines).find(
    (candidate) =>
      useLine >= candidate.startLine && useLine <= candidate.endLine,
  );
  if (wrapper?.parameters.includes(binding.local) === true) return false;
  if (binding.member === undefined) return true;
  const local = escapeRegularExpression(binding.local);
  const member = escapeRegularExpression(binding.member);
  const replacement = new RegExp(
    `\\b${local}\\s*\\.\\s*${member}\\s*(?:[+\\-*/%&|^?]?=(?!=|>)|\\+\\+|--)`,
    "u",
  );
  return !javascriptStructuralLines(lines)
    .slice(binding.line, Math.max(binding.line, useLine - 1))
    .some((line) => replacement.test(line));
}

function nodePlateExportedComponents(
  file: SourceFileSnapshot,
): NodePlateExportedComponent[] {
  const components: NodePlateExportedComponent[] = [];
  const structural = javascriptStructuralLines(file.lines);
  const patterns = [
    /^\s*export\s+(?:async\s+)?function\s+([A-Za-z_$][\w$]*)\s*\(([^)]*)\)\s*\{/u,
    /^\s*export\s+(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*(?:async\s*)?\(([^)]*)\)\s*=>/u,
    /^\s*export\s+(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*(?:async\s*)?([A-Za-z_$][\w$]*)\s*=>/u,
  ];
  for (let index = 0; index < structural.length; index += 1) {
    if (!/^\s*export\b/u.test(structural[index] ?? "")) continue;
    const declaration = structural
      .slice(index, Math.min(structural.length, index + 13))
      .join("\n");
    const match = patterns
      .map((pattern) => pattern.exec(declaration))
      .find((candidate) => candidate !== null);
    if (match === undefined || match === null) continue;
    components.push({
      endLine: javascriptFunctionEndLine(file.lines, index),
      parameters: match[2] ?? "",
      startLine: index + 1,
      symbol: match[1]!,
    });
  }
  return components;
}

function nodePlateMediaHasUrlParsers(
  lines: readonly string[],
  expression: string,
  line: number,
): { line: number; symbol: string } | undefined {
  const resolved = resolveJavascriptExpression(lines, expression, line);
  if (resolved === undefined) return undefined;
  const object = javascriptCompositePrefix(resolved.value, "{", "}");
  if (object === undefined) return undefined;
  const rawEntries = javascriptDelimitedEntries(object.slice(1, -1));
  if (rawEntries.some((entry) => /^\.\.\./u.test(entry.value.trim()))) {
    return undefined;
  }
  const entries = javascriptObjectEntries(resolved).filter(
    (entry) => entry.key === "urlParsers",
  );
  if (entries.length !== 1) return undefined;
  const parsers = resolveJavascriptExpression(
    lines,
    entries[0]!.value,
    entries[0]!.line,
  );
  if (parsers === undefined) return undefined;
  const array = javascriptCompositePrefix(parsers.value, "[", "]");
  if (array === undefined) return undefined;
  const values = javascriptDelimitedEntries(array.slice(1, -1))
    .map((entry) => entry.value.trim())
    .filter(Boolean);
  if (values.length === 0 || values.some((value) => value.startsWith("..."))) {
    return undefined;
  }
  return { line: entries[0]!.line, symbol: values.join(",") };
}

function nodePlateMediaIframeAllowsScripts(tag: string): boolean {
  if (!/\bsandbox\b/iu.test(tag)) return true;
  return /\bsandbox\s*=\s*(?:["'][^"']*\ballow-scripts\b[^"']*["']|\{\s*["'`][^"'`]*\ballow-scripts\b[^"'`]*["'`]\s*\})/iu.test(
    tag,
  );
}

function nodePlateMediaIframeSinks(
  files: readonly SourceFileSnapshot[],
): NodePlateMediaIframeSink[] {
  const sinks: NodePlateMediaIframeSink[] = [];
  for (const file of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path) ||
      !file.text.includes("@platejs/media/react") ||
      !/<iframe\b/iu.test(file.text)
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(
      files,
      file.path,
      "@platejs/media",
    );
    if (
      dependency === undefined ||
      !nodePlateMediaVersionHasEmbedMetadataXss(dependency.version)
    ) {
      continue;
    }
    const components = nodePlateExportedComponents(file);
    const structural = javascriptStructuralLines(file.lines);
    for (const binding of nodePlateMediaReactBindings(
      file.lines,
      "useMediaState",
    )) {
      const pattern = nodePlateMediaBindingPattern(binding);
      for (let index = binding.line; index < structural.length; index += 1) {
        if (!nodePlateMediaBindingUsable(file.lines, binding, index + 1)) {
          continue;
        }
        const declaration = structural
          .slice(index, Math.min(structural.length, index + 8))
          .join("\n");
        const destructured = new RegExp(
          `^\\s*(?:const|let|var)\\s*\\{([^}]+)\\}\\s*=\\s*${pattern}\\s*\\(`,
          "u",
        ).exec(declaration);
        const state = new RegExp(
          `^\\s*(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*${pattern}\\s*\\(`,
          "u",
        ).exec(declaration);
        if (destructured === null && state === null) continue;
        const arguments_ = javascriptCallArgumentsAtLine(
          file.lines,
          index + 1,
          new RegExp(`\\b${pattern}\\s*\\(`, "u"),
        );
        const parser = nodePlateMediaHasUrlParsers(
          file.lines,
          arguments_?.[0] ?? "",
          index + 1,
        );
        if (parser === undefined) continue;
        let embedExpression: string;
        let isVideoExpression: string;
        if (destructured !== null) {
          const entries = splitJavascriptArguments(destructured[1] ?? "");
          const embed = entries
            .map((entry) =>
              /^\s*embed(?:\s*:\s*([A-Za-z_$][\w$]*))?\s*$/u.exec(entry),
            )
            .find((entry) => entry !== null);
          const isVideo = entries
            .map((entry) =>
              /^\s*isVideo(?:\s*:\s*([A-Za-z_$][\w$]*))?\s*$/u.exec(entry),
            )
            .find((entry) => entry !== null);
          if (embed === undefined || isVideo === undefined) continue;
          embedExpression = embed[1] ?? "embed";
          isVideoExpression = isVideo[1] ?? "isVideo";
        } else {
          const stateLocal = state?.[1];
          if (stateLocal === undefined) continue;
          embedExpression = `${stateLocal}.embed`;
          isVideoExpression = `${stateLocal}.isVideo`;
        }
        const component = components.find(
          (candidate) =>
            index + 1 >= candidate.startLine && index + 1 <= candidate.endLine,
        );
        if (component === undefined) continue;
        const embedPattern = escapeRegularExpression(
          embedExpression,
        ).replaceAll("\\.", "\\s*\\.\\s*");
        const videoPattern = escapeRegularExpression(
          isVideoExpression,
        ).replaceAll("\\.", "\\s*\\.\\s*");
        for (
          let iframeIndex = index;
          iframeIndex < Math.min(structural.length, component.endLine);
          iframeIndex += 1
        ) {
          if (!/<iframe\b/iu.test(structural[iframeIndex] ?? "")) continue;
          const tag = structural
            .slice(iframeIndex, Math.min(component.endLine, iframeIndex + 8))
            .join(" ");
          if (
            !new RegExp(
              `<iframe\\b[^>]*\\bsrc\\s*=\\s*\\{\\s*${embedPattern}\\s*\\?*\\.\\s*url\\s*\\}`,
              "iu",
            ).test(tag) ||
            !nodePlateMediaIframeAllowsScripts(tag)
          ) {
            continue;
          }
          const guard = structural.slice(index, iframeIndex + 1).join("\n");
          const failClosedGuard = new RegExp(
            `\\bif\\s*\\([^)]*!\\s*${videoPattern}[^)]*\\)[\\s\\S]{0,160}\\breturn\\s+(?:null|false)\\b`,
            "u",
          ).test(guard);
          const conditionalRender = new RegExp(
            `\\b${videoPattern}\\s*&&[\\s\\S]{0,160}<iframe\\b`,
            "iu",
          ).test(tag);
          if (!failClosedGuard && !conditionalRender) continue;
          sinks.push({
            component,
            dependency,
            file,
            hookLine: index + 1,
            iframeLine: iframeIndex + 1,
            parserSymbol: parser.symbol,
          });
        }
      }
    }
  }
  return sinks.filter(
    (sink, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.file.path === sink.file.path &&
          candidate.iframeLine === sink.iframeLine,
      ) === index,
  );
}

function nodePlateMediaComponentProp(
  component: NodePlateExportedComponent,
  valueExpression: string,
): string | undefined {
  const value = valueExpression.replace(/\s+/gu, "").trim();
  const parameters = component.parameters.trim();
  const object = javascriptCompositePrefix(parameters, "{", "}");
  if (object !== undefined) {
    for (const raw of splitJavascriptArguments(object.slice(1, -1))) {
      const binding =
        /^\s*([A-Za-z_$][\w$]*)(?:\s*:\s*([A-Za-z_$][\w$]*))?\s*$/u.exec(raw);
      if (binding !== null && value === (binding[2] ?? binding[1])) {
        return binding[1];
      }
    }
  }
  const direct = /^([A-Za-z_$][\w$]*)$/u.exec(parameters);
  if (direct === null) return undefined;
  const property = new RegExp(
    `^${escapeRegularExpression(direct[1]!)}(?:\\?|)\\.([A-Za-z_$][\\w$]*)$`,
    "u",
  ).exec(value);
  return property?.[1];
}

function nodePlateMediaRenderers(
  files: readonly SourceFileSnapshot[],
  sinks: readonly NodePlateMediaIframeSink[],
): NodePlateMediaRenderer[] {
  const renderers: NodePlateMediaRenderer[] = [];
  const knownPaths = new Map(
    files.map((file) => [modelPathComparisonKey(file.path), file.path]),
  );
  for (const file of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path)
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(
      files,
      file.path,
      "@platejs/media",
    );
    if (
      dependency === undefined ||
      !nodePlateMediaVersionHasEmbedMetadataXss(dependency.version)
    ) {
      continue;
    }
    const imports = importedJavascriptSymbols(file.lines);
    const components = nodePlateExportedComponents(file);
    const structural = javascriptStructuralLines(file.lines);
    const plateBindings = imports.filter(
      (binding) =>
        binding.moduleSpecifier === "platejs/react" &&
        binding.imported === "Plate",
    );
    for (const componentImport of imports) {
      const importedPath = resolveRelativeModelImport(
        file.path,
        componentImport.moduleSpecifier,
        knownPaths,
      );
      const sink = sinks.find(
        (candidate) =>
          candidate.file.path === importedPath &&
          candidate.component.symbol === componentImport.imported &&
          candidate.dependency.manifestPath === dependency.manifestPath &&
          candidate.dependency.version === dependency.version &&
          candidate.dependency.proof === dependency.proof,
      );
      if (sink === undefined) continue;
      for (const plugin of nodePlateMediaReactBindings(
        file.lines,
        "MediaEmbedPlugin",
      )) {
        const pluginPattern = nodePlateMediaBindingPattern(plugin);
        for (
          let pluginIndex = plugin.line;
          pluginIndex < structural.length;
          pluginIndex += 1
        ) {
          if (
            !nodePlateMediaBindingUsable(file.lines, plugin, pluginIndex + 1)
          ) {
            continue;
          }
          const declaration = structural
            .slice(pluginIndex, Math.min(structural.length, pluginIndex + 13))
            .join("\n");
          const pluginConfiguration = new RegExp(
            `^\\s*(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*\\[[\\s\\S]*?${pluginPattern}\\s*\\.\\s*withComponent\\s*\\(\\s*${escapeRegularExpression(componentImport.local)}\\s*\\)[\\s\\S]*?\\]`,
            "u",
          ).exec(declaration);
          if (pluginConfiguration?.[1] === undefined) continue;
          const pluginVariable = pluginConfiguration[1];
          for (const plate of plateBindings) {
            for (
              let plateIndex = pluginIndex;
              plateIndex < structural.length;
              plateIndex += 1
            ) {
              if (!/<[A-Za-z_$][\w$]*\b/u.test(structural[plateIndex] ?? "")) {
                continue;
              }
              if (
                javascriptIdentifierReassignedBetween(
                  file.lines,
                  plate.local,
                  plate.line,
                  plateIndex + 1,
                ) ||
                javascriptIdentifierReassignedBetween(
                  file.lines,
                  pluginVariable,
                  pluginIndex + 1,
                  plateIndex + 1,
                )
              ) {
                continue;
              }
              const tag = structural
                .slice(plateIndex, Math.min(structural.length, plateIndex + 13))
                .join(" ");
              const plateTag = new RegExp(
                `<${escapeRegularExpression(plate.local)}\\b[^>]*>`,
                "u",
              ).exec(tag)?.[0];
              if (
                plateTag === undefined ||
                !new RegExp(
                  `\\bplugins\\s*=\\s*\\{\\s*${escapeRegularExpression(pluginVariable)}\\s*\\}`,
                  "u",
                ).test(plateTag)
              ) {
                continue;
              }
              const value = /\b(?:value|initialValue)\s*=\s*\{([^}]+)\}/u.exec(
                plateTag,
              )?.[1];
              if (value === undefined) continue;
              const component = components.find(
                (candidate) =>
                  plateIndex + 1 >= candidate.startLine &&
                  plateIndex + 1 <= candidate.endLine,
              );
              if (component === undefined) continue;
              const propName = nodePlateMediaComponentProp(component, value);
              if (propName === undefined) continue;
              renderers.push({
                component,
                componentImportLine: componentImport.line,
                dependency,
                file,
                mediaComponentSymbol: componentImport.local,
                plateLine: plateIndex + 1,
                pluginLine: pluginIndex + 1,
                pluginSymbol: pluginVariable,
                propName,
                sink,
              });
            }
          }
        }
      }
    }
  }
  return renderers.filter(
    (renderer, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.file.path === renderer.file.path &&
          candidate.plateLine === renderer.plateLine &&
          candidate.sink.file.path === renderer.sink.file.path,
      ) === index,
  );
}

function nodePlateMediaRemoteDocuments(
  file: SourceFileSnapshot,
): Array<{ line: number; symbol: string }> {
  const documents: Array<{ line: number; symbol: string }> = [];
  const responses = new Map<string, number>();
  const structural = javascriptStructuralLines(file.lines);
  for (let index = 0; index < structural.length; index += 1) {
    const line = structural[index] ?? "";
    const response =
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*await\s+fetch\s*\(/u.exec(
        line,
      );
    if (response?.[1] !== undefined) responses.set(response[1], index + 1);
    const direct =
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*await\s*\(\s*await\s+fetch\s*\([^)]*\)\s*\)\s*\.\s*json\s*\(/u.exec(
        line,
      );
    if (direct?.[1] !== undefined) {
      documents.push({ line: index + 1, symbol: direct[1] });
    }
    const parsed =
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*await\s+([A-Za-z_$][\w$]*)\s*\.\s*json\s*\(/u.exec(
        line,
      );
    if (
      parsed?.[1] !== undefined &&
      parsed[2] !== undefined &&
      responses.has(parsed[2]) &&
      !javascriptIdentifierReassignedBetween(
        file.lines,
        parsed[2],
        responses.get(parsed[2])!,
        index + 2,
      )
    ) {
      documents.push({ line: index + 1, symbol: parsed[1] });
    }
    const requestBody =
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*[A-Za-z_$][\w$]*\s*\.\s*body\b/u.exec(
        line,
      );
    if (requestBody?.[1] !== undefined) {
      documents.push({ line: index + 1, symbol: requestBody[1] });
    }
  }
  return documents;
}

function nodePlateMediaSources(
  files: readonly SourceFileSnapshot[],
  renderers: readonly NodePlateMediaRenderer[],
): NodePlateMediaSource[] {
  const sources: NodePlateMediaSource[] = [];
  const knownPaths = new Map(
    files.map((file) => [modelPathComparisonKey(file.path), file.path]),
  );
  for (const file of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path)
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(
      files,
      file.path,
      "@platejs/media",
    );
    if (dependency === undefined) continue;
    const structural = javascriptStructuralLines(file.lines);
    for (const imported of importedJavascriptSymbols(file.lines)) {
      const importedPath = resolveRelativeModelImport(
        file.path,
        imported.moduleSpecifier,
        knownPaths,
      );
      const renderer = renderers.find(
        (candidate) =>
          candidate.file.path === importedPath &&
          candidate.component.symbol === imported.imported &&
          candidate.dependency.manifestPath === dependency.manifestPath &&
          candidate.dependency.version === dependency.version &&
          candidate.dependency.proof === dependency.proof,
      );
      if (renderer === undefined) continue;
      for (const document of nodePlateMediaRemoteDocuments(file)) {
        for (
          let useIndex = document.line;
          useIndex < structural.length;
          useIndex += 1
        ) {
          if (
            !new RegExp(
              `<${escapeRegularExpression(imported.local)}\\b`,
              "u",
            ).test(structural[useIndex] ?? "")
          ) {
            continue;
          }
          if (
            javascriptIdentifierReassignedBetween(
              file.lines,
              document.symbol,
              document.line,
              useIndex + 1,
            ) ||
            javascriptIdentifierReassignedBetween(
              file.lines,
              imported.local,
              imported.line,
              useIndex + 1,
            )
          ) {
            continue;
          }
          const tag = structural
            .slice(useIndex, Math.min(structural.length, useIndex + 8))
            .join(" ");
          if (
            !new RegExp(
              `<${escapeRegularExpression(imported.local)}\\b[^>]*\\b${escapeRegularExpression(renderer.propName)}\\s*=\\s*\\{\\s*${escapeRegularExpression(document.symbol)}\\s*\\}`,
              "u",
            ).test(tag)
          ) {
            continue;
          }
          sources.push({
            file,
            line: document.line,
            renderer,
            rendererImportLine: imported.line,
            rendererUseLine: useIndex + 1,
            symbol: document.symbol,
          });
        }
      }
    }
  }
  return sources;
}

function nodePlateMediaEmbedXssRecords(
  files: readonly SourceFileSnapshot[],
): ResidualRiskRecord[] {
  const sinks = nodePlateMediaIframeSinks(files);
  const renderers = nodePlateMediaRenderers(files, sinks);
  const records: ResidualRiskRecord[] = [];
  const emitted = new Set<string>();
  for (const source of nodePlateMediaSources(files, renderers)) {
    const { renderer } = source;
    const { sink, dependency } = renderer;
    const key = `${source.file.path}\0${source.line}\0${sink.file.path}\0${sink.iframeLine}`;
    if (emitted.has(key)) continue;
    emitted.add(key);
    const prefix = dependency.proof === "npm-lockfile" ? "lock-resolved-" : "";
    const sinkKind = `${prefix}vulnerable-plate-media-embed-iframe-url`;
    const startLine = Math.max(1, sink.iframeLine - CONTEXT_LINES_BEFORE);
    const endLine = Math.min(
      sink.file.lines.length,
      sink.iframeLine + CONTEXT_LINES_AFTER,
    );
    const sourceStart = Math.max(1, source.line - CONTEXT_LINES_BEFORE);
    const sourceEnd = Math.min(
      source.file.lines.length,
      source.rendererUseLine + CONTEXT_LINES_AFTER,
    );
    records.push({
      path: sink.file.path,
      line: sink.iframeLine,
      categories: [
        "framework-dataflow:node-plate-media-embed-metadata-xss",
        "modeled-source:remote-serialized-plate-document",
        `modeled-sink:${sinkKind}`,
        "broken-control:trusted-serialized-media-provider-metadata",
      ],
      priority: 127,
      startLine,
      endLine,
      excerpt: sourceExcerpt(sink.file.lines, startLine, endLine),
      sourceExcerpt: sourceExcerpt(source.file.lines, sourceStart, sourceEnd),
      frameworkModel: {
        schemaVersion: "1.2",
        id: "node-plate-media-embed-metadata-xss",
        language: "javascript-typescript",
        scope: "cross-file-multi-hop-wrapper",
        source: {
          kind: "remote-serialized-plate-document",
          path: source.file.path,
          line: source.line,
        },
        sink: {
          kind: sinkKind,
          path: sink.file.path,
          line: sink.iframeLine,
          cweIds: ["CWE-79"],
        },
        propagators: [
          {
            kind: "plate-document-component-prop",
            path: source.file.path,
            line: source.rendererUseLine,
            symbol: `${source.symbol}->${renderer.component.symbol}.${renderer.propName}`,
          },
          {
            kind: "plate-editor-value",
            path: renderer.file.path,
            line: renderer.plateLine,
            symbol: renderer.propName,
          },
          {
            kind: "plate-media-embed-plugin-component",
            path: renderer.file.path,
            line: renderer.pluginLine,
            symbol: `${renderer.pluginSymbol}:${renderer.mediaComponentSymbol}`,
          },
          {
            kind: "plate-media-state-url-parsers",
            path: sink.file.path,
            line: sink.hookLine,
            symbol: sink.parserSymbol,
          },
          {
            kind: "plate-media-iframe-render",
            path: sink.file.path,
            line: sink.iframeLine,
            symbol: "iframe:embed.url",
          },
          {
            kind: "plate-media-runtime-dependency",
            path: dependency.manifestPath,
            line: dependency.line,
            symbol: `@platejs/media@${dependency.version}:${dependency.proof}:serialized-provider-url-fast-path`,
          },
        ],
        candidateControls: [],
      },
    });
    if (records.length >= MAX_FRAMEWORK_MULTI_HOP_RECORDS) return records;
  }
  return records;
}

interface NodeDefuddleBinding {
  line: number;
  local: string;
  member?: "Defuddle";
}

interface NodeDefuddleParserWrapper {
  bindingLine: number;
  callLine: number;
  dependency: NodeRuntimeDependency;
  file: SourceFileSnapshot;
  function: ExportedJavascriptFunction;
  htmlParameterIndex: number;
  returnLine: number;
}

interface NodeDefuddleRemoteHtmlSource {
  kind: string;
  line: number;
  symbol: string;
}

interface NodeDefuddleHtmlSink {
  kind: string;
  line: number;
}

function nodeDefuddleVersionHasExtractorXss(version: string): boolean {
  const match = /^(\d+)\.(\d+)\.(\d+)$/u.exec(version);
  if (match === null) return false;
  const [major, minor, patch] = match.slice(1).map(Number);
  return (
    major === 0 &&
    minor !== undefined &&
    patch !== undefined &&
    (minor < 19 || (minor === 19 && patch === 0))
  );
}

function nodeDefuddleBindingPattern(binding: NodeDefuddleBinding): string {
  const local = escapeRegularExpression(binding.local);
  return binding.member === undefined ? local : `${local}\\s*\\.\\s*Defuddle`;
}

function nodeDefuddleBindings(lines: readonly string[]): NodeDefuddleBinding[] {
  const bindings: NodeDefuddleBinding[] = importedJavascriptSymbols(lines)
    .filter(
      (binding) =>
        binding.moduleSpecifier === "defuddle/node" &&
        binding.imported === "Defuddle",
    )
    .map((binding) => ({ line: binding.line, local: binding.local }));
  for (let index = 0; index < lines.length; index += 1) {
    const code = javascriptCodeBeforeComment(lines[index] ?? "");
    const receiver =
      /^\s*import\s+\*\s+as\s+([A-Za-z_$][\w$]*)\s+from\s+["']defuddle\/node["']/u.exec(
        code,
      ) ??
      /^\s*import\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["']defuddle\/node["']\s*\)/u.exec(
        code,
      ) ??
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["']defuddle\/node["']\s*\)\s*;?\s*$/u.exec(
        code,
      );
    if (receiver?.[1] !== undefined) {
      bindings.push({
        line: index + 1,
        local: receiver[1],
        member: "Defuddle",
      });
    }
    const direct =
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["']defuddle\/node["']\s*\)\s*\.\s*Defuddle\s*;?\s*$/u.exec(
        code,
      );
    if (direct?.[1] !== undefined) {
      bindings.push({ line: index + 1, local: direct[1] });
    }
  }
  return bindings.filter(
    (binding, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.line === binding.line &&
          candidate.local === binding.local &&
          candidate.member === binding.member,
      ) === index,
  );
}

function nodeDefuddleBindingUsable(
  lines: readonly string[],
  binding: NodeDefuddleBinding,
  useLine: number,
): boolean {
  if (
    binding.line >= useLine ||
    javascriptIdentifierReassignedBetween(
      lines,
      binding.local,
      binding.line,
      useLine + 1,
    )
  ) {
    return false;
  }
  const wrapper = exportedJavascriptFunctions(lines).find(
    (candidate) =>
      useLine >= candidate.startLine && useLine <= candidate.endLine,
  );
  if (wrapper?.parameters.includes(binding.local) === true) return false;
  if (binding.member === undefined) return true;
  const local = escapeRegularExpression(binding.local);
  return !javascriptStructuralLines(lines)
    .slice(binding.line, Math.max(binding.line, useLine - 1))
    .some((line) =>
      new RegExp(
        `\\b${local}\\s*\\.\\s*Defuddle\\s*(?:[+\\-*/%&|^?]?=(?!=|>)|\\+\\+|--)`,
        "u",
      ).test(line),
    );
}

function nodeDefuddleParserWrappers(
  files: readonly SourceFileSnapshot[],
): NodeDefuddleParserWrapper[] {
  const wrappers: NodeDefuddleParserWrapper[] = [];
  for (const file of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path) ||
      !file.text.includes("defuddle/node")
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(files, file.path, "defuddle");
    if (
      dependency === undefined ||
      !nodeDefuddleVersionHasExtractorXss(dependency.version)
    ) {
      continue;
    }
    const structural = javascriptStructuralLines(file.lines);
    const functions = exportedJavascriptFunctions(file.lines);
    for (const binding of nodeDefuddleBindings(file.lines)) {
      const bindingPattern = nodeDefuddleBindingPattern(binding);
      for (let index = binding.line; index < structural.length; index += 1) {
        const line = index + 1;
        const wrapper = functions.find(
          (candidate) =>
            line >= candidate.startLine && line <= candidate.endLine,
        );
        if (
          wrapper === undefined ||
          !nodeDefuddleBindingUsable(file.lines, binding, line)
        ) {
          continue;
        }
        const callPattern = new RegExp(`\\b${bindingPattern}\\s*\\(`, "u");
        if (!callPattern.test(structural[index] ?? "")) continue;
        const arguments_ = javascriptCallArgumentsAtLine(
          file.lines,
          line,
          callPattern,
        );
        const htmlArgument = arguments_?.[0]?.trim();
        if (htmlArgument === undefined) continue;
        const htmlParameterIndex = wrapper.parameters.indexOf(htmlArgument);
        if (htmlParameterIndex < 0) continue;
        const statement = structural
          .slice(index, Math.min(structural.length, index + 8))
          .join("\n");
        const directReturn = new RegExp(
          `^\\s*return\\s+(?:await\\s+)?${bindingPattern}\\s*\\(`,
          "u",
        ).test(statement);
        let returnLine = line;
        if (!directReturn) {
          const assignment = new RegExp(
            `^\\s*(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*(?:await\\s+)?${bindingPattern}\\s*\\(`,
            "u",
          ).exec(statement);
          const result = assignment?.[1];
          if (result === undefined) continue;
          const returnPattern = new RegExp(
            `^\\s*return\\s+${escapeRegularExpression(result)}\\s*;?\\s*$`,
            "u",
          );
          const foundReturn = structural.findIndex(
            (candidate, candidateIndex) =>
              candidateIndex >= index &&
              candidateIndex < wrapper.endLine &&
              returnPattern.test(candidate),
          );
          if (
            foundReturn < 0 ||
            javascriptIdentifierReassignedBetween(
              file.lines,
              result,
              line,
              foundReturn + 2,
            )
          ) {
            continue;
          }
          returnLine = foundReturn + 1;
        }
        wrappers.push({
          bindingLine: binding.line,
          callLine: line,
          dependency,
          file,
          function: wrapper,
          htmlParameterIndex,
          returnLine,
        });
      }
    }
  }
  return wrappers.filter(
    (wrapper, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.file.path === wrapper.file.path &&
          candidate.function.symbol === wrapper.function.symbol &&
          candidate.callLine === wrapper.callLine,
      ) === index,
  );
}

function nodeDefuddleRemoteHtml(
  lines: readonly string[],
  expression: string,
  line: number,
  routeParameters: readonly string[],
): NodeDefuddleRemoteHtmlSource | undefined {
  const resolved = resolveJavascriptExpression(lines, expression, line);
  if (resolved === undefined) return undefined;
  const value = resolved.value.replace(/\s+/gu, " ").trim();
  const requestBody =
    /^([A-Za-z_$][\w$]*)\s*\.\s*body(?:\s*\.\s*[A-Za-z_$][\w$]*|\s*\[[^\]]+\])?$/u.exec(
      value,
    );
  if (
    requestBody?.[1] !== undefined &&
    routeParameters.includes(requestBody[1])
  ) {
    return {
      kind: "remote-request-html-body",
      line: resolved.line,
      symbol: requestBody[0].replace(/\s+/gu, ""),
    };
  }
  const requestText =
    /^(?:await\s+)?([A-Za-z_$][\w$]*)\s*\.\s*text\s*\(\s*\)$/u.exec(value);
  if (
    requestText?.[1] !== undefined &&
    routeParameters.includes(requestText[1])
  ) {
    return {
      kind: "remote-request-html-text",
      line: resolved.line,
      symbol: requestText[0].replace(/\s+/gu, ""),
    };
  }
  if (
    /^await\s+\(\s*await\s+fetch\s*\([^)]*\)\s*\)\s*\.\s*text\s*\(\s*\)$/u.test(
      value,
    )
  ) {
    return {
      kind: "remote-fetched-html-text",
      line: resolved.line,
      symbol: "fetch(...).text()",
    };
  }
  const responseText =
    /^await\s+([A-Za-z_$][\w$]*)\s*\.\s*text\s*\(\s*\)$/u.exec(value);
  if (responseText?.[1] === undefined) return undefined;
  const response = responseText[1];
  const earliest = Math.max(0, resolved.line - 65);
  const responseDeclaration = new RegExp(
    `^\\s*(?:const|let|var)\\s+${escapeRegularExpression(response)}\\s*=\\s*await\\s+fetch\\s*\\(`,
    "u",
  );
  const responseLine = javascriptStructuralLines(lines)
    .slice(earliest, resolved.line - 1)
    .findLastIndex((candidate) => responseDeclaration.test(candidate));
  if (responseLine < 0) return undefined;
  const absoluteResponseLine = earliest + responseLine + 1;
  if (
    javascriptIdentifierReassignedBetween(
      lines,
      response,
      absoluteResponseLine,
      resolved.line + 1,
    )
  ) {
    return undefined;
  }
  return {
    kind: "remote-fetched-html-text",
    line: absoluteResponseLine,
    symbol: `${response}.text()`,
  };
}

function nodeDefuddleHtmlSink(
  lines: readonly string[],
  result: string,
  callLine: number,
  endLine: number,
): NodeDefuddleHtmlSink | undefined {
  const structural = javascriptStructuralLines(lines);
  const resultPattern = escapeRegularExpression(result);
  const contentPattern = `${resultPattern}\\s*\\?*\\.\\s*content`;
  for (
    let index = callLine;
    index < Math.min(structural.length, endLine);
    index += 1
  ) {
    if (
      javascriptIdentifierReassignedBetween(lines, result, callLine, index + 2)
    ) {
      return undefined;
    }
    const window = structural
      .slice(Math.max(callLine - 1, index - 4), Math.min(endLine, index + 8))
      .join(" ");
    const originalWindow = javascriptCodeLinesWithoutComments(
      lines.slice(
        Math.max(callLine - 1, index - 4),
        Math.min(endLine, index + 8),
      ),
    ).join(" ");
    const current = structural[index] ?? "";
    const declaresHtml =
      /\.\s*(?:type|contentType)\s*\(\s*["'](?:text\/)?html["']\s*\)/iu.test(
        originalWindow,
      ) ||
      /setHeader\s*\(\s*["']content-type["']\s*,\s*["']text\/html(?:;[^"']*)?["']\s*\)/iu.test(
        originalWindow,
      );
    const sendsContent = new RegExp(
      `\\.\\s*(?:send|end)\\s*\\(\\s*${contentPattern}\\s*\\)`,
      "u",
    ).test(window);
    const htmlResponse = declaresHtml && sendsContent;
    if (htmlResponse) {
      return { kind: "html-response-defuddle-content", line: index + 1 };
    }
    if (
      new RegExp(`\\.\\s*innerHTML\\s*=\\s*${contentPattern}\\b`, "u").test(
        current,
      )
    ) {
      return { kind: "dom-innerhtml-defuddle-content", line: index + 1 };
    }
    if (
      new RegExp(
        `dangerouslySetInnerHTML\\s*=\\s*\\{\\s*\\{\\s*__html\\s*:\\s*${contentPattern}\\s*[,}]`,
        "u",
      ).test(window)
    ) {
      return { kind: "react-raw-html-defuddle-content", line: index + 1 };
    }
    if (
      new RegExp(
        `new\\s+Response\\s*\\(\\s*${contentPattern}\\s*,[\\s\\S]{0,320}(?:content-type|Content-Type)["']?\\s*[:=,][\\s\\S]{0,80}text\\/html`,
        "iu",
      ).test(originalWindow)
    ) {
      return { kind: "web-response-defuddle-content", line: index + 1 };
    }
  }
  return undefined;
}

function nodeDefuddleExtractorXssRecords(
  files: readonly SourceFileSnapshot[],
): ResidualRiskRecord[] {
  const wrappers = nodeDefuddleParserWrappers(files);
  const records: ResidualRiskRecord[] = [];
  const emitted = new Set<string>();
  const knownPaths = new Map(
    files.map((file) => [modelPathComparisonKey(file.path), file.path]),
  );
  for (const file of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path)
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(files, file.path, "defuddle");
    if (
      dependency === undefined ||
      !nodeDefuddleVersionHasExtractorXss(dependency.version)
    ) {
      continue;
    }
    const structural = javascriptStructuralLines(file.lines);
    const functions = exportedJavascriptFunctions(file.lines);
    for (const imported of importedJavascriptSymbols(file.lines)) {
      const importedPath = resolveRelativeModelImport(
        file.path,
        imported.moduleSpecifier,
        knownPaths,
      );
      const wrapper = wrappers.find(
        (candidate) =>
          candidate.file.path === importedPath &&
          candidate.function.symbol === imported.imported &&
          candidate.dependency.manifestPath === dependency.manifestPath &&
          candidate.dependency.version === dependency.version &&
          candidate.dependency.proof === dependency.proof,
      );
      if (wrapper === undefined) continue;
      for (let index = imported.line; index < structural.length; index += 1) {
        const line = index + 1;
        const route = functions.find(
          (candidate) =>
            line >= candidate.startLine && line <= candidate.endLine,
        );
        if (
          route === undefined ||
          javascriptIdentifierReassignedBetween(
            file.lines,
            imported.local,
            imported.line,
            line + 1,
          )
        ) {
          continue;
        }
        const declaration = new RegExp(
          `^\\s*(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*(?:await\\s+)?${escapeRegularExpression(imported.local)}\\s*\\(`,
          "u",
        ).exec(
          structural
            .slice(index, Math.min(structural.length, index + 8))
            .join("\n"),
        );
        const result = declaration?.[1];
        if (result === undefined) continue;
        const arguments_ = javascriptCallArgumentsAtLine(
          file.lines,
          line,
          new RegExp(
            `\\b${escapeRegularExpression(imported.local)}\\s*\\(`,
            "u",
          ),
        );
        const htmlArgument = arguments_?.[wrapper.htmlParameterIndex];
        if (htmlArgument === undefined) continue;
        const source = nodeDefuddleRemoteHtml(
          file.lines,
          htmlArgument,
          line,
          route.parameters,
        );
        if (source === undefined) continue;
        const sink = nodeDefuddleHtmlSink(
          file.lines,
          result,
          line,
          route.endLine,
        );
        if (sink === undefined) continue;
        const key = `${file.path}\0${source.line}\0${wrapper.file.path}\0${wrapper.callLine}\0${sink.line}`;
        if (emitted.has(key)) continue;
        emitted.add(key);
        const prefix =
          dependency.proof === "npm-lockfile" ? "lock-resolved-" : "";
        const sinkKind = `${prefix}vulnerable-defuddle-extractor-html-render`;
        const startLine = Math.max(1, sink.line - CONTEXT_LINES_BEFORE);
        const endLine = Math.min(
          file.lines.length,
          sink.line + CONTEXT_LINES_AFTER,
        );
        const sourceStart = Math.max(1, source.line - CONTEXT_LINES_BEFORE);
        const sourceEnd = Math.min(
          file.lines.length,
          line + CONTEXT_LINES_AFTER,
        );
        records.push({
          path: file.path,
          line: sink.line,
          categories: [
            "framework-dataflow:node-defuddle-extractor-html-xss",
            `modeled-source:${source.kind}`,
            `modeled-sink:${sinkKind}`,
            "broken-control:unsanitized-site-extractor-html-output",
          ],
          priority: 127,
          startLine,
          endLine,
          excerpt: sourceExcerpt(file.lines, startLine, endLine),
          sourceExcerpt: sourceExcerpt(file.lines, sourceStart, sourceEnd),
          frameworkModel: {
            schemaVersion: "1.2",
            id: "node-defuddle-extractor-html-xss",
            language: "javascript-typescript",
            scope: "cross-file-multi-hop-wrapper",
            source: {
              kind: source.kind,
              path: file.path,
              line: source.line,
            },
            sink: {
              kind: sinkKind,
              path: file.path,
              line: sink.line,
              cweIds: ["CWE-79"],
            },
            propagators: [
              {
                kind: "relative-defuddle-parser-wrapper-call",
                path: file.path,
                line,
                symbol: `${imported.local}:${wrapper.function.symbol}`,
              },
              {
                kind: "defuddle-node-html-input",
                path: wrapper.file.path,
                line: wrapper.callLine,
                symbol: wrapper.function.parameters[wrapper.htmlParameterIndex],
              },
              {
                kind: "defuddle-site-extractor-response",
                path: wrapper.file.path,
                line: wrapper.returnLine,
                symbol: "DefuddleResponse.content",
              },
              {
                kind: sink.kind,
                path: file.path,
                line: sink.line,
                symbol: `${result}.content`,
              },
              {
                kind: "defuddle-runtime-dependency",
                path: dependency.manifestPath,
                line: dependency.line,
                symbol: `defuddle@${dependency.version}:${dependency.proof}:unsanitized-site-extractor-output`,
              },
            ],
            candidateControls: [],
          },
        });
        if (records.length >= MAX_FRAMEWORK_MULTI_HOP_RECORDS) return records;
      }
    }
  }
  return records;
}

interface NodePickemBinding {
  line: number;
  local: string;
  member?: "pickem";
}

interface NodePickemRemoteCollection {
  kind: string;
  line: number;
  symbol: string;
}

interface NodePickemProjection {
  field: "description" | "group" | "label";
  fieldLine: number;
  property: string;
  source: NodePickemRemoteCollection;
}

function nodePickemVersionHasTerminalInjection(version: string): boolean {
  const match = /^(\d+)\.(\d+)\.(\d+)$/u.exec(version);
  if (match === null) return false;
  const [major, minor, patch] = match.slice(1).map(Number);
  if (major === undefined || minor === undefined || patch === undefined)
    return false;
  return major === 0 || (major === 1 && minor === 0 && patch < 7);
}

function nodePickemBindingPattern(binding: NodePickemBinding): string {
  const local = escapeRegularExpression(binding.local);
  return binding.member === undefined ? local : `${local}\\s*\\.\\s*pickem`;
}

function nodePickemBindings(lines: readonly string[]): NodePickemBinding[] {
  const bindings: NodePickemBinding[] = importedJavascriptSymbols(lines)
    .filter(
      (binding) =>
        binding.moduleSpecifier === "pickem" && binding.imported === "pickem",
    )
    .map((binding) => ({ line: binding.line, local: binding.local }));
  for (let index = 0; index < lines.length; index += 1) {
    const code = javascriptCodeBeforeComment(lines[index] ?? "");
    const receiver =
      /^\s*import\s+\*\s+as\s+([A-Za-z_$][\w$]*)\s+from\s+["']pickem["']/u.exec(
        code,
      ) ??
      /^\s*import\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["']pickem["']\s*\)/u.exec(
        code,
      ) ??
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["']pickem["']\s*\)\s*;?\s*$/u.exec(
        code,
      );
    if (receiver?.[1] !== undefined) {
      bindings.push({
        line: index + 1,
        local: receiver[1],
        member: "pickem",
      });
    }
    const direct =
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["']pickem["']\s*\)\s*\.\s*pickem\s*;?\s*$/u.exec(
        code,
      );
    if (direct?.[1] !== undefined) {
      bindings.push({ line: index + 1, local: direct[1] });
    }
  }
  return bindings.filter(
    (binding, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.line === binding.line &&
          candidate.local === binding.local &&
          candidate.member === binding.member,
      ) === index,
  );
}

function nodePickemBindingUsable(
  lines: readonly string[],
  binding: NodePickemBinding,
  useLine: number,
  route: ExportedJavascriptFunction | undefined,
): boolean {
  if (
    binding.line >= useLine ||
    route?.parameters.includes(binding.local) === true ||
    javascriptIdentifierReassignedBetween(
      lines,
      binding.local,
      binding.line,
      useLine + 1,
    )
  ) {
    return false;
  }
  const access = nodePickemBindingPattern(binding);
  return !javascriptStructuralLines(lines)
    .slice(binding.line, Math.max(binding.line, useLine - 1))
    .some((line) =>
      new RegExp(
        `\\b${access}(?:\\s*\\.\\s*checkbox)?\\s*(?:[+\\-*/%&|^?]?=(?!=|>)|\\+\\+|--)`,
        "u",
      ).test(line),
    );
}

function nodePickemRemoteCollection(
  lines: readonly string[],
  expression: string,
  line: number,
  routeParameters: readonly string[],
): NodePickemRemoteCollection | undefined {
  const resolved = resolveJavascriptExpression(lines, expression, line);
  if (resolved === undefined) return undefined;
  const value = resolved.value.replace(/\s+/gu, " ").trim();
  const requestBody =
    /^([A-Za-z_$][\w$]*)\s*\.\s*body(?:\s*\.\s*[A-Za-z_$][\w$]*|\s*\[[^\]]+\])+$/u.exec(
      value,
    );
  if (
    requestBody?.[1] !== undefined &&
    routeParameters.includes(requestBody[1])
  ) {
    return {
      kind: "remote-request-item-collection",
      line: resolved.line,
      symbol: requestBody[0].replace(/\s+/gu, ""),
    };
  }
  if (
    /^await\s+\(\s*await\s+fetch\s*\([^)]*\)\s*\)\s*\.\s*json\s*\(\s*\)$/u.test(
      value,
    )
  ) {
    return {
      kind: "remote-fetched-json-item-collection",
      line: resolved.line,
      symbol: "fetch(...).json()",
    };
  }
  const responseJson =
    /^await\s+([A-Za-z_$][\w$]*)\s*\.\s*json\s*\(\s*\)$/u.exec(value);
  if (responseJson?.[1] === undefined) return undefined;
  const response = responseJson[1];
  const earliest = Math.max(0, resolved.line - 65);
  const declaration = new RegExp(
    `^\\s*(?:const|let|var)\\s+${escapeRegularExpression(response)}\\s*=\\s*await\\s+fetch\\s*\\(`,
    "u",
  );
  const relativeLine = javascriptStructuralLines(lines)
    .slice(earliest, resolved.line - 1)
    .findLastIndex((candidate) => declaration.test(candidate));
  if (relativeLine < 0) return undefined;
  const responseLine = earliest + relativeLine + 1;
  if (
    javascriptIdentifierReassignedBetween(
      lines,
      response,
      responseLine,
      resolved.line + 1,
    )
  ) {
    return undefined;
  }
  return {
    kind: "remote-fetched-json-item-collection",
    line: responseLine,
    symbol: `${response}.json()`,
  };
}

function nodePickemProjectedProperty(
  expression: string,
  element: string,
): string | undefined {
  let value = expression.trim();
  while (value.startsWith("(") && value.endsWith(")")) {
    const close = matchingCallParenthesis(value, 0);
    if (close !== value.length - 1) break;
    value = value.slice(1, -1).trim();
  }
  const elementPattern = escapeRegularExpression(element);
  const direct = new RegExp(
    `^${elementPattern}\\s*(?:\\.\\s*([A-Za-z_$][\\w$]*)|\\[\\s*["']([^"']+)["']\\s*\\])$`,
    "u",
  ).exec(value);
  if (direct !== null) return direct[1] ?? direct[2];
  const stringWrapper = new RegExp(
    `^String\\s*\\(\\s*${elementPattern}\\s*(?:\\.\\s*([A-Za-z_$][\\w$]*)|\\[\\s*["']([^"']+)["']\\s*\\])\\s*\\)$`,
    "u",
  ).exec(value);
  if (stringWrapper !== null) return stringWrapper[1] ?? stringWrapper[2];
  if (value.startsWith("`") && value.endsWith("`")) {
    const interpolation = new RegExp(
      `\\$\\{\\s*${elementPattern}\\s*(?:\\.\\s*([A-Za-z_$][\\w$]*)|\\[\\s*["']([^"']+)["']\\s*\\])\\s*\\}`,
      "u",
    ).exec(value);
    if (interpolation !== null) return interpolation[1] ?? interpolation[2];
  }
  return undefined;
}

function nodePickemProjection(
  lines: readonly string[],
  expression: string,
  line: number,
  routeParameters: readonly string[],
): NodePickemProjection | undefined {
  const resolved = resolveJavascriptExpression(lines, expression, line);
  if (resolved === undefined) return undefined;
  const map =
    /^\s*([A-Za-z_$][\w$]*(?:\s*\.\s*[A-Za-z_$][\w$]*|\s*\[[^\]]+\])*)\s*\.\s*map\s*\(/u.exec(
      resolved.value,
    );
  if (map?.[1] === undefined) return undefined;
  const open = resolved.value.indexOf("(", map.index + map[0].length - 1);
  const close = matchingCallParenthesis(resolved.value, open);
  if (
    open < 0 ||
    close < 0 ||
    resolved.value
      .slice(close + 1)
      .trim()
      .replace(/;$/u, "") !== ""
  ) {
    return undefined;
  }
  const callbacks = splitJavascriptArguments(
    resolved.value.slice(open + 1, close),
  );
  if (callbacks.length !== 1) return undefined;
  const callback =
    /^\s*(?:\(\s*)?([A-Za-z_$][\w$]*)(?:\s*,\s*[A-Za-z_$][\w$]*)?\s*\)?\s*=>\s*([\s\S]+)$/u.exec(
      callbacks[0] ?? "",
    );
  if (callback?.[1] === undefined || callback[2] === undefined)
    return undefined;
  const element = callback[1];
  let returned = callback[2].trim();
  while (returned.startsWith("(") && returned.endsWith(")")) {
    const end = matchingCallParenthesis(returned, 0);
    if (end !== returned.length - 1) break;
    returned = returned.slice(1, -1).trim();
  }
  if (returned.startsWith("{")) {
    const explicitReturn =
      /^\{[\s\S]*?\breturn\s+(\{[\s\S]*\})\s*;?[\s\S]*\}$/u.exec(returned);
    if (explicitReturn?.[1] !== undefined) returned = explicitReturn[1];
  }
  const objectOffset = resolved.value.indexOf(returned, open + 1);
  const objectLine =
    resolved.line +
    (objectOffset < 0
      ? 0
      : resolved.value.slice(0, objectOffset).match(/\n/gu)?.length ?? 0);
  const entries = javascriptObjectEntries({
    line: objectLine,
    value: returned,
  });
  const source = nodePickemRemoteCollection(
    lines,
    map[1],
    resolved.line,
    routeParameters,
  );
  if (source === undefined) return undefined;
  for (const field of ["label", "description", "group"] as const) {
    const entry = entries.find((candidate) => candidate.key === field);
    if (entry === undefined) continue;
    const property = nodePickemProjectedProperty(entry.value, element);
    if (property !== undefined) {
      return { field, fieldLine: entry.line, property, source };
    }
  }
  return undefined;
}

function nodePickemTerminalInjectionRecords(
  files: readonly SourceFileSnapshot[],
): ResidualRiskRecord[] {
  const records: ResidualRiskRecord[] = [];
  const emitted = new Set<string>();
  for (const file of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path) ||
      !file.text.includes("pickem")
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(files, file.path, "pickem");
    if (
      dependency === undefined ||
      !nodePickemVersionHasTerminalInjection(dependency.version)
    ) {
      continue;
    }
    const structural = javascriptStructuralLines(file.lines);
    const functions = exportedJavascriptFunctions(file.lines);
    for (const binding of nodePickemBindings(file.lines)) {
      const bindingPattern = nodePickemBindingPattern(binding);
      const callPattern = new RegExp(
        `\\b${bindingPattern}(?:\\s*\\.\\s*checkbox)?\\s*\\(`,
        "u",
      );
      for (let index = binding.line; index < structural.length; index += 1) {
        const line = index + 1;
        if (!callPattern.test(structural[index] ?? "")) continue;
        const route = functions.find(
          (candidate) =>
            line >= candidate.startLine && line <= candidate.endLine,
        );
        if (!nodePickemBindingUsable(file.lines, binding, line, route))
          continue;
        const arguments_ = javascriptCallArgumentsAtLine(
          file.lines,
          line,
          callPattern,
        );
        if (arguments_ === undefined) continue;
        const items = arguments_[0];
        if (items === undefined) continue;
        const options = arguments_[1];
        if (options !== undefined) {
          const resolvedOptions = resolveJavascriptExpression(
            file.lines,
            options,
            line,
          );
          if (
            resolvedOptions !== undefined &&
            javascriptObjectPropertyValue(resolvedOptions.value, "format") !==
              undefined
          ) {
            continue;
          }
        }
        const projection = nodePickemProjection(
          file.lines,
          items,
          line,
          route?.parameters ?? [],
        );
        if (projection === undefined) continue;
        const key = `${file.path}\0${projection.source.line}\0${projection.fieldLine}\0${line}`;
        if (emitted.has(key)) continue;
        emitted.add(key);
        const prefix =
          dependency.proof === "npm-lockfile" ? "lock-resolved-" : "";
        const sinkKind = `${prefix}vulnerable-pickem-terminal-item-render`;
        const startLine = Math.max(1, line - CONTEXT_LINES_BEFORE);
        const endLine = Math.min(file.lines.length, line + CONTEXT_LINES_AFTER);
        const sourceStart = Math.max(
          1,
          projection.source.line - CONTEXT_LINES_BEFORE,
        );
        records.push({
          path: file.path,
          line,
          categories: [
            "framework-dataflow:node-pickem-terminal-control-injection",
            `modeled-source:${projection.source.kind}`,
            `modeled-sink:${sinkKind}`,
            "broken-control:unsanitized-terminal-item-text",
          ],
          priority: 123,
          startLine,
          endLine,
          excerpt: sourceExcerpt(file.lines, startLine, endLine),
          sourceExcerpt: sourceExcerpt(
            file.lines,
            sourceStart,
            Math.min(file.lines.length, line + CONTEXT_LINES_AFTER),
          ),
          frameworkModel: {
            schemaVersion: "1.2",
            id: "node-pickem-terminal-control-injection",
            language: "javascript-typescript",
            scope: "same-file",
            source: {
              kind: projection.source.kind,
              path: file.path,
              line: projection.source.line,
            },
            sink: {
              kind: sinkKind,
              path: file.path,
              line,
              cweIds: ["CWE-150"],
            },
            propagators: [
              {
                kind: "remote-pickem-item-collection",
                path: file.path,
                line: projection.source.line,
                symbol: projection.source.symbol,
              },
              {
                kind: "pickem-display-field-projection",
                path: file.path,
                line: projection.fieldLine,
                symbol: `${projection.field}:${projection.property}`,
              },
              {
                kind: "official-pickem-binding",
                path: file.path,
                line: binding.line,
                symbol: binding.local,
              },
              {
                kind: "pickem-terminal-render",
                path: file.path,
                line,
                symbol: (structural[index] ?? "").includes(".checkbox")
                  ? "pickem.checkbox"
                  : "pickem",
              },
              {
                kind: "pickem-runtime-dependency",
                path: dependency.manifestPath,
                line: dependency.line,
                symbol: `pickem@${dependency.version}:${dependency.proof}:unsanitized-terminal-display`,
              },
            ],
            candidateControls: [],
          },
        });
        if (records.length >= MAX_FRAMEWORK_MULTI_HOP_RECORDS) return records;
      }
    }
  }
  return records;
}

type NodeLogtapeFunction = "configure" | "getLogger" | "getSyslogSink";

interface NodeLogtapeBinding {
  function: NodeLogtapeFunction;
  line: number;
  local: string;
  receiver: boolean;
}

interface NodeLogtapeStructuredSink {
  binding: NodeLogtapeBinding;
  line: number;
  variable?: string;
}

interface NodeLogtapeTopology {
  configureBinding: NodeLogtapeBinding;
  configureLine: number;
  configuredCategory: readonly string[];
  sink: NodeLogtapeStructuredSink;
  sinkName: string;
}

interface NodeLogtapeLogger {
  binding: NodeLogtapeBinding;
  category: readonly string[];
  line: number;
  local: string;
  topology: NodeLogtapeTopology;
}

interface NodeLogtapeRemoteProperty {
  boundary: "structured-data-key" | "structured-data-value";
  kind: string;
  line: number;
  symbol: string;
}

function nodeLogtapeVersionHasSyslogInjection(version: string): boolean {
  const match = /^(\d+)\.(\d+)\.(\d+)$/u.exec(version);
  if (match === null) return false;
  const [major, minor, patch] = match.slice(1).map(Number);
  if (major === undefined || minor === undefined || patch === undefined) {
    return false;
  }
  return (
    major < 1 ||
    (major === 1 && (minor < 3 || (minor === 3 && patch < 11))) ||
    (major === 2 && minor === 0 && patch < 14) ||
    (major === 2 && minor === 1 && patch < 5)
  );
}

function nodeLogtapeBindingPattern(binding: NodeLogtapeBinding): string {
  const local = escapeRegularExpression(binding.local);
  return binding.receiver ? `${local}\\s*\\.\\s*${binding.function}` : local;
}

function nodeLogtapeBindings(
  lines: readonly string[],
  moduleSpecifier: "@logtape/logtape" | "@logtape/syslog",
  functionName: NodeLogtapeFunction,
): NodeLogtapeBinding[] {
  const bindings: NodeLogtapeBinding[] = importedJavascriptSymbols(lines)
    .filter(
      (binding) =>
        binding.moduleSpecifier === moduleSpecifier &&
        binding.imported === functionName,
    )
    .map((binding) => ({
      function: functionName,
      line: binding.line,
      local: binding.local,
      receiver: false,
    }));
  const escapedModule = escapeRegularExpression(moduleSpecifier);
  const escapedFunction = escapeRegularExpression(functionName);
  for (let index = 0; index < lines.length; index += 1) {
    const code = javascriptCodeBeforeComment(lines[index] ?? "");
    const receiver =
      new RegExp(
        `^\\s*import\\s+\\*\\s+as\\s+([A-Za-z_$][\\w$]*)\\s+from\\s+["']${escapedModule}["']`,
        "u",
      ).exec(code) ??
      new RegExp(
        `^\\s*import\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*require\\s*\\(\\s*["']${escapedModule}["']\\s*\\)`,
        "u",
      ).exec(code) ??
      new RegExp(
        `^\\s*(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*require\\s*\\(\\s*["']${escapedModule}["']\\s*\\)\\s*;?\\s*$`,
        "u",
      ).exec(code);
    if (receiver?.[1] !== undefined) {
      bindings.push({
        function: functionName,
        line: index + 1,
        local: receiver[1],
        receiver: true,
      });
    }
    const direct = new RegExp(
      `^\\s*(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*require\\s*\\(\\s*["']${escapedModule}["']\\s*\\)\\s*\\.\\s*${escapedFunction}\\s*;?\\s*$`,
      "u",
    ).exec(code);
    if (direct?.[1] !== undefined) {
      bindings.push({
        function: functionName,
        line: index + 1,
        local: direct[1],
        receiver: false,
      });
    }
  }
  return bindings.filter(
    (binding, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.function === binding.function &&
          candidate.line === binding.line &&
          candidate.local === binding.local &&
          candidate.receiver === binding.receiver,
      ) === index,
  );
}

function nodeLogtapeBindingUsable(
  lines: readonly string[],
  binding: NodeLogtapeBinding,
  useLine: number,
  route?: ExportedJavascriptFunction,
): boolean {
  if (
    binding.line >= useLine ||
    route?.parameters.includes(binding.local) === true ||
    javascriptIdentifierReassignedBetween(
      lines,
      binding.local,
      binding.line,
      useLine + 1,
    )
  ) {
    return false;
  }
  if (!binding.receiver) return true;
  const access = nodeLogtapeBindingPattern(binding);
  return !javascriptStructuralLines(lines)
    .slice(binding.line, Math.max(binding.line, useLine - 1))
    .some((line) =>
      new RegExp(
        `\\b${access}\\s*(?:[+\\-*/%&|^?]?=(?!=|>)|\\+\\+|--)`,
        "u",
      ).test(line),
    );
}

function nodeLogtapeLiteralStrings(
  expression: JavascriptResolvedExpression,
): string[] | undefined {
  const array = javascriptCompositePrefix(expression.value, "[", "]");
  if (
    array === undefined ||
    expression.value
      .slice(expression.value.indexOf(array) + array.length)
      .trim() !== ""
  ) {
    return undefined;
  }
  const entries = javascriptDelimitedEntries(array.slice(1, -1));
  const values: string[] = [];
  for (const entry of entries) {
    const literal = /^\s*["']([^"']*)["']\s*$/u.exec(entry.value);
    if (literal?.[1] === undefined) return undefined;
    values.push(literal[1]);
  }
  return values;
}

function nodeLogtapeCategory(
  lines: readonly string[],
  expression: string | undefined,
  line: number,
): readonly string[] | undefined {
  if (expression === undefined || expression.trim() === "") return [];
  const resolved = resolveJavascriptExpression(lines, expression, line);
  if (resolved === undefined) return undefined;
  const literal = /^\s*["']([^"']+)["']\s*$/u.exec(resolved.value);
  if (literal?.[1] !== undefined) return [literal[1]];
  return nodeLogtapeLiteralStrings(resolved);
}

function nodeLogtapeCallArgumentsAtLine(
  lines: readonly string[],
  line: number,
  callee: RegExp,
): string[] | undefined {
  const callLines = lines.slice(line - 1, Math.min(lines.length, line + 63));
  const original = javascriptCodeLinesWithoutComments(callLines).join("\n");
  const structural = javascriptStructuralLines(callLines).join("\n");
  const match = callee.exec(structural.split("\n", 1)[0] ?? "");
  if (match === null) return undefined;
  const open = structural.indexOf("(", match.index);
  const close = matchingCallParenthesis(structural, open);
  if (open < 0 || close < 0) return undefined;
  return splitJavascriptArguments(original.slice(open + 1, close));
}

function nodeLogtapeStructuredSinks(
  lines: readonly string[],
  bindings: readonly NodeLogtapeBinding[],
): NodeLogtapeStructuredSink[] {
  const structural = javascriptStructuralLines(lines);
  const sinks: NodeLogtapeStructuredSink[] = [];
  for (const binding of bindings) {
    const access = nodeLogtapeBindingPattern(binding);
    const callPattern = new RegExp(`\\b${access}\\s*\\(`, "u");
    for (let index = binding.line; index < structural.length; index += 1) {
      const line = index + 1;
      const statement = structural[index] ?? "";
      if (!callPattern.test(statement)) continue;
      if (!nodeLogtapeBindingUsable(lines, binding, line)) continue;
      const arguments_ = nodeLogtapeCallArgumentsAtLine(
        lines,
        line,
        callPattern,
      );
      const options = arguments_?.[0];
      if (options === undefined) continue;
      const resolved = resolveJavascriptExpression(lines, options, line);
      if (
        resolved === undefined ||
        javascriptObjectPropertyValue(
          resolved.value,
          "includeStructuredData",
        )?.trim() !== "true"
      ) {
        continue;
      }
      const assignment = new RegExp(
        `^\\s*(?:export\\s+)?(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)(?:\\s*:\\s*[^=;]+)?\\s*=\\s*(?:await\\s+)?${access}\\s*\\(`,
        "u",
      ).exec(statement);
      sinks.push({
        binding,
        line,
        ...(assignment?.[1] === undefined ? {} : { variable: assignment[1] }),
      });
    }
  }
  return sinks.filter(
    (sink, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.line === sink.line && candidate.variable === sink.variable,
      ) === index,
  );
}

function nodeLogtapeSinkForEntry(
  entry: JavascriptPropertyEntry,
  sinks: readonly NodeLogtapeStructuredSink[],
): NodeLogtapeStructuredSink | undefined {
  const value = entry.value.trim();
  const variable = sinks.find(
    (sink) => sink.variable !== undefined && sink.variable === value,
  );
  if (variable !== undefined) return variable;
  const lastLine = entry.line + (entry.value.match(/\n/gu)?.length ?? 0);
  return sinks.find(
    (sink) =>
      sink.line >= entry.line &&
      sink.line <= lastLine &&
      new RegExp(
        `\\b${nodeLogtapeBindingPattern(sink.binding)}\\s*\\(`,
        "u",
      ).test(entry.value),
  );
}

function nodeLogtapeTopologies(
  lines: readonly string[],
  sinks: readonly NodeLogtapeStructuredSink[],
  configureBindings: readonly NodeLogtapeBinding[],
): NodeLogtapeTopology[] {
  const structural = javascriptStructuralLines(lines);
  const topologies: NodeLogtapeTopology[] = [];
  for (const binding of configureBindings) {
    const access = nodeLogtapeBindingPattern(binding);
    const callPattern = new RegExp(`\\b${access}\\s*\\(`, "u");
    for (let index = binding.line; index < structural.length; index += 1) {
      const line = index + 1;
      if (!callPattern.test(structural[index] ?? "")) continue;
      if (!nodeLogtapeBindingUsable(lines, binding, line)) continue;
      const arguments_ = nodeLogtapeCallArgumentsAtLine(
        lines,
        line,
        callPattern,
      );
      const configuration = arguments_?.[0];
      if (configuration === undefined) continue;
      const resolvedConfiguration = resolveJavascriptExpression(
        lines,
        configuration,
        line,
      );
      if (resolvedConfiguration === undefined) continue;
      const configurationEntries = javascriptObjectEntries(
        resolvedConfiguration,
      );
      const sinksEntry = configurationEntries.find(
        (entry) => entry.key === "sinks",
      );
      const loggersEntry = configurationEntries.find(
        (entry) => entry.key === "loggers",
      );
      if (sinksEntry === undefined || loggersEntry === undefined) continue;
      const resolvedSinks = resolveJavascriptExpression(
        lines,
        sinksEntry.value,
        sinksEntry.line,
      );
      const resolvedLoggers = resolveJavascriptExpression(
        lines,
        loggersEntry.value,
        loggersEntry.line,
      );
      if (resolvedSinks === undefined || resolvedLoggers === undefined)
        continue;
      const connectedSinks = javascriptObjectEntries(resolvedSinks).flatMap(
        (entry) => {
          const sink = nodeLogtapeSinkForEntry(entry, sinks);
          return sink === undefined ? [] : [{ sink, sinkName: entry.key }];
        },
      );
      if (connectedSinks.length === 0) continue;
      for (const loggerExpression of javascriptArrayEntries(resolvedLoggers)) {
        const resolvedLogger = resolveJavascriptExpression(
          lines,
          loggerExpression.value,
          loggerExpression.line,
        );
        if (resolvedLogger === undefined) continue;
        const loggerEntries = javascriptObjectEntries(resolvedLogger);
        const loggerSinks = loggerEntries.find(
          (entry) => entry.key === "sinks",
        );
        const loggerCategory = loggerEntries.find(
          (entry) => entry.key === "category",
        );
        if (loggerSinks === undefined || loggerCategory === undefined) continue;
        const resolvedLoggerSinks = resolveJavascriptExpression(
          lines,
          loggerSinks.value,
          loggerSinks.line,
        );
        const category = nodeLogtapeCategory(
          lines,
          loggerCategory.value,
          loggerCategory.line,
        );
        if (resolvedLoggerSinks === undefined || category === undefined)
          continue;
        const sinkNames = nodeLogtapeLiteralStrings(resolvedLoggerSinks);
        if (sinkNames === undefined) continue;
        for (const connected of connectedSinks) {
          if (!sinkNames.includes(connected.sinkName)) continue;
          topologies.push({
            configureBinding: binding,
            configureLine: line,
            configuredCategory: category,
            sink: connected.sink,
            sinkName: connected.sinkName,
          });
        }
      }
    }
  }
  return topologies;
}

function nodeLogtapeCategoryMatches(
  configured: readonly string[],
  logger: readonly string[],
): boolean {
  return (
    configured.length <= logger.length &&
    configured.every((value, index) => logger[index] === value)
  );
}

function nodeLogtapeLoggers(
  lines: readonly string[],
  bindings: readonly NodeLogtapeBinding[],
  topologies: readonly NodeLogtapeTopology[],
): NodeLogtapeLogger[] {
  const structural = javascriptStructuralLines(lines);
  const loggers: NodeLogtapeLogger[] = [];
  for (const binding of bindings) {
    const access = nodeLogtapeBindingPattern(binding);
    const callPattern = new RegExp(`\\b${access}\\s*\\(`, "u");
    for (let index = binding.line; index < structural.length; index += 1) {
      const line = index + 1;
      const statement = structural[index] ?? "";
      if (!callPattern.test(statement)) continue;
      if (!nodeLogtapeBindingUsable(lines, binding, line)) continue;
      const assignment = new RegExp(
        `^\\s*(?:export\\s+)?(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)(?:\\s*:\\s*[^=;]+)?\\s*=\\s*${access}\\s*\\(`,
        "u",
      ).exec(statement);
      if (assignment?.[1] === undefined) continue;
      const arguments_ = nodeLogtapeCallArgumentsAtLine(
        lines,
        line,
        callPattern,
      );
      const category = nodeLogtapeCategory(lines, arguments_?.[0], line);
      if (category === undefined) continue;
      for (const topology of topologies) {
        if (
          topology.configureLine >= line ||
          !nodeLogtapeCategoryMatches(topology.configuredCategory, category)
        ) {
          continue;
        }
        loggers.push({
          binding,
          category,
          line,
          local: assignment[1],
          topology,
        });
      }
    }
  }
  return loggers;
}

function nodeLogtapeRemoteExpression(
  lines: readonly string[],
  expression: string,
  line: number,
  routeParameters: readonly string[],
): Omit<NodeLogtapeRemoteProperty, "boundary"> | undefined {
  const resolved = resolveJavascriptExpression(lines, expression, line);
  if (resolved === undefined) return undefined;
  let value = resolved.value.replace(/\s+/gu, " ").trim();
  const stringWrapper = /^String\s*\(\s*([\s\S]+)\s*\)$/u.exec(value);
  if (stringWrapper?.[1] !== undefined) value = stringWrapper[1].trim();
  const interpolation = /^`\$\{\s*([\s\S]+?)\s*\}`$/u.exec(value);
  if (interpolation?.[1] !== undefined) value = interpolation[1].trim();
  const requestMember =
    /^([A-Za-z_$][\w$]*)\s*\.\s*(body|query|params|headers)(?:\s*\.\s*[A-Za-z_$][\w$]*|\s*\[[^\]]+\])*$/u.exec(
      value,
    );
  if (
    requestMember?.[1] !== undefined &&
    requestMember[2] !== undefined &&
    routeParameters.includes(requestMember[1])
  ) {
    return {
      kind: `remote-request-${requestMember[2]}`,
      line: resolved.line,
      symbol: value.replace(/\s+/gu, ""),
    };
  }
  const requestGetter =
    /^(?:await\s+)?([A-Za-z_$][\w$]*)\s*\.\s*(?:(headers)\s*\.\s*get|get|header|text)\s*\([^)]*\)$/u.exec(
      value,
    );
  if (
    requestGetter?.[1] !== undefined &&
    routeParameters.includes(requestGetter[1])
  ) {
    return {
      kind:
        requestGetter[2] === "headers"
          ? "remote-request-header"
          : "remote-request-value",
      line: resolved.line,
      symbol: value.replace(/\s+/gu, ""),
    };
  }
  return undefined;
}

function nodeLogtapeRemoteProperty(
  lines: readonly string[],
  expression: string,
  line: number,
  routeParameters: readonly string[],
): NodeLogtapeRemoteProperty | undefined {
  const resolved = resolveJavascriptExpression(lines, expression, line);
  if (resolved === undefined) return undefined;
  for (const entry of javascriptObjectEntries(resolved)) {
    const source = nodeLogtapeRemoteExpression(
      lines,
      entry.value,
      entry.line,
      routeParameters,
    );
    if (source !== undefined) {
      return { ...source, boundary: "structured-data-value" };
    }
  }
  const object = javascriptCompositePrefix(resolved.value, "{", "}");
  if (object === undefined) return undefined;
  for (const entry of javascriptDelimitedEntries(object.slice(1, -1))) {
    const entryLine =
      resolved.line +
      (object.slice(0, entry.offset + 1).match(/\n/gu)?.length ?? 0);
    const computed = /^\s*\[\s*([\s\S]+?)\s*\]\s*:/u.exec(entry.value);
    const spread = /^\s*\.\.\.\s*([\s\S]+)$/u.exec(entry.value);
    const candidate = computed?.[1] ?? spread?.[1];
    if (candidate === undefined) continue;
    const source = nodeLogtapeRemoteExpression(
      lines,
      candidate,
      entryLine,
      routeParameters,
    );
    if (source !== undefined) {
      return { ...source, boundary: "structured-data-key" };
    }
  }
  return undefined;
}

function nodeLogtapeSyslogInjectionRecords(
  files: readonly SourceFileSnapshot[],
): ResidualRiskRecord[] {
  const records: ResidualRiskRecord[] = [];
  const emitted = new Set<string>();
  for (const file of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path) ||
      !file.text.includes("@logtape/syslog") ||
      !file.text.includes("includeStructuredData")
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(
      files,
      file.path,
      "@logtape/syslog",
    );
    if (
      dependency === undefined ||
      !nodeLogtapeVersionHasSyslogInjection(dependency.version)
    ) {
      continue;
    }
    const sinkBindings = nodeLogtapeBindings(
      file.lines,
      "@logtape/syslog",
      "getSyslogSink",
    );
    const configureBindings = nodeLogtapeBindings(
      file.lines,
      "@logtape/logtape",
      "configure",
    );
    const loggerBindings = nodeLogtapeBindings(
      file.lines,
      "@logtape/logtape",
      "getLogger",
    );
    const sinks = nodeLogtapeStructuredSinks(file.lines, sinkBindings);
    const topologies = nodeLogtapeTopologies(
      file.lines,
      sinks,
      configureBindings,
    );
    const loggers = nodeLogtapeLoggers(file.lines, loggerBindings, topologies);
    if (loggers.length === 0) continue;
    const structural = javascriptStructuralLines(file.lines);
    const functions = exportedJavascriptFunctions(file.lines);
    for (const logger of loggers) {
      const loggerPattern = escapeRegularExpression(logger.local);
      const callPattern = new RegExp(
        `\\b${loggerPattern}\\s*\\.\\s*(?:debug|info|warning|error|fatal|trace)\\s*\\(`,
        "u",
      );
      for (let index = logger.line; index < structural.length; index += 1) {
        const line = index + 1;
        if (!callPattern.test(structural[index] ?? "")) continue;
        const route = functions.find(
          (candidate) =>
            line >= candidate.startLine && line <= candidate.endLine,
        );
        if (
          route === undefined ||
          route.parameters.includes(logger.local) ||
          javascriptIdentifierReassignedBetween(
            file.lines,
            logger.local,
            logger.line,
            line + 1,
          )
        ) {
          continue;
        }
        const arguments_ = nodeLogtapeCallArgumentsAtLine(
          file.lines,
          line,
          callPattern,
        );
        const properties = arguments_?.[1];
        if (properties === undefined) continue;
        const source = nodeLogtapeRemoteProperty(
          file.lines,
          properties,
          line,
          route.parameters,
        );
        if (source === undefined) continue;
        const key = `${file.path}\0${source.line}\0${logger.topology.sink.line}\0${line}`;
        if (emitted.has(key)) continue;
        emitted.add(key);
        const prefix =
          dependency.proof === "npm-lockfile" ? "lock-resolved-" : "";
        const sinkKind = `${prefix}vulnerable-logtape-syslog-${source.boundary}`;
        const startLine = Math.max(1, line - CONTEXT_LINES_BEFORE);
        const endLine = Math.min(file.lines.length, line + CONTEXT_LINES_AFTER);
        const sourceStart = Math.max(1, source.line - CONTEXT_LINES_BEFORE);
        records.push({
          path: file.path,
          line,
          categories: [
            "framework-dataflow:node-logtape-syslog-structured-data-injection",
            `modeled-source:${source.kind}`,
            `modeled-sink:${sinkKind}`,
            "broken-control:unescaped-syslog-structured-data",
          ],
          priority: 126,
          startLine,
          endLine,
          excerpt: sourceExcerpt(file.lines, startLine, endLine),
          sourceExcerpt: sourceExcerpt(
            file.lines,
            sourceStart,
            Math.min(file.lines.length, line + CONTEXT_LINES_AFTER),
          ),
          frameworkModel: {
            schemaVersion: "1.2",
            id: "node-logtape-syslog-structured-data-injection",
            language: "javascript-typescript",
            scope: "same-file",
            source: {
              kind: source.kind,
              path: file.path,
              line: source.line,
            },
            sink: {
              kind: sinkKind,
              path: file.path,
              line,
              cweIds: ["CWE-93", "CWE-117"],
            },
            propagators: [
              {
                kind: "remote-log-record-property",
                path: file.path,
                line: source.line,
                symbol: `${source.boundary}:${source.symbol}`,
              },
              {
                kind: "official-logtape-logger-binding",
                path: file.path,
                line: logger.binding.line,
                symbol: logger.binding.local,
              },
              {
                kind: "connected-logtape-syslog-sink",
                path: file.path,
                line: logger.topology.configureLine,
                symbol: `${logger.topology.sinkName}:${logger.category.join(".") || "root"}`,
              },
              {
                kind: "official-logtape-configure-binding",
                path: file.path,
                line: logger.topology.configureBinding.line,
                symbol: logger.topology.configureBinding.local,
              },
              {
                kind: "enabled-logtape-structured-data",
                path: file.path,
                line: logger.topology.sink.line,
                symbol: "includeStructuredData:true",
              },
              {
                kind: "official-logtape-syslog-binding",
                path: file.path,
                line: logger.topology.sink.binding.line,
                symbol: logger.topology.sink.binding.local,
              },
              {
                kind: "logtape-syslog-runtime-dependency",
                path: dependency.manifestPath,
                line: dependency.line,
                symbol: `@logtape/syslog@${dependency.version}:${dependency.proof}:unescaped-structured-data`,
              },
            ],
            candidateControls: [],
          },
        });
        if (records.length >= MAX_FRAMEWORK_MULTI_HOP_RECORDS) return records;
      }
    }
  }
  return records;
}

interface NodeSunEditorBinding {
  line: number;
  local: string;
  member: "create" | "embed" | undefined;
}

interface NodeSunEditorRemoteContent {
  kind: string;
  line: number;
  symbol: string;
}

function nodeSunEditorVersionHasEmbedXss(version: string): boolean {
  const match = /^(\d+)\.(\d+)\.(\d+)$/u.exec(version);
  if (match === null) return false;
  const [major, minor, patch] = match.slice(1).map(Number) as [
    number,
    number,
    number,
  ];
  return (
    major < 3 || (major === 3 && (minor < 1 || (minor === 1 && patch < 4)))
  );
}

function nodeSunEditorBindingPattern(binding: NodeSunEditorBinding): string {
  const local = escapeRegularExpression(binding.local);
  return binding.member === undefined
    ? local
    : `${local}\\s*\\.\\s*${binding.member}`;
}

function nodeSunEditorBindings(
  lines: readonly string[],
  kind: "create" | "embed",
): NodeSunEditorBinding[] {
  const bindings: NodeSunEditorBinding[] = [];
  const aggregatePlugin =
    /^suneditor\/(?:plugins|src\/plugins(?:\/index(?:\.js)?)?)$/u;
  const directEmbed = /^suneditor\/src\/plugins\/modal\/embed(?:\.js)?$/u;
  if (kind === "create") {
    bindings.push(
      ...importedJavascriptSymbols(lines)
        .filter(
          (binding) =>
            binding.moduleSpecifier === "suneditor" &&
            binding.imported === "create",
        )
        .map((binding) => ({
          line: binding.line,
          local: binding.local,
          member: undefined,
        })),
    );
  } else {
    bindings.push(
      ...importedJavascriptSymbols(lines)
        .filter(
          (binding) =>
            aggregatePlugin.test(binding.moduleSpecifier) &&
            binding.imported === "embed",
        )
        .map((binding) => ({
          line: binding.line,
          local: binding.local,
          member: undefined,
        })),
    );
  }
  for (let index = 0; index < lines.length; index += 1) {
    const code = javascriptCodeBeforeComment(lines[index] ?? "");
    if (kind === "create") {
      const receiver =
        /^\s*import\s+(?:\*\s+as\s+)?([A-Za-z_$][\w$]*)\s+from\s+["']suneditor["']/u.exec(
          code,
        ) ??
        /^\s*import\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["']suneditor["']\s*\)/u.exec(
          code,
        ) ??
        /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["']suneditor["']\s*\)\s*;?\s*$/u.exec(
          code,
        );
      if (receiver?.[1] !== undefined) {
        bindings.push({
          line: index + 1,
          local: receiver[1],
          member: "create",
        });
      }
      const direct =
        /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["']suneditor["']\s*\)\s*\.\s*create\s*;?\s*$/u.exec(
          code,
        ) ??
        /^\s*(?:const|let|var)\s*\{\s*create(?:\s*:\s*([A-Za-z_$][\w$]*))?\s*\}\s*=\s*require\s*\(\s*["']suneditor["']\s*\)/u.exec(
          code,
        );
      if (direct !== null) {
        bindings.push({
          line: index + 1,
          local: direct[1] ?? "create",
          member: undefined,
        });
      }
      continue;
    }
    const defaultImport =
      /^\s*import\s+([A-Za-z_$][\w$]*)\s+from\s+["'](suneditor\/(?:plugins|src\/plugins(?:\/index(?:\.js)?)?)|suneditor\/src\/plugins\/modal\/embed(?:\.js)?)["']/u.exec(
        code,
      );
    if (defaultImport?.[1] !== undefined && defaultImport[2] !== undefined) {
      bindings.push({
        line: index + 1,
        local: defaultImport[1],
        member: directEmbed.test(defaultImport[2]) ? undefined : "embed",
      });
    }
    const receiver =
      /^\s*import\s+\*\s+as\s+([A-Za-z_$][\w$]*)\s+from\s+["'](suneditor\/(?:plugins|src\/plugins(?:\/index(?:\.js)?)?))["']/u.exec(
        code,
      ) ??
      /^\s*import\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["'](suneditor\/(?:plugins|src\/plugins(?:\/index(?:\.js)?)?))["']\s*\)/u.exec(
        code,
      ) ??
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["'](suneditor\/(?:plugins|src\/plugins(?:\/index(?:\.js)?)?))["']\s*\)\s*;?\s*$/u.exec(
        code,
      );
    if (receiver?.[1] !== undefined) {
      bindings.push({ line: index + 1, local: receiver[1], member: "embed" });
    }
    const direct =
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["']suneditor\/src\/plugins\/modal\/embed(?:\.js)?["']\s*\)\s*;?\s*$/u.exec(
        code,
      ) ??
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["']suneditor\/(?:plugins|src\/plugins(?:\/index(?:\.js)?)?)["']\s*\)\s*\.\s*embed\s*;?\s*$/u.exec(
        code,
      ) ??
      /^\s*(?:const|let|var)\s*\{\s*embed(?:\s*:\s*([A-Za-z_$][\w$]*))?\s*\}\s*=\s*require\s*\(\s*["']suneditor\/(?:plugins|src\/plugins(?:\/index(?:\.js)?)?)["']\s*\)/u.exec(
        code,
      );
    if (direct !== null) {
      bindings.push({
        line: index + 1,
        local: direct[1] ?? "embed",
        member: undefined,
      });
    }
  }
  return bindings.filter(
    (binding, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.line === binding.line &&
          candidate.local === binding.local &&
          candidate.member === binding.member,
      ) === index,
  );
}

function nodeSunEditorBindingUsable(
  lines: readonly string[],
  binding: NodeSunEditorBinding,
  useLine: number,
  route: ExportedJavascriptFunction,
): boolean {
  if (
    binding.line >= useLine ||
    route.parameters.includes(binding.local) ||
    javascriptIdentifierReassignedBetween(
      lines,
      binding.local,
      binding.line,
      useLine + 1,
    )
  ) {
    return false;
  }
  if (binding.member === undefined) return true;
  const access = nodeSunEditorBindingPattern(binding);
  return !javascriptStructuralLines(lines)
    .slice(binding.line, Math.max(binding.line, useLine - 1))
    .some((line) =>
      new RegExp(
        `\\b${access}\\s*(?:[+\\-*/%&|^?]?=(?!=|>)|\\+\\+|--)`,
        "u",
      ).test(line),
    );
}

function nodeSunEditorPluginsContainBinding(
  lines: readonly string[],
  expression: string,
  line: number,
  binding: NodeSunEditorBinding,
): boolean {
  const resolved = resolveJavascriptExpression(lines, expression, line);
  if (resolved === undefined) return false;
  const access = new RegExp(`^${nodeSunEditorBindingPattern(binding)}$`, "u");
  if (binding.member === "embed" && resolved.value.trim() === binding.local) {
    return true;
  }
  return javascriptObjectEntries(resolved).some(
    (entry) => entry.key === "embed" && access.test(entry.value.trim()),
  );
}

function nodeSunEditorHasEmbedButton(
  lines: readonly string[],
  expression: string,
  line: number,
  depth = 0,
): boolean {
  if (depth > 5) return false;
  const resolved = resolveJavascriptExpression(lines, expression, line);
  if (resolved === undefined) return false;
  return javascriptArrayEntries(resolved).some((entry) => {
    if (/^["']embed["']$/u.test(entry.value.trim())) return true;
    return nodeSunEditorHasEmbedButton(
      lines,
      entry.value,
      entry.line,
      depth + 1,
    );
  });
}

function nodeSunEditorRemoteContent(
  lines: readonly string[],
  expression: string,
  line: number,
  route: ExportedJavascriptFunction,
): NodeSunEditorRemoteContent | undefined {
  return nodeLogtapeRemoteExpression(lines, expression, line, route.parameters);
}

function nodeSunEditorEmbedXssRecords(
  files: readonly SourceFileSnapshot[],
): ResidualRiskRecord[] {
  const records: ResidualRiskRecord[] = [];
  const emitted = new Set<string>();
  for (const file of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path) ||
      !file.text.includes("suneditor") ||
      !file.text.includes("embed")
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(files, file.path, "suneditor");
    if (
      dependency === undefined ||
      !nodeSunEditorVersionHasEmbedXss(dependency.version)
    ) {
      continue;
    }
    const createBindings = nodeSunEditorBindings(file.lines, "create");
    const embedBindings = nodeSunEditorBindings(file.lines, "embed");
    const routes = exportedJavascriptFunctions(file.lines);
    const structural = javascriptStructuralLines(file.lines);
    for (const createBinding of createBindings) {
      const createAccess = nodeSunEditorBindingPattern(createBinding);
      const createCall = new RegExp(`\\b${createAccess}\\s*\\(`, "u");
      for (
        let index = createBinding.line;
        index < structural.length;
        index += 1
      ) {
        const line = index + 1;
        if (!createCall.test(structural[index] ?? "")) continue;
        const route = routes.find(
          (candidate) =>
            line >= candidate.startLine && line <= candidate.endLine,
        );
        if (
          route === undefined ||
          !nodeSunEditorBindingUsable(file.lines, createBinding, line, route)
        ) {
          continue;
        }
        const arguments_ = javascriptCallArgumentsAtLine(
          file.lines,
          line,
          createCall,
        );
        const optionsExpression = arguments_?.[1];
        if (optionsExpression === undefined) continue;
        const options = resolveJavascriptExpression(
          file.lines,
          optionsExpression,
          line,
        );
        if (options === undefined) continue;
        const optionEntries = javascriptObjectEntries(options);
        const plugins = optionEntries.find((entry) => entry.key === "plugins");
        const buttons = optionEntries.find(
          (entry) => entry.key === "buttonList",
        );
        if (plugins === undefined || buttons === undefined) continue;
        const embedBinding = embedBindings.find(
          (binding) =>
            nodeSunEditorBindingUsable(file.lines, binding, line, route) &&
            nodeSunEditorPluginsContainBinding(
              file.lines,
              plugins.value,
              plugins.line,
              binding,
            ),
        );
        if (
          embedBinding === undefined ||
          !nodeSunEditorHasEmbedButton(file.lines, buttons.value, buttons.line)
        ) {
          continue;
        }
        let sinkLine = line;
        let source: NodeSunEditorRemoteContent | undefined;
        let boundary = "initial-editor-value";
        const value = optionEntries.find((entry) => entry.key === "value");
        if (value !== undefined) {
          source = nodeSunEditorRemoteContent(
            file.lines,
            value.value,
            value.line,
            route,
          );
        }
        if (source === undefined) {
          const assignment = new RegExp(
            `^\\s*(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*${createAccess}\\s*\\(`,
            "u",
          ).exec(structural[index] ?? "");
          const editor = assignment?.[1];
          if (editor !== undefined) {
            const setContents = new RegExp(
              `\\b${escapeRegularExpression(editor)}\\s*\\.\\s*setContents\\s*\\(`,
              "u",
            );
            for (
              let useIndex = index + 1;
              useIndex < Math.min(structural.length, route.endLine);
              useIndex += 1
            ) {
              const useLine = useIndex + 1;
              if (!setContents.test(structural[useIndex] ?? "")) continue;
              if (
                javascriptIdentifierReassignedBetween(
                  file.lines,
                  editor,
                  line,
                  useLine + 1,
                )
              ) {
                break;
              }
              const setArguments = javascriptCallArgumentsAtLine(
                file.lines,
                useLine,
                setContents,
              );
              const candidate = setArguments?.[0];
              if (candidate === undefined) continue;
              source = nodeSunEditorRemoteContent(
                file.lines,
                candidate,
                useLine,
                route,
              );
              if (source !== undefined) {
                sinkLine = useLine;
                boundary = "setContents";
                break;
              }
            }
          }
        }
        if (source === undefined) continue;
        const key = `${file.path}\0${source.line}\0${line}\0${sinkLine}`;
        if (emitted.has(key)) continue;
        emitted.add(key);
        const prefix =
          dependency.proof === "npm-lockfile" ? "lock-resolved-" : "";
        const sinkKind = `${prefix}vulnerable-suneditor-embed-external-script-dom-append`;
        const startLine = Math.max(1, sinkLine - CONTEXT_LINES_BEFORE);
        const endLine = Math.min(
          file.lines.length,
          sinkLine + CONTEXT_LINES_AFTER,
        );
        const sourceStart = Math.max(1, source.line - CONTEXT_LINES_BEFORE);
        records.push({
          path: file.path,
          line: sinkLine,
          categories: [
            "framework-dataflow:node-suneditor-embed-external-script-xss",
            `modeled-source:${source.kind}`,
            `modeled-sink:${sinkKind}`,
            "broken-control:embed-script-recreated-in-live-dom",
          ],
          priority: 127,
          startLine,
          endLine,
          excerpt: sourceExcerpt(file.lines, startLine, endLine),
          sourceExcerpt: sourceExcerpt(
            file.lines,
            sourceStart,
            Math.min(file.lines.length, sinkLine + CONTEXT_LINES_AFTER),
          ),
          frameworkModel: {
            schemaVersion: "1.2",
            id: "node-suneditor-embed-external-script-xss",
            language: "javascript-typescript",
            scope: "same-file",
            source: {
              kind: source.kind,
              path: file.path,
              line: source.line,
            },
            sink: {
              kind: sinkKind,
              path: file.path,
              line: sinkLine,
              cweIds: ["CWE-79"],
            },
            propagators: [
              {
                kind: "remote-stored-editor-content",
                path: file.path,
                line: source.line,
                symbol: `${source.symbol}->${boundary}`,
              },
              {
                kind: "official-suneditor-create-binding",
                path: file.path,
                line: createBinding.line,
                symbol: createBinding.local,
              },
              {
                kind: "enabled-suneditor-embed-plugin",
                path: file.path,
                line: plugins.line,
                symbol: nodeSunEditorBindingPattern(embedBinding),
              },
              {
                kind: "enabled-suneditor-embed-button",
                path: file.path,
                line: buttons.line,
                symbol: "buttonList:embed",
              },
              {
                kind: "suneditor-runtime-dependency",
                path: dependency.manifestPath,
                line: dependency.line,
                symbol: `suneditor@${dependency.version}:${dependency.proof}:unrestricted-embed-script-src`,
              },
            ],
            candidateControls: [],
          },
        });
        if (records.length >= MAX_FRAMEWORK_MULTI_HOP_RECORDS) return records;
      }
    }
  }
  return records;
}

const NODE_NX_SELF_HOSTED_CACHE_PACKAGES = [
  "@nx/azure-cache",
  "@nx/gcs-cache",
  "@nx/powerpack-azure-cache",
  "@nx/powerpack-gcs-cache",
  "@nx/powerpack-s3-cache",
  "@nx/powerpack-shared-fs-cache",
  "@nx/s3-cache",
  "@nx/shared-fs-cache",
] as const;

type NodeNxSelfHostedCachePackage =
  (typeof NODE_NX_SELF_HOSTED_CACHE_PACKAGES)[number];

interface NodeNxBuildDependency extends NodeRuntimeDependency {
  packageName: string;
}

interface NodeNxCacheEvidence {
  file: SourceFileSnapshot;
  kind: string;
  line: number;
  symbol: string;
}

function nodeNxBuildDependency(
  files: readonly SourceFileSnapshot[],
  sourcePath: string,
  dependencyName: string,
): NodeNxBuildDependency | undefined {
  const manifests = files
    .filter(
      (file) =>
        posix.basename(file.path) === "package.json" &&
        pathWithinDirectory(sourcePath, posix.dirname(file.path)),
    )
    .sort(
      (left, right) =>
        posix.dirname(right.path).length - posix.dirname(left.path).length,
    );
  const manifest = manifests[0];
  if (manifest === undefined) return undefined;
  let parsed: unknown;
  try {
    parsed = JSON.parse(manifest.text) as unknown;
  } catch {
    return undefined;
  }
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    return undefined;
  }
  const sections = [
    "dependencies",
    "optionalDependencies",
    "devDependencies",
  ] as const;
  const root = parsed as Record<string, unknown>;
  const declarations = sections.flatMap((section) => {
    const dependencies = root[section];
    if (
      typeof dependencies !== "object" ||
      dependencies === null ||
      Array.isArray(dependencies)
    ) {
      return [];
    }
    const value = (dependencies as Record<string, unknown>)[dependencyName];
    return typeof value === "string" ? [value] : [];
  });
  if (
    declarations.length === 0 ||
    declarations.some((value) => value !== declarations[0])
  ) {
    return undefined;
  }
  const declaration = declarations[0]!;
  const exact = nodeExactSemver(declaration);
  const version = exact
    ? declaration
    : nodeRegistrySemverDeclaration(declaration)
      ? nodePackageLockResolvedVersion(
          files,
          manifest,
          dependencyName,
          declaration,
          sections,
        )
      : undefined;
  if (version === undefined) return undefined;
  const escaped = escapeRegularExpression(dependencyName);
  const line =
    manifest.lines.findIndex((candidate) =>
      new RegExp(`^[\\s\"]*${escaped}\"\\s*:`, "u").test(candidate),
    ) + 1;
  return {
    packageName: dependencyName,
    manifestPath: manifest.path,
    line: Math.max(1, line),
    version,
    proof: exact ? "manifest-exact" : "npm-lockfile",
  };
}

function nodeNxHttpCacheVersionHasArchiveEscape(version: string): boolean {
  const match = /^(\d+)\.(\d+)\.(\d+)$/u.exec(version);
  if (match === null) return false;
  const [major, minor, patch] = match.slice(1).map(Number) as [
    number,
    number,
    number,
  ];
  if (major === 20) return minor > 8 || (minor === 8 && patch >= 0);
  if (major === 21) return true;
  if (major === 22) return minor < 7 || (minor === 7 && patch <= 6);
  return major === 23 && minor === 0 && patch <= 1;
}

function nodeNxCacheDisabledNear(
  lines: readonly string[],
  line: number,
): boolean {
  const nearby = lines
    .slice(Math.max(0, line - 6), Math.min(lines.length, line + 5))
    .join("\n");
  return (
    /--skip[-_]?nx[-_]?cache\b/iu.test(nearby) ||
    /\bNX_SKIP_NX_CACHE\b\s*(?::|=)\s*["']?(?:1|true)\b/iu.test(nearby) ||
    /\bNX_POWERPACK_CACHE_MODE\b\s*(?::|=)\s*["']?no-cache\b/iu.test(nearby)
  );
}

function nodeNxCacheableTaskInvocations(
  files: readonly SourceFileSnapshot[],
): NodeNxCacheEvidence[] {
  const invocations: NodeNxCacheEvidence[] = [];
  const administrative = new Set([
    "add",
    "connect",
    "daemon",
    "exec",
    "format",
    "generate",
    "graph",
    "import",
    "init",
    "list",
    "migrate",
    "new",
    "register",
    "repair",
    "report",
    "reset",
    "show",
    "sync",
    "view-logs",
  ]);
  const command =
    /\b(?:(?:npx|bunx|yarn|pnpm(?:\s+(?:exec|dlx))?|npm\s+exec)\s+)?nx(?:\.cmd)?\s+([A-Za-z][\w:-]*)/iu;
  for (const file of files) {
    if (
      javascriptTestOrExamplePath(file.path) ||
      posix.basename(file.path) === "package-lock.json" ||
      posix.basename(file.path) === "npm-shrinkwrap.json" ||
      !/\bnx(?:\.cmd)?\b/iu.test(file.text)
    ) {
      continue;
    }
    for (let index = 0; index < file.lines.length; index += 1) {
      const source = file.lines[index] ?? "";
      const match = command.exec(source);
      if (match?.[1] === undefined) continue;
      const operation = match[1].toLowerCase();
      if (
        administrative.has(operation) ||
        nodeNxCacheDisabledNear(file.lines, index + 1)
      ) {
        continue;
      }
      invocations.push({
        file,
        kind: "nx-cache-consuming-task-execution",
        line: index + 1,
        symbol: match[0].replace(/\s+/gu, " ").trim(),
      });
    }
  }
  return invocations;
}

function nodeNxHttpCacheActivations(
  files: readonly SourceFileSnapshot[],
): NodeNxCacheEvidence[] {
  const activations: NodeNxCacheEvidence[] = [];
  for (const file of files) {
    if (
      javascriptTestOrExamplePath(file.path) ||
      !file.text.includes("NX_SELF_HOSTED_REMOTE_CACHE_SERVER")
    ) {
      continue;
    }
    for (let index = 0; index < file.lines.length; index += 1) {
      const source = file.lines[index] ?? "";
      if (/^\s*(?:#|\/\/)/u.test(source)) continue;
      const assignment =
        /\bNX_SELF_HOSTED_REMOTE_CACHE_SERVER\b(?:["']?\s*\])?\s*(?::|=)\s*(.+)$/u.exec(
          source,
        );
      const value = assignment?.[1]?.trim().replace(/[,;]\s*$/u, "");
      if (
        value === undefined ||
        value === "" ||
        /^(?:["']{2}|false|null|undefined)$/iu.test(value)
      ) {
        continue;
      }
      activations.push({
        file,
        kind: "nx-self-hosted-http-cache-configuration",
        line: index + 1,
        symbol: "NX_SELF_HOSTED_REMOTE_CACHE_SERVER",
      });
    }
  }
  return activations;
}

function nodeNxProviderConfigurationKey(
  packageName: NodeNxSelfHostedCachePackage,
): "azure" | "gcs" | "s3" | "shared-fs" {
  if (packageName.includes("azure")) return "azure";
  if (packageName.includes("gcs")) return "gcs";
  if (packageName.includes("s3")) return "s3";
  return "shared-fs";
}

function nodeNxCiPath(path: string): boolean {
  return (
    path.startsWith(".github/workflows/") ||
    /(?:^|\/)(?:\.circleci\/config\.yml|\.gitlab-ci\.yml|azure-pipelines\.ya?ml|Jenkinsfile)$/iu.test(
      path,
    ) ||
    path.includes(".buildkite/")
  );
}

function nodeNxProviderConfiguration(
  files: readonly SourceFileSnapshot[],
  dependency: NodeNxBuildDependency,
  packageName: NodeNxSelfHostedCachePackage,
  invocation: NodeNxCacheEvidence,
): NodeNxCacheEvidence | undefined {
  const key = nodeNxProviderConfigurationKey(packageName);
  if (key === "shared-fs") {
    if (!nodeNxCiPath(invocation.file.path)) return undefined;
    return {
      file: invocation.file,
      kind: "nx-shared-filesystem-cache-ci-activation",
      line: invocation.line,
      symbol: `${packageName}:CI`,
    };
  }
  const directory = posix.dirname(dependency.manifestPath);
  const configPath =
    directory === "." ? "nx.json" : posix.join(directory, "nx.json");
  const config = files.find((file) => file.path === configPath);
  if (config === undefined) return undefined;
  let parsed: unknown;
  try {
    parsed = JSON.parse(config.text) as unknown;
  } catch {
    return undefined;
  }
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    return undefined;
  }
  const provider = (parsed as Record<string, unknown>)[key];
  if (
    typeof provider !== "object" ||
    provider === null ||
    Array.isArray(provider)
  ) {
    return undefined;
  }
  const settings = provider as Record<string, unknown>;
  const mode = nodeNxCiPath(invocation.file.path)
    ? settings["ciMode"]
    : settings["localMode"];
  if (mode === "no-cache") return undefined;
  const line =
    config.lines.findIndex((candidate) =>
      new RegExp(`^\\s*\"${escapeRegularExpression(key)}\"\\s*:`, "u").test(
        candidate,
      ),
    ) + 1;
  return {
    file: config,
    kind: `nx-${key}-cache-configuration`,
    line: Math.max(1, line),
    symbol: `${packageName}:${key}`,
  };
}

function nodeNxSelfHostedCacheArchiveEscapeRecords(
  files: readonly SourceFileSnapshot[],
): ResidualRiskRecord[] {
  const records: ResidualRiskRecord[] = [];
  const emitted = new Set<string>();
  const invocations = nodeNxCacheableTaskInvocations(files);
  const httpActivations = nodeNxHttpCacheActivations(files);
  for (const invocation of invocations) {
    const nx = nodeNxBuildDependency(files, invocation.file.path, "nx");
    if (
      nx !== undefined &&
      nodeNxHttpCacheVersionHasArchiveEscape(nx.version)
    ) {
      const activation = httpActivations.find(
        (candidate) => candidate.file.path === invocation.file.path,
      );
      if (activation !== undefined) {
        const key = `http\0${invocation.file.path}\0${invocation.line}`;
        if (!emitted.has(key)) {
          emitted.add(key);
          records.push(
            nodeNxSelfHostedCacheArchiveEscapeRecord(
              invocation,
              activation,
              nx,
              "http",
            ),
          );
        }
      }
    }
    for (const packageName of NODE_NX_SELF_HOSTED_CACHE_PACKAGES) {
      const dependency = nodeNxBuildDependency(
        files,
        invocation.file.path,
        packageName,
      );
      if (
        dependency === undefined ||
        !/^\d+\.\d+\.\d+$/u.test(dependency.version)
      ) {
        continue;
      }
      const activation = nodeNxProviderConfiguration(
        files,
        dependency,
        packageName,
        invocation,
      );
      if (activation === undefined) continue;
      const key = `${packageName}\0${invocation.file.path}\0${invocation.line}`;
      if (emitted.has(key)) continue;
      emitted.add(key);
      records.push(
        nodeNxSelfHostedCacheArchiveEscapeRecord(
          invocation,
          activation,
          dependency,
          nodeNxProviderConfigurationKey(packageName),
        ),
      );
      if (records.length >= MAX_FRAMEWORK_MULTI_HOP_RECORDS) return records;
    }
  }
  return records;
}

function nodeNxSelfHostedCacheArchiveEscapeRecord(
  invocation: NodeNxCacheEvidence,
  activation: NodeNxCacheEvidence,
  dependency: NodeNxBuildDependency,
  surface: "azure" | "gcs" | "http" | "s3" | "shared-fs",
): ResidualRiskRecord {
  const lockResolved = dependency.proof === "npm-lockfile";
  const packageLabel = dependency.packageName;
  const sinkKind = `${lockResolved ? "lock-resolved-" : ""}${surface === "http" ? "vulnerable-nx-http-remote-cache-restore" : "unpatched-nx-provider-cache-restore"}`;
  const startLine = Math.max(1, invocation.line - CONTEXT_LINES_BEFORE);
  const endLine = Math.min(
    invocation.file.lines.length,
    invocation.line + CONTEXT_LINES_AFTER,
  );
  const sourceStart = Math.max(1, activation.line - CONTEXT_LINES_BEFORE);
  const sourceEnd = Math.min(
    activation.file.lines.length,
    activation.line + CONTEXT_LINES_AFTER,
  );
  return {
    path: invocation.file.path,
    line: invocation.line,
    categories: [
      "framework-dataflow:node-nx-self-hosted-cache-archive-escape",
      `modeled-source:${activation.kind}`,
      `modeled-sink:${sinkKind}`,
      "broken-control:unconfined-remote-cache-archive-extraction",
    ],
    priority: 126,
    startLine,
    endLine,
    excerpt: sourceExcerpt(invocation.file.lines, startLine, endLine),
    sourceExcerpt: sourceExcerpt(activation.file.lines, sourceStart, sourceEnd),
    frameworkModel: {
      schemaVersion: "1.2",
      id: "node-nx-self-hosted-cache-archive-escape",
      language: "javascript-typescript",
      scope:
        activation.file.path === invocation.file.path
          ? "same-file"
          : "cross-file",
      source: {
        kind: activation.kind,
        path: activation.file.path,
        line: activation.line,
      },
      sink: {
        kind: sinkKind,
        path: invocation.file.path,
        line: invocation.line,
        cweIds: ["CWE-22", "CWE-59"],
      },
      propagators: [
        {
          kind: activation.kind,
          path: activation.file.path,
          line: activation.line,
          symbol: activation.symbol,
        },
        {
          kind: invocation.kind,
          path: invocation.file.path,
          line: invocation.line,
          symbol: invocation.symbol,
        },
        {
          kind:
            surface === "http"
              ? "nx-runtime-dependency"
              : "nx-provider-cache-dependency",
          path: dependency.manifestPath,
          line: dependency.line,
          symbol: `${packageLabel}@${dependency.version}:${dependency.proof}:${surface === "http" ? "unconfined-http-cache-tar-extraction" : "unpatched-provider-cache-tar-extraction"}`,
        },
      ],
      candidateControls: [],
    },
  };
}

interface NodeUndiciAgentBinding {
  local: string;
  line: number;
  constructor: string;
}

interface NodeUndiciRequestUse {
  file: SourceFileSnapshot;
  line: number;
  operation: "fetch" | "request";
  target: string;
  options: string;
}

function nodeUndiciSocks5VersionIsCrossOriginVulnerable(
  version: string,
): boolean {
  const match = /^(\d+)\.(\d+)\.(\d+)$/u.exec(version);
  if (match === null) return false;
  const major = Number(match[1]);
  const minor = Number(match[2]);
  return (
    (major === 7 && minor >= 23 && minor < 28) || (major === 8 && minor < 2)
  );
}

function nodeUndiciOfficialExpressions(lines: readonly string[]): {
  constructors: Array<{
    expression: string;
    protections: NodeShescapeBindingProtection[];
  }>;
  requests: Array<{
    expression: string;
    operation: "fetch" | "request";
    protections: NodeShescapeBindingProtection[];
  }>;
  setters: Array<{
    expression: string;
    protections: NodeShescapeBindingProtection[];
  }>;
} {
  const constructors: Array<{
    expression: string;
    protections: NodeShescapeBindingProtection[];
  }> = importedJavascriptSymbols(lines)
    .filter(
      (binding) =>
        binding.moduleSpecifier === "undici" &&
        binding.imported === "Socks5ProxyAgent",
    )
    .map((binding) => ({
      expression: binding.local,
      protections: [{ local: binding.local, line: binding.line }],
    }));
  const requests: Array<{
    expression: string;
    operation: "fetch" | "request";
    protections: NodeShescapeBindingProtection[];
  }> = importedJavascriptSymbols(lines)
    .filter(
      (binding) =>
        binding.moduleSpecifier === "undici" &&
        (binding.imported === "fetch" || binding.imported === "request"),
    )
    .map((binding) => ({
      expression: binding.local,
      operation: binding.imported as "fetch" | "request",
      protections: [{ local: binding.local, line: binding.line }],
    }));
  const setters: Array<{
    expression: string;
    protections: NodeShescapeBindingProtection[];
  }> = importedJavascriptSymbols(lines)
    .filter(
      (binding) =>
        binding.moduleSpecifier === "undici" &&
        binding.imported === "setGlobalDispatcher",
    )
    .map((binding) => ({
      expression: binding.local,
      protections: [{ local: binding.local, line: binding.line }],
    }));
  const codeLines = javascriptCodeLinesWithoutComments(lines);
  for (let index = 0; index < codeLines.length; index += 1) {
    const line = codeLines[index] ?? "";
    const receiver =
      /^\s*import\s+\*\s+as\s+([A-Za-z_$][\w$]*)\s+from\s+["']undici["']/u.exec(
        line,
      ) ??
      /^\s*import\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["']undici["']\s*\)/u.exec(
        line,
      ) ??
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*["']undici["']\s*\)/u.exec(
        line,
      );
    if (receiver === null) continue;
    const local = receiver[1]!;
    const lineNumber = index + 1;
    constructors.push({
      expression: `${local}\\s*\\.\\s*Socks5ProxyAgent`,
      protections: [
        { local, line: lineNumber },
        { local, line: lineNumber, member: "Socks5ProxyAgent" },
      ],
    });
    requests.push(
      {
        expression: `${local}\\s*\\.\\s*fetch`,
        operation: "fetch",
        protections: [
          { local, line: lineNumber },
          { local, line: lineNumber, member: "fetch" },
        ],
      },
      {
        expression: `${local}\\s*\\.\\s*request`,
        operation: "request",
        protections: [
          { local, line: lineNumber },
          { local, line: lineNumber, member: "request" },
        ],
      },
    );
    setters.push({
      expression: `${local}\\s*\\.\\s*setGlobalDispatcher`,
      protections: [
        { local, line: lineNumber },
        { local, line: lineNumber, member: "setGlobalDispatcher" },
      ],
    });
  }
  return { constructors, requests, setters };
}

function nodeUndiciResolvedExpression(
  lines: readonly string[],
  expression: string,
  line: number,
): string {
  return (
    resolveJavascriptExpression(lines, expression, line)?.value ?? expression
  );
}

function nodeUndiciRemoteTarget(
  lines: readonly string[],
  expression: string,
  line: number,
): boolean {
  const value = nodeUndiciResolvedExpression(lines, expression, line);
  return /\b(?:req|request)\s*(?:\.|\[)\s*(?:body|cookies|headers|params|query)\b|\bctx\s*\.\s*(?:headers|params|query|request\s*\.\s*body)\b|\b(?:searchParams|nextUrl\s*\.\s*searchParams)\s*\.\s*(?:get|getAll)\s*\(/iu.test(
    value,
  );
}

function nodeUndiciCredentialedOptions(options: string): boolean {
  return /(?:^|[,{]\s*)(?:["']?(?:authorization|cookie|proxy-authorization)["']?)\s*:\s*(?!["']{2}|false\b|null\b|undefined\b)[^,}]+/iu.test(
    options,
  );
}

function nodeUndiciSocks5CrossOriginRoutingRecords(
  files: readonly SourceFileSnapshot[],
): ResidualRiskRecord[] {
  const records: ResidualRiskRecord[] = [];
  for (const file of files) {
    if (
      javascriptTestOrExamplePath(file.path) ||
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      !file.text.includes("Socks5ProxyAgent")
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(files, file.path, "undici");
    if (
      dependency === undefined ||
      !nodeUndiciSocks5VersionIsCrossOriginVulnerable(dependency.version)
    ) {
      continue;
    }
    const official = nodeUndiciOfficialExpressions(file.lines);
    if (official.constructors.length === 0 || official.requests.length === 0) {
      continue;
    }
    const structural = javascriptStructuralLines(file.lines);
    const agents: NodeUndiciAgentBinding[] = [];
    for (let index = 0; index < structural.length; index += 1) {
      for (const constructor of official.constructors) {
        const declaration = new RegExp(
          `^\\s*(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*new\\s+${constructor.expression}\\s*\\(`,
          "u",
        ).exec(structural[index] ?? "");
        if (
          declaration !== null &&
          nodePackageBindingUsable(
            file.lines,
            constructor.protections,
            index + 1,
          )
        ) {
          agents.push({
            local: declaration[1]!,
            line: index + 1,
            constructor: constructor.expression,
          });
        }
      }
    }
    for (const agent of agents) {
      const uses: NodeUndiciRequestUse[] = [];
      const globalAssignments: Array<{ line: number; dispatcher: string }> = [];
      for (let index = agent.line; index < structural.length; index += 1) {
        for (const setter of official.setters) {
          if (
            !nodePackageBindingUsable(file.lines, setter.protections, index + 1)
          ) {
            continue;
          }
          const callee = new RegExp(`\\b${setter.expression}\\s*\\(`, "u");
          if (!callee.test(structural[index] ?? "")) continue;
          const arguments_ = javascriptCallArgumentsAtLine(
            file.lines,
            index + 1,
            callee,
          );
          const dispatcher = arguments_?.[0]?.trim();
          if (dispatcher !== undefined) {
            globalAssignments.push({ line: index + 1, dispatcher });
          }
        }
      }
      for (let index = agent.line; index < structural.length; index += 1) {
        if (
          javascriptIdentifierReassignedBetween(
            file.lines,
            agent.local,
            agent.line,
            index + 2,
          )
        ) {
          break;
        }
        for (const request of official.requests) {
          if (
            !nodePackageBindingUsable(
              file.lines,
              request.protections,
              index + 1,
            )
          ) {
            continue;
          }
          const callee = new RegExp(`\\b${request.expression}\\s*\\(`, "u");
          if (!callee.test(structural[index] ?? "")) continue;
          const arguments_ = javascriptCallArgumentsAtLine(
            file.lines,
            index + 1,
            callee,
          );
          if (arguments_ === undefined || arguments_.length < 1) continue;
          const options = nodeUndiciResolvedExpression(
            file.lines,
            arguments_[1] ?? "{}",
            index + 1,
          );
          const explicitDispatcher = javascriptObjectPropertyValue(
            options,
            "dispatcher",
          )?.trim();
          const activeGlobal = globalAssignments
            .filter((assignment) => assignment.line < index + 1)
            .at(-1)?.dispatcher;
          if (
            explicitDispatcher !== agent.local &&
            !(explicitDispatcher === undefined && activeGlobal === agent.local)
          ) {
            continue;
          }
          uses.push({
            file,
            line: index + 1,
            operation: request.operation,
            target: arguments_[0]?.trim() ?? "",
            options,
          });
        }
      }
      const first = uses.find((use) =>
        nodeUndiciRemoteTarget(file.lines, use.target, use.line),
      );
      const later = uses.find(
        (use) =>
          first !== undefined &&
          use.line > first.line &&
          nodeUndiciCredentialedOptions(use.options),
      );
      if (first === undefined || later === undefined) continue;
      const startLine = Math.max(1, later.line - CONTEXT_LINES_BEFORE);
      const endLine = Math.min(
        file.lines.length,
        later.line + CONTEXT_LINES_AFTER,
      );
      const sourceStart = Math.max(1, first.line - CONTEXT_LINES_BEFORE);
      const sourceEnd = Math.min(
        file.lines.length,
        first.line + CONTEXT_LINES_AFTER,
      );
      records.push({
        path: file.path,
        line: later.line,
        categories: [
          "framework-dataflow:node-undici-socks5-cross-origin-routing",
          "modeled-source:remote-first-socks5-origin",
          "modeled-sink:credentialed-later-socks5-origin",
          "broken-control:single-cross-origin-socks5-pool",
        ],
        priority: 125,
        startLine,
        endLine,
        excerpt: sourceExcerpt(file.lines, startLine, endLine),
        sourceExcerpt: sourceExcerpt(file.lines, sourceStart, sourceEnd),
        frameworkModel: {
          schemaVersion: "1.2",
          id: "node-undici-socks5-cross-origin-routing",
          language: "javascript-typescript",
          scope: "same-file",
          source: {
            kind: "remote-first-socks5-origin",
            path: file.path,
            line: first.line,
          },
          sink: {
            kind:
              dependency.proof === "npm-lockfile"
                ? "lock-resolved-credentialed-later-socks5-origin"
                : "credentialed-later-socks5-origin",
            path: file.path,
            line: later.line,
            cweIds: ["CWE-346"],
          },
          propagators: [
            {
              kind: "shared-undici-socks5-agent",
              path: file.path,
              line: agent.line,
              symbol: agent.local,
            },
            ...(() => {
              const activation = globalAssignments
                .filter(
                  (assignment) =>
                    assignment.line < first.line &&
                    assignment.dispatcher === agent.local,
                )
                .at(-1);
              return activation === undefined
                ? []
                : [
                    {
                      kind: "undici-global-dispatcher-activation",
                      path: file.path,
                      line: activation.line,
                      symbol: agent.local,
                    },
                  ];
            })(),
            {
              kind: "remote-first-socks5-origin",
              path: file.path,
              line: first.line,
              symbol: first.operation,
            },
            {
              kind: "credentialed-later-socks5-origin",
              path: file.path,
              line: later.line,
              symbol: later.operation,
            },
            {
              kind: "undici-runtime-dependency",
              path: dependency.manifestPath,
              line: dependency.line,
              symbol: `undici@${dependency.version}:${dependency.proof}:single-cross-origin-socks5-pool`,
            },
          ],
          candidateControls: [],
        },
      });
      if (records.length >= MAX_FRAMEWORK_MULTI_HOP_RECORDS) return records;
    }
  }
  return records;
}

interface NodeAuthJsFactoryBinding {
  local: string;
  line: number;
  member?: "default";
}

interface NodeAuthJsWrapperBinding {
  dependency: NodeRuntimeDependency;
  exported: boolean;
  factory: NodeAuthJsFactoryBinding;
  factoryLine: number;
  file: SourceFileSnapshot;
  line: number;
  symbol: string;
}

interface NodeAuthJsWrapperUse {
  binding: NodeAuthJsWrapperBinding;
  exposureLine?: number;
  file: SourceFileSnapshot;
  importLine?: number;
  importedSymbol?: string;
  local: string;
}

interface NodeAuthJsFailOpenDecision {
  sinkFile?: SourceFileSnapshot;
  sinkLine: number;
  sourceLine: number;
}

function nodeAuthJsVersionHasConfigurationErrorFailOpen(
  version: string,
): boolean {
  const match = /^5\.0\.0-beta\.(\d+)$/u.exec(version);
  return match !== null && Number(match[1]) <= 31;
}

function nodeAuthJsFactoryBindings(
  lines: readonly string[],
): NodeAuthJsFactoryBinding[] {
  const bindings: NodeAuthJsFactoryBinding[] = [];
  const add = (binding: NodeAuthJsFactoryBinding): void => {
    if (
      !bindings.some(
        (candidate) =>
          candidate.local === binding.local &&
          candidate.line === binding.line &&
          candidate.member === binding.member,
      )
    ) {
      bindings.push(binding);
    }
  };
  const codeLines = javascriptCodeLinesWithoutComments(lines);
  for (let index = 0; index < codeLines.length; index += 1) {
    const code = codeLines[index] ?? "";
    const defaultImport =
      /^\s*import\s+(?!type\b)([A-Za-z_$][\w$]*)(?:\s*,\s*\{[^}]*\})?\s+from\s+['"]next-auth['"]/u.exec(
        code,
      );
    if (defaultImport?.[1] !== undefined) {
      add({ local: defaultImport[1], line: index + 1 });
    }
    const namespace =
      /^\s*import\s+\*\s+as\s+([A-Za-z_$][\w$]*)\s+from\s+['"]next-auth['"]/u.exec(
        code,
      );
    if (namespace?.[1] !== undefined) {
      add({ local: namespace[1], line: index + 1, member: "default" });
    }
    const importEquals =
      /^\s*import\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*['"]next-auth['"]\s*\)/u.exec(
        code,
      );
    if (importEquals?.[1] !== undefined) {
      add({ local: importEquals[1], line: index + 1, member: "default" });
    }
    const commonJs =
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*['"]next-auth['"]\s*\)\s*;?\s*$/u.exec(
        code,
      );
    if (commonJs?.[1] !== undefined) {
      add({ local: commonJs[1], line: index + 1, member: "default" });
    }
    const commonJsDefault =
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*['"]next-auth['"]\s*\)\s*\.\s*default\s*;?\s*$/u.exec(
        code,
      );
    if (commonJsDefault?.[1] !== undefined) {
      add({ local: commonJsDefault[1], line: index + 1 });
    }
    const destructuredDefault =
      /^\s*(?:const|let|var)\s*\{\s*default\s*:\s*([A-Za-z_$][\w$]*)\s*\}\s*=\s*require\s*\(\s*['"]next-auth['"]\s*\)\s*;?\s*$/u.exec(
        code,
      );
    if (destructuredDefault?.[1] !== undefined) {
      add({ local: destructuredDefault[1], line: index + 1 });
    }
  }
  return bindings;
}

function nodeAuthJsGeneratedWrapperBindings(
  files: readonly SourceFileSnapshot[],
): NodeAuthJsWrapperBinding[] {
  const wrappers: NodeAuthJsWrapperBinding[] = [];
  for (const file of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path) ||
      !/['"]next-auth['"]/u.test(file.text)
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(files, file.path, "next-auth");
    if (
      dependency === undefined ||
      !nodeAuthJsVersionHasConfigurationErrorFailOpen(dependency.version)
    ) {
      continue;
    }
    const structuralLines = javascriptStructuralLines(file.lines);
    for (const factory of nodeAuthJsFactoryBindings(file.lines)) {
      const receiver =
        factory.member === undefined
          ? escapeRegularExpression(factory.local)
          : `${escapeRegularExpression(factory.local)}\\s*\\.\\s*default`;
      for (
        let index = factory.line;
        index < structuralLines.length;
        index += 1
      ) {
        if (
          javascriptIdentifierReassignedBetween(
            file.lines,
            factory.local,
            factory.line,
            index + 2,
          )
        ) {
          break;
        }
        const declaration = structuralLines
          .slice(index, Math.min(structuralLines.length, index + 13))
          .join("\n");
        const destructured = new RegExp(
          `^\\s*(export\\s+)?(?:const|let|var)\\s*\\{([\\s\\S]*?)\\}\\s*=\\s*${receiver}\\s*\\(`,
          "u",
        ).exec(declaration);
        if (destructured !== null) {
          for (const rawBinding of splitJavascriptArguments(
            destructured[2] ?? "",
          )) {
            const parsed = /^\s*auth(?:\s*:\s*([A-Za-z_$][\w$]*))?\s*$/u.exec(
              rawBinding,
            );
            if (parsed === null) continue;
            wrappers.push({
              dependency,
              exported: destructured[1] !== undefined,
              factory,
              factoryLine: factory.line,
              file,
              line: index + 1,
              symbol: parsed[1] ?? "auth",
            });
          }
        }

        const member = new RegExp(
          `^\\s*(export\\s+)?(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*${receiver}\\s*\\(`,
          "u",
        ).exec(declaration);
        if (member?.[2] !== undefined) {
          const open = declaration.indexOf(
            "(",
            member.index + member[0].length - 1,
          );
          const close = matchingCallParenthesis(declaration, open);
          if (
            open >= 0 &&
            close >= 0 &&
            /^\s*\.\s*auth\b/u.test(declaration.slice(close + 1))
          ) {
            wrappers.push({
              dependency,
              exported: member[1] !== undefined,
              factory,
              factoryLine: factory.line,
              file,
              line: index + 1,
              symbol: member[2],
            });
          }
        }

        const commonJsMember = new RegExp(
          `^\\s*(?:module\\.)?exports\\.([A-Za-z_$][\\w$]*)\\s*=\\s*${receiver}\\s*\\(`,
          "u",
        ).exec(declaration);
        if (commonJsMember?.[1] !== undefined) {
          const commonJsOpen = declaration.indexOf(
            "(",
            commonJsMember.index + commonJsMember[0].length - 1,
          );
          const commonJsClose = matchingCallParenthesis(
            declaration,
            commonJsOpen,
          );
          if (
            commonJsOpen >= 0 &&
            commonJsClose >= 0 &&
            /^\s*\.\s*auth\b/u.test(declaration.slice(commonJsClose + 1))
          ) {
            wrappers.push({
              dependency,
              exported: true,
              factory,
              factoryLine: factory.line,
              file,
              line: index + 1,
              symbol: commonJsMember[1],
            });
          }
        }
      }
    }
  }
  return wrappers.filter(
    (wrapper, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.file.path === wrapper.file.path &&
          candidate.line === wrapper.line &&
          candidate.symbol === wrapper.symbol,
      ) === index,
  );
}

function nodeAuthJsAliasImportTarget(
  moduleSpecifier: string,
  wrappers: readonly NodeAuthJsWrapperBinding[],
  importedSymbol: string,
  manifestPath: string,
): NodeAuthJsWrapperBinding | undefined {
  const prefix = ["@/", "~/"].find((candidate) =>
    moduleSpecifier.startsWith(candidate),
  );
  if (prefix === undefined) return undefined;
  const suffix = moduleSpecifier.slice(prefix.length).replaceAll("\\", "/");
  if (
    suffix === "" ||
    suffix === "." ||
    suffix.includes("..") ||
    posix.isAbsolute(suffix)
  ) {
    return undefined;
  }
  const matches = wrappers.filter((wrapper) => {
    if (
      !wrapper.exported ||
      wrapper.symbol !== importedSymbol ||
      wrapper.dependency.manifestPath !== manifestPath
    ) {
      return false;
    }
    const extension = posix.extname(wrapper.file.path);
    const stem =
      extension === ""
        ? wrapper.file.path
        : wrapper.file.path.slice(0, -extension.length);
    return stem === suffix || stem.endsWith(`/${suffix}`);
  });
  return matches.length === 1 ? matches[0] : undefined;
}

function nodeAuthJsImportedWrapperBinding(
  callerPath: string,
  moduleSpecifier: string,
  importedSymbol: string,
  manifestPath: string,
  knownPaths: ReadonlyMap<string, string>,
  wrappers: readonly NodeAuthJsWrapperBinding[],
): NodeAuthJsWrapperBinding | undefined {
  const relativePath = resolveRelativeModelImport(
    callerPath,
    moduleSpecifier,
    knownPaths,
  );
  return (
    wrappers.find(
      (candidate) =>
        candidate.exported &&
        candidate.dependency.manifestPath === manifestPath &&
        candidate.file.path === relativePath &&
        candidate.symbol === importedSymbol,
    ) ??
    nodeAuthJsAliasImportTarget(
      moduleSpecifier,
      wrappers,
      importedSymbol,
      manifestPath,
    )
  );
}

function nodeAuthJsWrapperUses(
  files: readonly SourceFileSnapshot[],
  wrappers: readonly NodeAuthJsWrapperBinding[],
): NodeAuthJsWrapperUse[] {
  const knownPaths = new Map(
    files.map((file) => [modelPathComparisonKey(file.path), file.path]),
  );
  const uses: NodeAuthJsWrapperUse[] = [];
  for (const file of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path)
    ) {
      continue;
    }
    const structuralLines = javascriptStructuralLines(file.lines);
    const codeLines = javascriptCodeLinesWithoutComments(file.lines);
    for (const binding of wrappers.filter(
      (candidate) => candidate.file.path === file.path,
    )) {
      uses.push({ binding, file, local: binding.symbol });
    }
    for (const imported of importedJavascriptSymbols(file.lines)) {
      const callerDependency = nodeRuntimeDependency(
        files,
        file.path,
        "next-auth",
      );
      if (callerDependency === undefined) continue;
      const binding = nodeAuthJsImportedWrapperBinding(
        file.path,
        imported.moduleSpecifier,
        imported.imported,
        callerDependency.manifestPath,
        knownPaths,
        wrappers,
      );
      if (binding === undefined) continue;
      if (
        callerDependency.manifestPath !== binding.dependency.manifestPath ||
        callerDependency.version !== binding.dependency.version
      ) {
        continue;
      }
      uses.push({
        binding,
        exposureLine:
          structuralLines.findIndex((line, index) => {
            if (index + 1 <= imported.line) return false;
            const local = escapeRegularExpression(imported.local);
            return (
              new RegExp(
                `^\\s*export\\s*\\{\\s*${local}\\s+as\\s+(?:proxy|middleware|default)\\s*\\}`,
                "u",
              ).test(line) ||
              new RegExp(
                `^\\s*export\\s+default\\s+${local}\\s*;?\\s*$`,
                "u",
              ).test(line) ||
              new RegExp(
                `^\\s*export\\s+(?:const|let|var)\\s+(?:proxy|middleware)\\s*=\\s*${local}\\s*;?\\s*$`,
                "u",
              ).test(line)
            );
          }) + 1 || undefined,
        file,
        importLine: imported.line,
        importedSymbol: imported.imported,
        local: imported.local,
      });
    }
    for (let index = 0; index < structuralLines.length; index += 1) {
      const reexport =
        /^\s*export\s*\{([^}]+)\}\s*from\s*['"]([^'"]+)['"]/u.exec(
          codeLines[index] ?? "",
        );
      if (reexport === null) continue;
      const callerDependency = nodeRuntimeDependency(
        files,
        file.path,
        "next-auth",
      );
      if (callerDependency === undefined) continue;
      for (const rawBinding of splitJavascriptArguments(reexport[1] ?? "")) {
        const exported =
          /^\s*([A-Za-z_$][\w$]*)\s+as\s+(proxy|middleware|default)\s*$/u.exec(
            rawBinding,
          );
        if (exported?.[1] === undefined) continue;
        const binding = nodeAuthJsImportedWrapperBinding(
          file.path,
          reexport[2]!,
          exported[1],
          callerDependency.manifestPath,
          knownPaths,
          wrappers,
        );
        if (
          binding === undefined ||
          callerDependency.version !== binding.dependency.version
        ) {
          continue;
        }
        uses.push({
          binding,
          exposureLine: index + 1,
          file,
          importLine: index + 1,
          importedSymbol: exported[1],
          local: exported[2]!,
        });
      }
    }
  }
  return uses.filter(
    (use, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.file.path === use.file.path &&
          candidate.local === use.local &&
          candidate.binding.file.path === use.binding.file.path &&
          candidate.binding.line === use.binding.line,
      ) === index,
  );
}

function nodeAuthJsFirstCallArgument(
  lines: readonly string[],
  line: number,
  callee: RegExp,
): JavascriptResolvedExpression | undefined {
  const callLines = lines.slice(line - 1, Math.min(lines.length, line + 95));
  const original = javascriptCodeLinesWithoutComments(callLines).join("\n");
  const structural = javascriptStructuralLines(callLines).join("\n");
  const firstLine = structural.split("\n", 1)[0] ?? "";
  const match = callee.exec(firstLine);
  if (match === null) return undefined;
  const open = structural.indexOf("(", match.index);
  const close = matchingCallParenthesis(structural, open);
  if (open < 0 || close < 0) return undefined;
  const argumentText = original.slice(open + 1, close);
  const first = javascriptDelimitedEntries(argumentText)[0];
  if (first === undefined) return undefined;
  const prefix = original.slice(0, open + 1 + first.offset);
  return {
    line: line + (prefix.match(/\n/gu)?.length ?? 0),
    value: first.value,
  };
}

function nodeAuthJsAuthorizedCallbackFailOpenDecision(
  binding: NodeAuthJsWrapperBinding,
): number | undefined {
  const receiver =
    binding.factory.member === undefined
      ? escapeRegularExpression(binding.factory.local)
      : `${escapeRegularExpression(binding.factory.local)}\\s*\\.\\s*default`;
  const configArgument = nodeAuthJsFirstCallArgument(
    binding.file.lines,
    binding.line,
    new RegExp(`\\b${receiver}\\s*\\(`, "u"),
  );
  if (configArgument === undefined) return undefined;
  const config = resolveJavascriptExpression(
    binding.file.lines,
    configArgument.value,
    configArgument.line,
  );
  if (config === undefined) return undefined;
  const callbacksEntry = javascriptObjectEntries(config).find(
    (entry) => entry.key === "callbacks",
  );
  if (callbacksEntry === undefined) return undefined;
  const callbacks = resolveJavascriptExpression(
    binding.file.lines,
    callbacksEntry.value,
    callbacksEntry.line,
  );
  if (callbacks === undefined) return undefined;
  const text = javascriptCodeLinesWithoutComments(
    callbacks.value.split(/\r?\n/u),
  ).join("\n");
  const property = /\bauthorized\s*:\s*/u.exec(text);
  const method = /(?:^|[,{\n])\s*(?:async\s+)?authorized\s*\(/u.exec(text);
  let start: number;
  if (
    property !== null &&
    (method === null || property.index <= method.index)
  ) {
    start = property.index + property[0].length;
  } else if (method !== null) {
    const authorizedOffset = method[0].indexOf("authorized");
    start = method.index + Math.max(0, authorizedOffset);
  } else {
    return undefined;
  }
  const callbackEntry = javascriptDelimitedEntries(text.slice(start))[0];
  if (callbackEntry === undefined) return undefined;
  const callbackStart = start + callbackEntry.offset;
  return nodeAuthJsCallbackFailOpenDecision(
    {
      line:
        callbacks.line +
        (text.slice(0, callbackStart).match(/\n/gu)?.length ?? 0),
      value: callbackEntry.value,
    },
    true,
  );
}

function nodeAuthJsCallbackParameters(callback: string):
  | {
      authIdentifiers: string[];
      requestIdentifier?: string;
    }
  | undefined {
  const destructured =
    /^\s*(?:async\s*)?(?:\(\s*)?\{([^}]*)\}(?:\s*\))?(?:\s*:\s*[^=]+)?\s*=>/u.exec(
      callback,
    ) ??
    /^\s*(?:async\s+)?function(?:\s+[A-Za-z_$][\w$]*)?\s*\(\s*\{([^}]*)\}/u.exec(
      callback,
    ) ??
    /^\s*(?:async\s+)?authorized\s*\(\s*\{([^}]*)\}/u.exec(callback);
  if (destructured !== null) {
    const auth = splitJavascriptArguments(destructured[1] ?? "")
      .map((binding) =>
        /^\s*auth(?:\s*:\s*([A-Za-z_$][\w$]*))?(?:\s*=.*)?\s*$/u.exec(binding),
      )
      .find((candidate) => candidate !== null);
    if (auth === undefined || auth === null) return undefined;
    return { authIdentifiers: [auth[1] ?? "auth"] };
  }
  const identifier =
    /^\s*(?:async\s*)?\(\s*([A-Za-z_$][\w$]*)(?:\s*\??\s*:\s*[^,)]+)?[^)]*\)\s*=>/u.exec(
      callback,
    ) ??
    /^\s*(?:async\s*)?([A-Za-z_$][\w$]*)\s*=>/u.exec(callback) ??
    /^\s*(?:async\s+)?function(?:\s+[A-Za-z_$][\w$]*)?\s*\(\s*([A-Za-z_$][\w$]*)/u.exec(
      callback,
    );
  return identifier?.[1] === undefined
    ? undefined
    : { authIdentifiers: [], requestIdentifier: identifier[1] };
}

function nodeAuthJsConditionHasConsequence(
  lines: readonly string[],
  index: number,
  matchEnd: number,
): boolean {
  const action =
    /\breturn\b|\b(?:NextResponse|Response)\s*\.\s*(?:next|redirect|rewrite)\s*\(|\bnew\s+Response\s*\(|\b(?:redirect|rewrite|notFound|unauthorized)\s*\(/u;
  const sameLine = lines[index]?.slice(matchEnd) ?? "";
  if (action.test(sameLine)) return true;
  if (sameLine.trim() !== "" && sameLine.trim() !== "{") return false;
  const structural = javascriptStructuralLines(lines);
  let statementLine = index + 1;
  while (
    statementLine < lines.length &&
    (structural[statementLine] ?? "").trim() === ""
  ) {
    statementLine += 1;
  }
  if (statementLine >= lines.length) return false;
  const firstStatement = structural[statementLine] ?? "";
  if (!firstStatement.trimStart().startsWith("{")) {
    return action.test(lines[statementLine] ?? "");
  }
  const endLine = javascriptFunctionEndLine(lines, statementLine);
  return action.test(lines.slice(statementLine, endLine).join("\n"));
}

function nodeAuthJsCallbackFailOpenDecision(
  callback: JavascriptResolvedExpression,
  booleanReturnIsAuthorization = false,
): number | undefined {
  const parameters = nodeAuthJsCallbackParameters(callback.value);
  if (parameters === undefined) return undefined;
  const lines = javascriptCodeLinesWithoutComments(
    callback.value.split(/\r?\n/u),
  );
  const authIdentifiers = new Set(parameters.authIdentifiers);
  if (parameters.requestIdentifier !== undefined) {
    const request = escapeRegularExpression(parameters.requestIdentifier);
    for (const line of lines) {
      const destructured = new RegExp(
        `\\b(?:const|let|var)\\s*\\{\\s*auth(?:\\s*:\\s*([A-Za-z_$][\\w$]*))?[^}]*\\}\\s*=\\s*${request}\\b`,
        "u",
      ).exec(line);
      if (destructured !== null) {
        authIdentifiers.add(destructured[1] ?? "auth");
      }
      const alias = new RegExp(
        `\\b(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*${request}\\s*\\.\\s*auth\\b`,
        "u",
      ).exec(line);
      if (alias?.[1] !== undefined) authIdentifiers.add(alias[1]);
    }
  }
  const references = [
    ...(parameters.requestIdentifier === undefined
      ? []
      : [
          `${escapeRegularExpression(parameters.requestIdentifier)}\\s*\\.\\s*auth`,
        ]),
    ...[...authIdentifiers].map(escapeRegularExpression),
  ];
  if (references.length === 0) return undefined;
  const reference = `(?:${references.join("|")})\\b(?!\\s*(?:\\?\\.|\\.)\\s*[A-Za-z_$])`;
  const truthTest = new RegExp(
    `(?:!!\\s*${reference}|!(?!=)\\s*${reference}|\\bBoolean\\s*\\(\\s*${reference}\\s*\\))`,
    "u",
  );
  const condition = new RegExp(
    `\\bif\\s*\\(\\s*!{0,2}\\s*${reference}(?:\\s*[!=]==?\\s*(?:null|undefined))?\\s*\\)`,
    "u",
  );
  const ternary = new RegExp(`${reference}\\s*\\?`, "u");
  const responseAction =
    /\b(?:NextResponse|Response)\s*\.\s*(?:next|redirect|rewrite)\s*\(|\bnew\s+Response\s*\(|\b(?:redirect|rewrite|notFound|unauthorized)\s*\(/u;
  const aliases = new Map<string, number>();
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index] ?? "";
    const assignment = new RegExp(
      `\\b(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*(?:!!\\s*${reference}|\\bBoolean\\s*\\(\\s*${reference}\\s*\\))`,
      "u",
    ).exec(line);
    if (assignment?.[1] !== undefined) aliases.set(assignment[1], index);
    const conditionMatch = condition.exec(line);
    const window = lines
      .slice(index, Math.min(lines.length, index + 7))
      .join("\n");
    if (
      (booleanReturnIsAuthorization &&
        ((/\breturn\b/u.test(line) && truthTest.test(line)) ||
          new RegExp(`=>\\s*${truthTest.source}`, "u").test(line))) ||
      (conditionMatch !== null &&
        nodeAuthJsConditionHasConsequence(
          lines,
          index,
          conditionMatch.index + conditionMatch[0].length,
        )) ||
      (ternary.test(line) && responseAction.test(window))
    ) {
      return callback.line + index;
    }
  }
  for (const [alias, assignmentLine] of aliases) {
    const aliasCondition = new RegExp(
      `\\bif\\s*\\(\\s*!{0,2}\\s*${escapeRegularExpression(alias)}\\b[^)]*\\)`,
      "u",
    );
    const aliasTernary = new RegExp(
      `\\b${escapeRegularExpression(alias)}\\s*\\?`,
      "u",
    );
    for (
      let index = assignmentLine + 1;
      index < Math.min(lines.length, assignmentLine + 17);
      index += 1
    ) {
      const line = lines[index] ?? "";
      const conditionMatch = aliasCondition.exec(line);
      if (
        booleanReturnIsAuthorization &&
        new RegExp(
          `\\breturn\\s+!?${escapeRegularExpression(alias)}\\b`,
          "u",
        ).test(line)
      ) {
        return callback.line + assignmentLine;
      }
      if (
        conditionMatch !== null &&
        nodeAuthJsConditionHasConsequence(
          lines,
          index,
          conditionMatch.index + conditionMatch[0].length,
        )
      ) {
        return callback.line + assignmentLine;
      }
      if (
        aliasTernary.test(line) &&
        responseAction.test(
          lines.slice(index, Math.min(lines.length, index + 7)).join("\n"),
        )
      ) {
        return callback.line + assignmentLine;
      }
    }
  }
  return undefined;
}

function nodeAuthJsNoArgumentFailOpenDecision(
  lines: readonly string[],
  local: string,
  bindingLine: number,
): NodeAuthJsFailOpenDecision[] {
  const decisions: NodeAuthJsFailOpenDecision[] = [];
  const structuralLines = javascriptStructuralLines(lines);
  const escaped = escapeRegularExpression(local);
  const declaration = new RegExp(
    `^\\s*(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*(?:await\\s+)?${escaped}\\s*\\(\\s*\\)`,
    "u",
  );
  for (let index = bindingLine; index < structuralLines.length; index += 1) {
    const match = declaration.exec(structuralLines[index] ?? "");
    if (match?.[1] === undefined) continue;
    const sourceLine = index + 1;
    if (
      javascriptIdentifierReassignedBetween(
        lines,
        local,
        bindingLine,
        sourceLine + 1,
      )
    ) {
      continue;
    }
    const result = match[1];
    const end = Math.min(structuralLines.length, index + 17);
    const bare = new RegExp(
      `\\b${escapeRegularExpression(result)}\\b(?!\\s*(?:\\?\\.|\\.)\\s*[A-Za-z_$])`,
      "u",
    );
    const condition = new RegExp(
      `\\bif\\s*\\(\\s*!{0,2}\\s*${bare.source}(?:\\s*[!=]==?\\s*(?:null|undefined))?\\s*\\)`,
      "u",
    );
    const ternary = new RegExp(`${bare.source}\\s*\\?`, "u");
    const responseAction =
      /\b(?:NextResponse|Response)\s*\.\s*(?:next|redirect|rewrite)\s*\(|\bnew\s+Response\s*\(|\b(?:redirect|rewrite|notFound|unauthorized)\s*\(/u;
    for (let candidate = index + 1; candidate < end; candidate += 1) {
      const line = structuralLines[candidate] ?? "";
      const conditionMatch = condition.exec(line);
      if (
        (conditionMatch !== null &&
          nodeAuthJsConditionHasConsequence(
            structuralLines,
            candidate,
            conditionMatch.index + conditionMatch[0].length,
          )) ||
        (ternary.test(line) &&
          responseAction.test(
            structuralLines
              .slice(candidate, Math.min(end, candidate + 7))
              .join("\n"),
          ))
      ) {
        decisions.push({ sinkLine: candidate + 1, sourceLine });
        break;
      }
    }
  }
  return decisions;
}

function nodeAuthJsWrapperFailOpenDecisions(
  use: NodeAuthJsWrapperUse,
): NodeAuthJsFailOpenDecision[] {
  const decisions: NodeAuthJsFailOpenDecision[] = [];
  const structuralLines = javascriptStructuralLines(use.file.lines);
  const escaped = escapeRegularExpression(use.local);
  const call = new RegExp(`(?<![.$\\w])${escaped}\\s*\\(`, "u");
  const bindingLine = use.importLine ?? use.binding.line;
  for (let index = bindingLine; index < structuralLines.length; index += 1) {
    if (!call.test(structuralLines[index] ?? "")) continue;
    const sourceLine = index + 1;
    if (
      javascriptIdentifierReassignedBetween(
        use.file.lines,
        use.local,
        bindingLine,
        sourceLine + 1,
      )
    ) {
      continue;
    }
    const callback = nodeAuthJsFirstCallArgument(
      use.file.lines,
      sourceLine,
      call,
    );
    if (callback === undefined) continue;
    const sinkLine = nodeAuthJsCallbackFailOpenDecision(callback);
    if (sinkLine !== undefined) decisions.push({ sinkLine, sourceLine });
  }
  decisions.push(
    ...nodeAuthJsNoArgumentFailOpenDecision(
      use.file.lines,
      use.local,
      bindingLine,
    ),
  );
  return decisions.filter(
    (decision, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.sourceLine === decision.sourceLine &&
          candidate.sinkLine === decision.sinkLine,
      ) === index,
  );
}

function nodeAuthJsConfigurationErrorFailOpenRecords(
  files: readonly SourceFileSnapshot[],
): ResidualRiskRecord[] {
  const wrappers = nodeAuthJsGeneratedWrapperBindings(files);
  const records: ResidualRiskRecord[] = [];
  for (const use of nodeAuthJsWrapperUses(files, wrappers)) {
    const decisions = nodeAuthJsWrapperFailOpenDecisions(use);
    if (
      use.exposureLine !== undefined &&
      (use.importLine === use.exposureLine ||
        !javascriptIdentifierReassignedBetween(
          use.file.lines,
          use.local,
          use.importLine ?? use.binding.line,
          use.exposureLine + 1,
        ))
    ) {
      const sinkLine = nodeAuthJsAuthorizedCallbackFailOpenDecision(
        use.binding,
      );
      if (sinkLine !== undefined) {
        decisions.push({
          sinkFile: use.binding.file,
          sinkLine,
          sourceLine: use.exposureLine,
        });
      }
    }
    for (const decision of decisions) {
      const sinkFile = decision.sinkFile ?? use.file;
      const sinkStart = Math.max(1, decision.sinkLine - CONTEXT_LINES_BEFORE);
      const sinkEnd = Math.min(
        sinkFile.lines.length,
        decision.sinkLine + CONTEXT_LINES_AFTER,
      );
      const sourceStart = Math.max(1, decision.sourceLine - 2);
      const sourceEnd = Math.min(
        use.file.lines.length,
        decision.sourceLine + 2,
      );
      const prefix =
        use.binding.dependency.proof === "npm-lockfile" ? "lock-resolved-" : "";
      const sinkKind = `${prefix}vulnerable-next-auth-truthy-error-object-authorization-decision`;
      const propagators = [
        ...(use.importLine === undefined
          ? []
          : [
              {
                kind:
                  use.file.path === use.binding.file.path
                    ? "same-file-authjs-wrapper-binding"
                    : "authjs-module-import",
                path: use.file.path,
                line: use.importLine,
                symbol: `${use.importedSymbol ?? use.binding.symbol} as ${use.local}`,
              },
            ]),
        {
          kind: "official-next-auth-factory",
          path: use.binding.file.path,
          line: use.binding.factoryLine,
          symbol: use.binding.symbol,
        },
        {
          kind: "next-auth-runtime-dependency",
          path: use.binding.dependency.manifestPath,
          line: use.binding.dependency.line,
          symbol: `next-auth@${use.binding.dependency.version}:${use.binding.dependency.proof}:truthy-configuration-error-auth-object`,
        },
      ];
      records.push({
        path: sinkFile.path,
        line: decision.sinkLine,
        categories: [
          "framework-dataflow:node-authjs-configuration-error-fail-open",
          use.file.path === sinkFile.path
            ? "framework-same-file-authjs-wrapper"
            : "framework-cross-file-authjs-wrapper",
          "modeled-source:unauthenticated-authjs-request-during-configuration-error",
          `modeled-sink:${sinkKind}`,
        ],
        priority: 120,
        startLine: sinkStart,
        endLine: sinkEnd,
        excerpt: sourceExcerpt(sinkFile.lines, sinkStart, sinkEnd),
        sourceExcerpt: sourceExcerpt(use.file.lines, sourceStart, sourceEnd),
        frameworkModel: {
          schemaVersion: "1.2",
          id: "node-authjs-configuration-error-fail-open",
          language: "javascript-typescript",
          scope: use.file.path === sinkFile.path ? "same-file" : "cross-file",
          source: {
            kind: "unauthenticated-authjs-request-during-configuration-error",
            path: use.file.path,
            line: decision.sourceLine,
          },
          sink: {
            kind: sinkKind,
            path: sinkFile.path,
            line: decision.sinkLine,
            cweIds: ["CWE-636", "CWE-285"],
          },
          propagators,
          candidateControls: [],
        },
      });
    }
  }
  return records;
}

type NodeKeystoneFactoryMember = "config" | "list";

interface NodeKeystoneFactoryBinding {
  line: number;
  local: string;
  receiver: boolean;
}

interface NodeKeystoneFactoryCall {
  argument: string;
  argumentLine: number;
  bindingLine: number;
  symbol: string;
}

interface NodeKeystoneExportedConfig {
  call: NodeKeystoneFactoryCall;
  exposureLine: number;
}

interface NodeKeystoneListsObject {
  file: SourceFileSnapshot;
  value: JavascriptResolvedExpression;
  importLine?: number;
  importedSymbol?: string;
}

function nodeKeystoneVersionHasNegativeTakeBypass(version: string): boolean {
  if (version.includes("-") || version.includes("+")) return false;
  const parts = version.split(".").map(Number);
  if (parts.length !== 3 || parts.some((part) => !Number.isSafeInteger(part))) {
    return false;
  }
  const [major, minor, patch] = parts as [number, number, number];
  return (
    major < 6 || (major === 6 && (minor < 5 || (minor === 5 && patch <= 2)))
  );
}

function nodeKeystoneFactoryBindings(
  lines: readonly string[],
  member: NodeKeystoneFactoryMember,
): NodeKeystoneFactoryBinding[] {
  const bindings: NodeKeystoneFactoryBinding[] = importedJavascriptSymbols(
    lines,
  )
    .filter(
      (binding) =>
        binding.moduleSpecifier === "@keystone-6/core" &&
        binding.imported === member,
    )
    .map((binding) => ({
      line: binding.line,
      local: binding.local,
      receiver: false,
    }));
  const codeLines = javascriptCodeLinesWithoutComments(lines);
  for (let index = 0; index < codeLines.length; index += 1) {
    const code = codeLines[index] ?? "";
    const receiver =
      /^\s*import\s+\*\s+as\s+([A-Za-z_$][\w$]*)\s+from\s+['"]@keystone-6\/core['"]/u.exec(
        code,
      ) ??
      /^\s*import\s+([A-Za-z_$][\w$]*)\s+from\s+['"]@keystone-6\/core['"]/u.exec(
        code,
      ) ??
      /^\s*import\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*['"]@keystone-6\/core['"]\s*\)/u.exec(
        code,
      ) ??
      /^\s*(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*['"]@keystone-6\/core['"]\s*\)\s*;?\s*$/u.exec(
        code,
      );
    if (receiver?.[1] !== undefined) {
      bindings.push({ line: index + 1, local: receiver[1], receiver: true });
    }
  }
  return bindings.filter(
    (binding, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.local === binding.local &&
          candidate.receiver === binding.receiver &&
          candidate.line === binding.line,
      ) === index,
  );
}

function nodeKeystoneReceiverMemberReplaced(
  lines: readonly string[],
  binding: NodeKeystoneFactoryBinding,
  member: NodeKeystoneFactoryMember,
  callLine: number,
): boolean {
  if (!binding.receiver) return false;
  const replacement = new RegExp(
    `\\b${escapeRegularExpression(binding.local)}\\s*\\.\\s*${member}\\s*(?:[+\\-*/%&|^?]?=(?!=|>)|\\+\\+|--)`,
    "u",
  );
  return javascriptStructuralLines(lines)
    .slice(binding.line, Math.max(binding.line, callLine - 1))
    .some((line) => replacement.test(line));
}

function nodeKeystoneFactoryCall(
  file: SourceFileSnapshot,
  expression: string,
  expressionLine: number,
  member: NodeKeystoneFactoryMember,
): NodeKeystoneFactoryCall | undefined {
  const bindings = nodeKeystoneFactoryBindings(file.lines, member);
  const candidates: Array<{
    binding?: NodeKeystoneFactoryBinding;
    match: RegExpExecArray;
    symbol: string;
  }> = [];
  for (const binding of bindings) {
    const escaped = escapeRegularExpression(binding.local);
    const pattern = binding.receiver
      ? new RegExp(`\\b${escaped}\\s*\\.\\s*${member}\\s*\\(`, "u")
      : new RegExp(`(?<![.$\\w])${escaped}(?:\\s*<[^;({]+>)?\\s*\\(`, "u");
    const match = pattern.exec(expression);
    if (match !== null) {
      candidates.push({
        binding,
        match,
        symbol: binding.receiver ? `${binding.local}.${member}` : binding.local,
      });
    }
  }
  const direct = new RegExp(
    `\\brequire\\s*\\(\\s*['"]@keystone-6/core['"]\\s*\\)\\s*\\.\\s*${member}\\s*\\(`,
    "u",
  ).exec(expression);
  if (direct !== null) {
    candidates.push({
      match: direct,
      symbol: `require(@keystone-6/core).${member}`,
    });
  }
  candidates.sort((left, right) => left.match.index - right.match.index);
  for (const candidate of candidates) {
    const open = candidate.match.index + candidate.match[0].lastIndexOf("(");
    const close = matchingCallParenthesis(expression, open);
    if (open < 0 || close < 0) continue;
    const body = expression.slice(open + 1, close);
    const arguments_ = splitJavascriptArguments(body);
    const argument = arguments_[0]?.trim();
    if (argument === undefined || argument === "") continue;
    const leading = body.indexOf(argument);
    const argumentLine =
      expressionLine +
      (expression.slice(0, open + 1 + Math.max(0, leading)).match(/\n/gu)
        ?.length ?? 0);
    const callLine =
      expressionLine +
      (expression.slice(0, candidate.match.index).match(/\n/gu)?.length ?? 0);
    if (
      candidate.binding !== undefined &&
      (candidate.binding.line >= callLine ||
        javascriptIdentifierReassignedBetween(
          file.lines,
          candidate.binding.local,
          candidate.binding.line,
          callLine + 1,
        ) ||
        nodeKeystoneReceiverMemberReplaced(
          file.lines,
          candidate.binding,
          member,
          callLine,
        ))
    ) {
      continue;
    }
    return {
      argument,
      argumentLine,
      bindingLine: candidate.binding?.line ?? callLine,
      symbol: candidate.symbol,
    };
  }
  return undefined;
}

function nodeKeystoneExportedConfigs(
  file: SourceFileSnapshot,
): NodeKeystoneExportedConfig[] {
  const structural = javascriptStructuralLines(file.lines);
  const original = javascriptCodeLinesWithoutComments(file.lines);
  const configs: NodeKeystoneExportedConfig[] = [];
  for (let index = 0; index < structural.length; index += 1) {
    const first = structural[index] ?? "";
    const chunk = original
      .slice(index, Math.min(original.length, index + 64))
      .join("\n");
    const direct =
      /^\s*export\s+default\s+/u.exec(first) ??
      /^\s*(?:module\s*\.\s*exports|exports\s*\.\s*default)\s*=\s*/u.exec(
        first,
      );
    if (direct !== null) {
      const prefix =
        /^\s*export\s+default\s+/u.exec(chunk) ??
        /^\s*(?:module\s*\.\s*exports|exports\s*\.\s*default)\s*=\s*/u.exec(
          chunk,
        );
      if (prefix !== null) {
        const call = nodeKeystoneFactoryCall(
          file,
          chunk.slice(prefix[0].length),
          index + 1,
          "config",
        );
        if (call !== undefined) {
          configs.push({ call, exposureLine: index + 1 });
          continue;
        }
      }
    }
    const declaration =
      /^\s*(?:export\s+)?(?:const|let|var)\s+([A-Za-z_$][\w$]*)(?:\s*:[^=;]+)?\s*=\s*/u.exec(
        first,
      );
    if (declaration?.[1] === undefined) continue;
    const completeDeclaration = new RegExp(
      `^\\s*(?:export\\s+)?(?:const|let|var)\\s+${escapeRegularExpression(declaration[1])}(?:\\s*:[^=;]+)?\\s*=\\s*`,
      "u",
    ).exec(chunk);
    if (completeDeclaration === null) continue;
    const call = nodeKeystoneFactoryCall(
      file,
      chunk.slice(completeDeclaration[0].length),
      index + 1,
      "config",
    );
    if (call === undefined) continue;
    const escaped = escapeRegularExpression(declaration[1]);
    for (
      let candidate = index + 1;
      candidate < structural.length;
      candidate += 1
    ) {
      const line = structural[candidate] ?? "";
      if (
        !new RegExp(
          `^\\s*(?:export\\s+default\\s+[^;]*\\b${escaped}\\b|(?:module\\s*\\.\\s*exports|exports\\s*\\.\\s*default)\\s*=\\s*[^;]*\\b${escaped}\\b)`,
          "u",
        ).test(line)
      ) {
        continue;
      }
      if (
        !javascriptIdentifierReassignedBetween(
          file.lines,
          declaration[1],
          index + 1,
          candidate + 2,
        )
      ) {
        configs.push({ call, exposureLine: candidate + 1 });
      }
      break;
    }
  }
  return configs.filter(
    (config, index, all) =>
      all.findIndex(
        (candidate) =>
          candidate.call.argumentLine === config.call.argumentLine &&
          candidate.exposureLine === config.exposureLine,
      ) === index,
  );
}

function nodeKeystoneExportedSymbol(
  file: SourceFileSnapshot,
  symbol: string,
): boolean {
  const escaped = escapeRegularExpression(symbol);
  return javascriptStructuralLines(file.lines).some((line) =>
    new RegExp(
      `^\\s*(?:export\\s+(?:(?:const|let|var)\\s+${escaped}\\b|\\{[^}]*\\b${escaped}\\b)|exports\\s*\\.\\s*${escaped}\\s*=|module\\s*\\.\\s*exports\\s*=\\s*\\{[^}]*\\b${escaped}\\b)`,
      "u",
    ).test(line),
  );
}

function nodeKeystoneListsObject(
  files: readonly SourceFileSnapshot[],
  configFile: SourceFileSnapshot,
  entry: JavascriptPropertyEntry,
): NodeKeystoneListsObject | undefined {
  const resolved = resolveJavascriptExpression(
    configFile.lines,
    entry.value,
    entry.line,
  );
  if (resolved !== undefined && javascriptObjectEntries(resolved).length > 0) {
    return { file: configFile, value: resolved };
  }
  if (!/^[A-Za-z_$][\w$]*$/u.test(entry.value.trim())) return undefined;
  const local = entry.value.trim();
  const imported = importedJavascriptSymbols(configFile.lines).find(
    (binding) =>
      binding.local === local &&
      (binding.moduleSpecifier.startsWith(".") ||
        binding.moduleSpecifier.startsWith("/")),
  );
  if (imported === undefined) return undefined;
  const knownPaths = new Map(
    files.map((file) => [modelPathComparisonKey(file.path), file.path]),
  );
  const importedPath = resolveRelativeModelImport(
    configFile.path,
    imported.moduleSpecifier,
    knownPaths,
  );
  const importedFile = files.find((file) => file.path === importedPath);
  if (
    importedFile === undefined ||
    !nodeKeystoneExportedSymbol(importedFile, imported.imported)
  ) {
    return undefined;
  }
  const importedValue = resolveJavascriptExpression(
    importedFile.lines,
    imported.imported,
    importedFile.lines.length + 1,
  );
  if (
    importedValue === undefined ||
    javascriptObjectEntries(importedValue).length === 0
  ) {
    return undefined;
  }
  return {
    file: importedFile,
    value: importedValue,
    importLine: imported.line,
    importedSymbol: imported.imported,
  };
}

function nodeKeystoneLiteralTrue(
  lines: readonly string[],
  expression: string,
  line: number,
): boolean {
  return (
    resolveJavascriptExpression(lines, expression, line)?.value.trim() ===
    "true"
  );
}

function nodeKeystoneQueryOmitted(
  file: SourceFileSnapshot,
  graphql: JavascriptResolvedExpression,
): boolean {
  const omit = javascriptObjectEntries(graphql).find(
    (entry) => entry.key === "omit",
  );
  if (omit === undefined) return false;
  if (nodeKeystoneLiteralTrue(file.lines, omit.value, omit.line)) return true;
  const resolved = resolveJavascriptExpression(
    file.lines,
    omit.value,
    omit.line,
  );
  if (resolved === undefined) return false;
  if (/^\[\s*['"]query['"]\s*(?:,|\])/u.test(resolved.value.trim())) {
    return true;
  }
  const query = javascriptObjectEntries(resolved).find(
    (entry) => entry.key === "query",
  );
  return (
    query !== undefined &&
    nodeKeystoneLiteralTrue(file.lines, query.value, query.line)
  );
}

function nodeKeystoneQueryDefinitelyDenied(
  file: SourceFileSnapshot,
  access: JavascriptPropertyEntry | undefined,
): boolean {
  if (access === undefined) return false;
  const raw = access.value.trim();
  if (/^[A-Za-z_$][\w$]*$/u.test(raw)) {
    const imported = importedJavascriptSymbols(file.lines).find(
      (binding) =>
        binding.local === raw &&
        binding.imported === "denyAll" &&
        binding.moduleSpecifier === "@keystone-6/core/access",
    );
    if (
      imported !== undefined &&
      !javascriptIdentifierReassignedBetween(
        file.lines,
        raw,
        imported.line,
        access.line + 1,
      )
    ) {
      return true;
    }
  }
  const resolved = resolveJavascriptExpression(file.lines, raw, access.line);
  if (resolved === undefined) return false;
  const operation = javascriptObjectEntries(resolved).find(
    (entry) => entry.key === "operation",
  );
  if (operation === undefined) return false;
  const operations = resolveJavascriptExpression(
    file.lines,
    operation.value,
    operation.line,
  );
  if (operations === undefined) return false;
  const query = javascriptObjectEntries(operations).find(
    (entry) => entry.key === "query",
  );
  if (query === undefined) return false;
  const value =
    resolveJavascriptExpression(
      file.lines,
      query.value,
      query.line,
    )?.value.trim() ?? query.value.trim();
  return (
    value === "false" ||
    /^(?:async\s+)?(?:\([^)]*\)|[A-Za-z_$][\w$]*)\s*=>\s*false\b/u.test(
      value,
    ) ||
    /^function\b[\s\S]*\breturn\s+false\b/u.test(value)
  );
}

function nodeKeystoneNegativeTakeBypassRecords(
  files: readonly SourceFileSnapshot[],
): ResidualRiskRecord[] {
  const records: ResidualRiskRecord[] = [];
  const emitted = new Set<string>();
  for (const configFile of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(configFile.extension) ||
      javascriptTestOrExamplePath(configFile.path) ||
      !configFile.text.includes("@keystone-6/core")
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(
      files,
      configFile.path,
      "@keystone-6/core",
    );
    if (
      dependency === undefined ||
      !nodeKeystoneVersionHasNegativeTakeBypass(dependency.version)
    ) {
      continue;
    }
    for (const exported of nodeKeystoneExportedConfigs(configFile)) {
      const config = resolveJavascriptExpression(
        configFile.lines,
        exported.call.argument,
        exported.call.argumentLine,
      );
      if (config === undefined) continue;
      const listsEntry = javascriptObjectEntries(config).find(
        (entry) => entry.key === "lists",
      );
      if (listsEntry === undefined) continue;
      const lists = nodeKeystoneListsObject(files, configFile, listsEntry);
      if (lists === undefined) continue;
      for (const listEntry of javascriptObjectEntries(lists.value)) {
        const listExpression = resolveJavascriptExpression(
          lists.file.lines,
          listEntry.value,
          listEntry.line,
        ) ?? { line: listEntry.line, value: listEntry.value };
        const listCall = nodeKeystoneFactoryCall(
          lists.file,
          listExpression.value,
          listExpression.line,
          "list",
        );
        if (listCall === undefined) continue;
        const listConfig = resolveJavascriptExpression(
          lists.file.lines,
          listCall.argument,
          listCall.argumentLine,
        );
        if (listConfig === undefined) continue;
        const listProperties = javascriptObjectEntries(listConfig);
        const access = listProperties.find((entry) => entry.key === "access");
        if (nodeKeystoneQueryDefinitelyDenied(lists.file, access)) continue;
        const graphqlEntry = listProperties.find(
          (entry) => entry.key === "graphql",
        );
        if (graphqlEntry === undefined) continue;
        const graphql = resolveJavascriptExpression(
          lists.file.lines,
          graphqlEntry.value,
          graphqlEntry.line,
        );
        if (
          graphql === undefined ||
          nodeKeystoneQueryOmitted(lists.file, graphql)
        ) {
          continue;
        }
        const maxTake = javascriptObjectEntries(graphql).find(
          (entry) => entry.key === "maxTake",
        );
        if (maxTake === undefined) continue;
        const maxTakeValue =
          resolveJavascriptExpression(
            lists.file.lines,
            maxTake.value,
            maxTake.line,
          )?.value.trim() ?? maxTake.value.trim();
        if (!/^[1-9]\d*$/u.test(maxTakeValue)) continue;
        const numericMaxTake = Number(maxTakeValue);
        if (!Number.isSafeInteger(numericMaxTake)) continue;
        const key = `${lists.file.path}\0${maxTake.line}\0${configFile.path}\0${exported.exposureLine}`;
        if (emitted.has(key)) continue;
        emitted.add(key);
        const prefix =
          dependency.proof === "npm-lockfile" ? "lock-resolved-" : "";
        const sinkKind = `${prefix}vulnerable-keystone-graphql-negative-take-max-take-bypass`;
        const sinkStart = Math.max(1, maxTake.line - CONTEXT_LINES_BEFORE);
        const sinkEnd = Math.min(
          lists.file.lines.length,
          maxTake.line + CONTEXT_LINES_AFTER,
        );
        const sourceStart = Math.max(1, exported.exposureLine - 2);
        const sourceEnd = Math.min(
          configFile.lines.length,
          exported.exposureLine + 2,
        );
        records.push({
          path: lists.file.path,
          line: maxTake.line,
          categories: [
            "framework-dataflow:node-keystone-graphql-negative-take-bypass",
            configFile.path === lists.file.path
              ? "framework-same-file-keystone-config"
              : "framework-cross-file-keystone-config",
            "modeled-source:untrusted-keystone-graphql-negative-take",
            `modeled-sink:${sinkKind}`,
          ],
          priority: 120,
          startLine: sinkStart,
          endLine: sinkEnd,
          excerpt: sourceExcerpt(lists.file.lines, sinkStart, sinkEnd),
          sourceExcerpt: sourceExcerpt(
            configFile.lines,
            sourceStart,
            sourceEnd,
          ),
          frameworkModel: {
            schemaVersion: "1.2",
            id: "node-keystone-graphql-negative-take-bypass",
            language: "javascript-typescript",
            scope:
              configFile.path === lists.file.path ? "same-file" : "cross-file",
            source: {
              kind: "untrusted-keystone-graphql-negative-take",
              path: configFile.path,
              line: exported.exposureLine,
            },
            sink: {
              kind: sinkKind,
              path: lists.file.path,
              line: maxTake.line,
              cweIds: ["CWE-20", "CWE-770"],
            },
            propagators: [
              {
                kind: "official-keystone-config-factory",
                path: configFile.path,
                line: exported.call.bindingLine,
                symbol: exported.call.symbol,
              },
              {
                kind: "exported-keystone-runtime-config",
                path: configFile.path,
                line: exported.exposureLine,
                symbol: "default Keystone configuration",
              },
              ...(lists.importLine === undefined
                ? []
                : [
                    {
                      kind: "relative-keystone-lists-import",
                      path: configFile.path,
                      line: lists.importLine,
                      symbol: lists.importedSymbol,
                    },
                  ]),
              {
                kind: "official-keystone-list-factory",
                path: lists.file.path,
                line: listCall.bindingLine,
                symbol: listCall.symbol,
              },
              {
                kind: "keystone-runtime-dependency",
                path: dependency.manifestPath,
                line: dependency.line,
                symbol: `@keystone-6/core@${dependency.version}:${dependency.proof}:negative-take-max-take-bypass`,
              },
            ],
            candidateControls:
              access === undefined
                ? []
                : [
                    {
                      kind: "keystone-list-query-access-control",
                      path: lists.file.path,
                      line: access.line,
                    },
                  ],
          },
        });
      }
    }
  }
  return records;
}

function frameworkCrossFileDataflowRecords(
  files: readonly SourceFileSnapshot[],
): ResidualRiskRecord[] {
  return [
    ...frameworkDirectCrossFileDataflowRecords(files),
    ...frameworkDirectPythonDataflowRecords(files),
    ...frameworkDirectJavaDataflowRecords(files),
    ...frameworkDirectDotnetDataflowRecords(files),
    ...frameworkMultiHopDataflowRecords(files),
    ...frameworkPythonMultiHopDataflowRecords(files),
    ...frameworkJavaMultiHopDataflowRecords(files),
    ...frameworkDotnetMultiHopDataflowRecords(files),
  ];
}

interface NodeOpcuaExportedServer {
  dependency: NodeRuntimeDependency;
  file: SourceFileSnapshot;
  line: number;
  symbol: string;
}

function nodeOpcuaCrossFileServerDosRecords(
  files: readonly SourceFileSnapshot[],
): ResidualRiskRecord[] {
  const knownPaths = new Map(
    files.map((file) => [modelPathComparisonKey(file.path), file.path]),
  );
  const exportedServers: NodeOpcuaExportedServer[] = [];
  for (const file of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(file.extension) ||
      javascriptTestOrExamplePath(file.path) ||
      !/['"]node-opcua['"]/u.test(file.text)
    ) {
      continue;
    }
    const dependency = nodeRuntimeDependency(files, file.path, "node-opcua");
    if (
      dependency === undefined ||
      !nodeOpcuaVersionHasUnboundedNonceCache(dependency.version)
    ) {
      continue;
    }
    const structuralLines = javascriptStructuralLines(file.lines);
    const importedServers = importedJavascriptSymbols(file.lines).filter(
      (imported) =>
        imported.moduleSpecifier === "node-opcua" &&
        imported.imported === "OPCUAServer",
    );
    for (const imported of importedServers) {
      for (
        let index = imported.line;
        index < structuralLines.length;
        index += 1
      ) {
        const declaration = new RegExp(
          `^\\s*export\\s+(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*new\\s+${escapeRegularExpression(imported.local)}\\s*\\(`,
          "u",
        ).exec(structuralLines[index] ?? "");
        if (declaration?.[1] === undefined) continue;
        const line = index + 1;
        if (
          javascriptIdentifierReassignedBetween(
            file.lines,
            imported.local,
            imported.line,
            line + 1,
          )
        ) {
          continue;
        }
        exportedServers.push({
          dependency,
          file,
          line,
          symbol: declaration[1],
        });
      }
    }
  }

  const records: ResidualRiskRecord[] = [];
  const emitted = new Set<string>();
  for (const caller of files) {
    if (
      !JAVASCRIPT_EXTENSIONS.has(caller.extension) ||
      javascriptTestOrExamplePath(caller.path)
    ) {
      continue;
    }
    const structuralLines = javascriptStructuralLines(caller.lines);
    for (const imported of importedJavascriptSymbols(caller.lines)) {
      const importedPath = resolveRelativeModelImport(
        caller.path,
        imported.moduleSpecifier,
        knownPaths,
      );
      if (importedPath === undefined) continue;
      const server = exportedServers.find(
        (candidate) =>
          candidate.file.path === importedPath &&
          candidate.symbol === imported.imported,
      );
      if (server === undefined) continue;
      const startCall = new RegExp(
        `\\b${escapeRegularExpression(imported.local)}\\s*\\.\\s*start\\s*\\(`,
        "u",
      );
      for (
        let index = imported.line;
        index < structuralLines.length;
        index += 1
      ) {
        if (!startCall.test(structuralLines[index] ?? "")) continue;
        const startLine = index + 1;
        if (
          javascriptIdentifierReassignedBetween(
            caller.lines,
            imported.local,
            imported.line,
            startLine + 1,
          ) ||
          structuralLines
            .slice(imported.line, Math.max(imported.line, startLine - 1))
            .some((candidate) =>
              new RegExp(
                `\\b${escapeRegularExpression(imported.local)}\\s*\\.\\s*start\\s*(?:[+\\-*/%&|^?]?=(?!=|>)|\\+\\+|--)`,
                "u",
              ).test(candidate),
            )
        ) {
          continue;
        }
        const key = `${caller.path}\0${startLine}\0${server.file.path}\0${server.line}`;
        if (emitted.has(key)) continue;
        emitted.add(key);
        const sinkStart = Math.max(1, server.line - CONTEXT_LINES_BEFORE);
        const sinkEnd = Math.min(
          server.file.lines.length,
          server.line + CONTEXT_LINES_AFTER,
        );
        const sourceStart = Math.max(1, startLine - 2);
        const sourceEnd = Math.min(caller.lines.length, startLine + 2);
        const prefix =
          server.dependency.proof === "npm-lockfile" ? "lock-resolved-" : "";
        const sinkKind = `${prefix}vulnerable-node-opcua-unbounded-nonce-cache-dos`;
        records.push({
          path: server.file.path,
          line: server.line,
          categories: [
            "framework-dataflow:node-opcua-server-nonce-cache-dos",
            "framework-cross-file-server-instance",
            "modeled-source:untrusted-opcua-session-nonce",
            `modeled-sink:${sinkKind}`,
          ],
          priority: 120,
          startLine: sinkStart,
          endLine: sinkEnd,
          excerpt: sourceExcerpt(server.file.lines, sinkStart, sinkEnd),
          sourceExcerpt: sourceExcerpt(caller.lines, sourceStart, sourceEnd),
          frameworkModel: {
            schemaVersion: "1.2",
            id: "node-opcua-server-nonce-cache-dos",
            language: "javascript-typescript",
            scope: "cross-file",
            source: {
              kind: "untrusted-opcua-session-nonce",
              path: caller.path,
              line: startLine,
            },
            sink: {
              kind: sinkKind,
              path: server.file.path,
              line: server.line,
              cweIds: ["CWE-770", "CWE-400"],
            },
            propagators: [
              {
                kind: "relative-module-import",
                path: caller.path,
                line: imported.line,
                symbol: `${imported.imported} as ${imported.local}`,
              },
              {
                kind: "node-opcua-runtime-dependency",
                path: server.dependency.manifestPath,
                line: server.dependency.line,
                symbol: `node-opcua@${server.dependency.version}:${server.dependency.proof}:unbounded-session-nonce-cache`,
              },
            ],
            candidateControls: [],
          },
        });
      }
    }
  }
  return records;
}

