function pythonLxmlIterparseBindings(
  lines: readonly string[],
): PythonLxmlIterparseBinding[] {
  const bindings: PythonLxmlIterparseBinding[] = [];
  const structuralLines = pythonStructuralLines(lines);
  for (let index = 0; index < structuralLines.length; index += 1) {
    const structural = structuralLines[index] ?? "";
    const moduleImport =
      /^\s*import\s+lxml\.etree(?:\s+as\s+([A-Za-z_]\w*))?\s*$/u.exec(
        structural,
      );
    if (moduleImport !== null) {
      bindings.push({
        imported: "lxml.etree.iterparse",
        local: moduleImport[1] ?? "lxml",
        memberPath:
          moduleImport[1] === undefined ? "etree.iterparse" : "iterparse",
        line: index + 1,
      });
      continue;
    }

    const etreeImport = /^\s*from\s+lxml\s+import\s+(.+?)\s*$/u.exec(
      structural,
    );
    const iterparseImport = /^\s*from\s+lxml\.etree\s+import\s+(.+?)\s*$/u.exec(
      structural,
    );
    const imported = etreeImport?.[1] ?? iterparseImport?.[1];
    if (imported === undefined) continue;
    let importedText = imported.trim();
    if (importedText.startsWith("(") && !importedText.endsWith(")")) {
      for (
        let offset = index + 1;
        offset < Math.min(structuralLines.length, index + 8);
        offset += 1
      ) {
        importedText += `\n${structuralLines[offset] ?? ""}`;
        if ((structuralLines[offset] ?? "").includes(")")) break;
      }
    }
    if (importedText.startsWith("(") !== importedText.endsWith(")")) {
      continue;
    }
    importedText = importedText.replace(/^\(([\s\S]*)\)$/u, "$1");
    for (const rawBinding of splitPythonArguments(importedText)) {
      const binding = /^([A-Za-z_]\w*)(?:\s+as\s+([A-Za-z_]\w*))?$/u.exec(
        rawBinding.trim(),
      );
      if (binding?.[1] === undefined) continue;
      if (etreeImport !== null && binding[1] === "etree") {
        bindings.push({
          imported: "lxml.etree.iterparse",
          local: binding[2] ?? "etree",
          memberPath: "iterparse",
          line: index + 1,
        });
      } else if (iterparseImport !== null && binding[1] === "iterparse") {
        bindings.push({
          imported: "lxml.etree.iterparse",
          local: binding[2] ?? "iterparse",
          memberPath: "",
          line: index + 1,
        });
      }
    }
  }
  return bindings;
}

function pythonLxmlIterparseCandidateLines(
  lines: readonly string[],
  limit: number,
): Array<{ kind: string; line: number }> {
  const bindings = pythonLxmlIterparseBindings(lines).map((binding) => {
    const memberPattern = binding.memberPath
      .split(".")
      .filter(Boolean)
      .map(escapeRegularExpression)
      .join("\\s*\\.\\s*");
    return {
      binding,
      callee:
        memberPattern === ""
          ? new RegExp(
              `\\b${escapeRegularExpression(binding.local)}\\s*\\(`,
              "u",
            )
          : new RegExp(
              `\\b${escapeRegularExpression(binding.local)}\\s*\\.\\s*${memberPattern}\\s*\\(`,
              "u",
            ),
    };
  });
  const structuralLines = pythonStructuralLines(lines);
  const matches: Array<{ kind: string; line: number }> = [];
  for (
    let index = 0;
    index < structuralLines.length && matches.length < limit;
    index += 1
  ) {
    const line = index + 1;
    const structural = structuralLines[index] ?? "";
    if (
      bindings.some(
        ({ binding, callee }) => binding.line < line && callee.test(structural),
      )
    ) {
      matches.push({
        kind: "lxml-iterparse-external-entity-resolution",
        line,
      });
    }
  }
  return matches;
}

interface PythonMemberBinding extends PythonModuleImportBinding {
  memberPath: string;
  operation: string;
}

interface PythonLxmlEtCompatBinding extends PythonMemberBinding {}

interface PythonLxmlEtCompatBindingContext {
  constructors: PythonLxmlEtCompatBinding[];
  parsers: PythonLxmlEtCompatBinding[];
}

const PYTHON_LXML_ETCOMPAT_CONSTRUCTORS = new Set([
  "ETCompatXMLParser",
  "XMLTreeBuilder",
]);

const PYTHON_LXML_PARSE_FUNCTIONS = new Set([
  "XML",
  "fromstring",
  "fromstringlist",
  "parse",
]);

function pythonLxmlEtCompatBindings(
  lines: readonly string[],
): PythonLxmlEtCompatBindingContext {
  const constructors: PythonLxmlEtCompatBinding[] = [];
  const parsers: PythonLxmlEtCompatBinding[] = [];
  const structuralLines = pythonStructuralLines(lines);
  const addReceiverBindings = (
    local: string,
    memberPrefix: string,
    line: number,
  ): void => {
    for (const operation of PYTHON_LXML_ETCOMPAT_CONSTRUCTORS) {
      constructors.push({
        imported: `lxml.etree.${operation}`,
        local,
        memberPath: `${memberPrefix}${operation}`,
        operation,
        line,
      });
    }
    for (const operation of PYTHON_LXML_PARSE_FUNCTIONS) {
      parsers.push({
        imported: `lxml.etree.${operation}`,
        local,
        memberPath: `${memberPrefix}${operation}`,
        operation,
        line,
      });
    }
  };

  for (let index = 0; index < structuralLines.length; index += 1) {
    const structural = structuralLines[index] ?? "";
    const moduleImport =
      /^\s*import\s+lxml\.etree(?:\s+as\s+([A-Za-z_]\w*))?\s*$/u.exec(
        structural,
      );
    if (moduleImport !== null) {
      addReceiverBindings(
        moduleImport[1] ?? "lxml",
        moduleImport[1] === undefined ? "etree." : "",
        index + 1,
      );
      continue;
    }

    const etreeImport = /^\s*from\s+lxml\s+import\s+(.+?)\s*$/u.exec(
      structural,
    );
    const directImport = /^\s*from\s+lxml\.etree\s+import\s+(.+?)\s*$/u.exec(
      structural,
    );
    const imported = etreeImport?.[1] ?? directImport?.[1];
    if (imported === undefined) continue;
    let importedText = imported.trim();
    if (importedText.startsWith("(") && !importedText.endsWith(")")) {
      for (
        let offset = index + 1;
        offset < Math.min(structuralLines.length, index + 8);
        offset += 1
      ) {
        importedText += `\n${structuralLines[offset] ?? ""}`;
        if ((structuralLines[offset] ?? "").includes(")")) break;
      }
    }
    if (importedText.startsWith("(") !== importedText.endsWith(")")) {
      continue;
    }
    importedText = importedText.replace(/^\(([\s\S]*)\)$/u, "$1");
    for (const rawBinding of splitPythonArguments(importedText)) {
      const binding = /^([A-Za-z_]\w*)(?:\s+as\s+([A-Za-z_]\w*))?$/u.exec(
        rawBinding.trim(),
      );
      if (binding?.[1] === undefined) continue;
      const importedName = binding[1];
      const local = binding[2] ?? importedName;
      if (etreeImport !== null && importedName === "etree") {
        addReceiverBindings(local, "", index + 1);
      } else if (
        directImport !== null &&
        PYTHON_LXML_ETCOMPAT_CONSTRUCTORS.has(importedName)
      ) {
        constructors.push({
          imported: `lxml.etree.${importedName}`,
          local,
          memberPath: "",
          operation: importedName,
          line: index + 1,
        });
      } else if (
        directImport !== null &&
        PYTHON_LXML_PARSE_FUNCTIONS.has(importedName)
      ) {
        parsers.push({
          imported: `lxml.etree.${importedName}`,
          local,
          memberPath: "",
          operation: importedName,
          line: index + 1,
        });
      }
    }
  }
  return { constructors, parsers };
}

function pythonMemberBindingCallee(binding: PythonMemberBinding): RegExp {
  const memberPattern = binding.memberPath
    .split(".")
    .filter(Boolean)
    .map(escapeRegularExpression)
    .join("\\s*\\.\\s*");
  return memberPattern === ""
    ? new RegExp(`\\b${escapeRegularExpression(binding.local)}\\s*\\(`, "u")
    : new RegExp(
        `\\b${escapeRegularExpression(binding.local)}\\s*\\.\\s*${memberPattern}\\s*\\(`,
        "u",
      );
}

function pythonMemberBindingIsLive(
  lines: readonly string[],
  binding: PythonMemberBinding,
  callLine: number,
  wrapper: ExportedPythonFunction | undefined,
): boolean {
  const rootMember = binding.memberPath.split(".")[0];
  return !(
    binding.line >= callLine ||
    wrapper?.parameters.includes(binding.local) === true ||
    pythonImportedBindingReassigned(lines, binding, undefined, callLine) ||
    (binding.memberPath !== "" &&
      (pythonImportedBindingReassigned(
        lines,
        binding,
        binding.memberPath,
        callLine,
      ) ||
        (rootMember !== undefined &&
          pythonImportedBindingReassigned(
            lines,
            binding,
            rootMember,
            callLine,
          ))))
  );
}

function pythonLxmlEtCompatCandidateLines(
  lines: readonly string[],
  limit: number,
): Array<{ kind: string; line: number }> {
  const bindings = pythonLxmlEtCompatBindings(lines).parsers.map((binding) => ({
    binding,
    callee: pythonMemberBindingCallee(binding),
  }));
  const structuralLines = pythonStructuralLines(lines);
  const matches: Array<{ kind: string; line: number }> = [];
  for (
    let index = 0;
    index < structuralLines.length && matches.length < limit;
    index += 1
  ) {
    const line = index + 1;
    const structural = structuralLines[index] ?? "";
    if (
      bindings.some(
        ({ binding, callee }) => binding.line < line && callee.test(structural),
      )
    ) {
      matches.push({
        kind: "lxml-etcompat-external-entity-resolution",
        line,
      });
    }
  }
  return matches;
}

interface PythonResolvedExpressionOrigin {
  expression: string;
  line: number;
}

function pythonTopLevelFunctionRangeAtLine(
  lines: readonly string[],
  line: number,
): { startLine: number; endLine: number } | undefined {
  const structuralLines = pythonStructuralLines(lines);
  for (let index = 0; index < structuralLines.length; index += 1) {
    const structural = structuralLines[index] ?? "";
    if (
      /^\s/u.test(structural) ||
      !/^(?:async\s+)?def\s+[A-Za-z_]\w*\s*\(/u.test(structural)
    ) {
      continue;
    }
    const endLine = pythonFunctionEndLine(lines, index);
    if (line >= index + 1 && line <= endLine) {
      return { startLine: index + 1, endLine };
    }
  }
  return undefined;
}

function pythonAssignmentValueAtLine(
  lines: readonly string[],
  line: number,
): string | undefined {
  const original = lines
    .slice(line - 1, Math.min(lines.length, line + 12))
    .join("\n");
  const equals = pythonStructuralCode(lines[line - 1] ?? "").indexOf("=");
  if (equals < 0) return undefined;
  const value = original.slice(equals + 1).trim();
  const firstLine = value.split("\n", 1)[0] ?? "";
  const structural = pythonStructuralLines(value.split("\n")).join("\n");
  const first = structural.search(/\S/u);
  let open = first >= 0 && "([{".includes(structural[first] ?? "") ? first : -1;
  if (open < 0) open = pythonStructuralCode(firstLine).indexOf("(");
  if (open < 0) return firstLine.trim();
  const opening = structural[open];
  const closing = opening === "(" ? ")" : opening === "[" ? "]" : "}";
  let depth = 0;
  let close = -1;
  for (let index = open; index < structural.length; index += 1) {
    if (structural[index] === opening) depth += 1;
    else if (structural[index] === closing) {
      depth -= 1;
      if (depth === 0) {
        close = index;
        break;
      }
    }
  }
  return (close < 0 ? value : value.slice(0, close + 1)).trim();
}

function resolvePythonExpressionOrigin(
  lines: readonly string[],
  expression: string,
  beforeLine: number,
  depth = 0,
  seen: ReadonlySet<string> = new Set(),
): PythonResolvedExpressionOrigin | undefined {
  const value = expression.trim();
  if (value === "" || depth > 8) return undefined;
  if (!/^[A-Za-z_]\w*$/u.test(value)) {
    return { expression: value, line: beforeLine };
  }
  if (seen.has(value)) return undefined;
  const earliest = Math.max(1, beforeLine - 64);
  const structuralLines = pythonStructuralLines(lines);
  const assignment = new RegExp(
    `^\\s*${escapeRegularExpression(value)}\\s*(?::[^=]+)?=`,
    "u",
  );
  for (let line = beforeLine - 1; line >= earliest; line -= 1) {
    if (!assignment.test(structuralLines[line - 1] ?? "")) continue;
    if (pythonIdentifierReassignedBetween(lines, value, line, beforeLine)) {
      return undefined;
    }
    const assigned = pythonAssignmentValueAtLine(lines, line);
    if (assigned === undefined) return undefined;
    return resolvePythonExpressionOrigin(
      lines,
      assigned,
      line,
      depth + 1,
      new Set([...seen, value]),
    );
  }
  return { expression: value, line: beforeLine };
}

function pythonCallArgumentsForExpression(
  expression: string,
  callee: RegExp,
): string[] | undefined {
  const structural = pythonStructuralCode(expression);
  const match = callee.exec(structural);
  if (match === null) return undefined;
  const open = structural.indexOf("(", match.index);
  if (open < 0) return undefined;
  const close = matchingCallParenthesis(expression, open);
  if (close < 0 || expression.slice(close + 1).trim() !== "") return undefined;
  return splitPythonArguments(expression.slice(open + 1, close));
}

interface PythonPinnedRequirement {
  packageName: string;
  version: string;
  path: string;
  line: number;
}

interface PythonPinnedRuntime {
  version: string;
  path: string;
  line: number;
}

function pythonPinnedRuntime(
  files: readonly SourceFileSnapshot[],
  sourcePath: string,
): PythonPinnedRuntime | undefined {
  let directory = posix.dirname(sourcePath.replaceAll("\\", "/"));
  while (true) {
    const prefix = directory === "." ? "" : `${directory}/`;
    const runtimeFiles = files.filter((file) => {
      const normalized = file.path.replaceAll("\\", "/").toLowerCase();
      return (
        normalized === `${prefix}.python-version`.toLowerCase() ||
        normalized === `${prefix}runtime.txt`.toLowerCase()
      );
    });
    if (runtimeFiles.length > 0) {
      if (runtimeFiles.length !== 1) return undefined;
      const runtime = runtimeFiles[0]!;
      const nonempty = runtime.lines
        .map((line, index) => ({ line: line.trim(), index }))
        .filter(({ line }) => line !== "" && !line.startsWith("#"));
      if (nonempty.length !== 1) return undefined;
      const expected = runtime.path.toLowerCase().endsWith("runtime.txt")
        ? /^python-(\d+\.\d+\.\d+)$/u
        : /^(\d+\.\d+\.\d+)$/u;
      const parsed = expected.exec(nonempty[0]!.line);
      return parsed?.[1] === undefined
        ? undefined
        : {
            version: parsed[1],
            path: runtime.path,
            line: nonempty[0]!.index + 1,
          };
    }
    if (directory === ".") break;
    const parent = posix.dirname(directory);
    if (parent === directory) break;
    directory = parent;
  }
  return undefined;
}

function pythonPinnedRequirement(
  files: readonly SourceFileSnapshot[],
  sourcePath: string,
  packageName: string,
): PythonPinnedRequirement | undefined {
  let directory = posix.dirname(sourcePath.replaceAll("\\", "/"));
  const normalizedPackage = packageName.toLowerCase();
  const requirement = new RegExp(
    `^\\s*${escapeRegularExpression(packageName)}(?:\\[[^\\]]+\\])?\\s*==\\s*([0-9]+\\.[0-9]+\\.[0-9]+(?:[+.-][A-Za-z0-9.]+)?)\\s*(?:;[^#]+)?(?:#.*)?$`,
    "iu",
  );
  while (true) {
    const prefix = directory === "." ? "" : `${directory}/`;
    const requirementFiles = files.filter(
      (file) =>
        file.path.replaceAll("\\", "/").toLowerCase() ===
        `${prefix}requirements.txt`.toLowerCase(),
    );
    if (requirementFiles.length === 1) {
      const matches = requirementFiles[0]!.lines.flatMap((line, index) => {
        const parsed = requirement.exec(pythonStructuralCode(line));
        return parsed?.[1] === undefined
          ? []
          : [
              {
                packageName: normalizedPackage,
                version: parsed[1],
                path: requirementFiles[0]!.path,
                line: index + 1,
              },
            ];
      });
      return matches.length === 1 ? matches[0] : undefined;
    }
    if (directory === ".") break;
    const parent = posix.dirname(directory);
    if (parent === directory) break;
    directory = parent;
  }
  return undefined;
}

function pythonPackageVersionAtMost(
  version: string,
  ceiling: readonly [number, number, number],
): boolean {
  const parsed = /^(\d+)\.(\d+)\.(\d+)/u.exec(version);
  if (parsed === null) return false;
  const values = [Number(parsed[1]), Number(parsed[2]), Number(parsed[3])];
  for (let index = 0; index < ceiling.length; index += 1) {
    if (values[index]! < ceiling[index]!) return true;
    if (values[index]! > ceiling[index]!) return false;
  }
  return true;
}

function pythonPackageVersionAtLeast(
  version: string,
  floor: readonly [number, number, number],
): boolean {
  const parsed = /^(\d+)\.(\d+)\.(\d+)/u.exec(version);
  if (parsed === null) return false;
  const values = [Number(parsed[1]), Number(parsed[2]), Number(parsed[3])];
  for (let index = 0; index < floor.length; index += 1) {
    if (values[index]! > floor[index]!) return true;
    if (values[index]! < floor[index]!) return false;
  }
  return true;
}

interface PythonAsyncSshScpBinding extends PythonMemberBinding {
  originLine?: number;
}

interface PythonAsyncSshRemoteSource {
  expression: string;
  line: number;
  route: "connection-tuple" | "host-path";
}

interface PythonAsyncSshLocalDestination {
  expression: string;
  line: number;
}

function pythonAsyncSshBindingExpression(
  binding: PythonAsyncSshScpBinding,
): string {
  return binding.memberPath === ""
    ? binding.local
    : `${binding.local}.${binding.memberPath}`;
}

function pythonAsyncSshScpBindings(
  lines: readonly string[],
): PythonAsyncSshScpBinding[] {
  const bindings: PythonAsyncSshScpBinding[] = [];
  const structuralLines = pythonStructuralLines(lines);
  for (let index = 0; index < structuralLines.length; index += 1) {
    const structural = structuralLines[index] ?? "";
    const moduleImport =
      /^\s*import\s+asyncssh(?:\s+as\s+([A-Za-z_]\w*))?\s*$/u.exec(structural);
    if (moduleImport !== null) {
      bindings.push({
        imported: "asyncssh.scp",
        local: moduleImport[1] ?? "asyncssh",
        memberPath: "scp",
        operation: "scp",
        line: index + 1,
      });
      continue;
    }
    const fromImport = /^\s*from\s+asyncssh\s+import\s+(.+?)\s*$/u.exec(
      structural,
    );
    if (fromImport?.[1] === undefined) continue;
    const importedText = pythonCollectedImport(
      structuralLines,
      index,
      fromImport[1],
    );
    if (importedText === undefined) continue;
    for (const rawBinding of splitPythonArguments(importedText)) {
      const parsed = /^scp(?:\s+as\s+([A-Za-z_]\w*))?$/u.exec(
        rawBinding.trim(),
      );
      if (parsed === null) continue;
      bindings.push({
        imported: "asyncssh.scp",
        local: parsed[1] ?? "scp",
        memberPath: "",
        operation: "scp",
        line: index + 1,
      });
    }
  }

  const importedBindings = [...bindings];
  for (let index = 0; index < structuralLines.length; index += 1) {
    const structural = structuralLines[index] ?? "";
    if (/^\s/u.test(structural)) continue;
    for (const binding of importedBindings) {
      if (
        binding.line >= index + 1 ||
        !pythonMemberBindingIsLive(lines, binding, index + 1, undefined)
      ) {
        continue;
      }
      const source = pythonAsyncSshBindingExpression(binding)
        .split(".")
        .map(escapeRegularExpression)
        .join("\\s*\\.\\s*");
      const alias = new RegExp(
        `^\\s*([A-Za-z_]\\w*)\\s*(?::[^=]+)?=\\s*${source}\\s*$`,
        "u",
      ).exec(structural)?.[1];
      if (alias === undefined || alias === binding.local) continue;
      bindings.push({
        imported: binding.imported,
        local: alias,
        memberPath: "",
        operation: "scp",
        line: index + 1,
        originLine: binding.originLine ?? binding.line,
      });
    }
  }
  return bindings;
}

function pythonLiteralStringValue(expression: string): string | undefined {
  const match = /^(?:[rRuUbB]{0,2})(["'])([\s\S]*)\1$/u.exec(expression.trim());
  return match?.[2];
}

function pythonAsyncSshRemoteSource(
  lines: readonly string[],
  expression: string,
  beforeLine: number,
): PythonAsyncSshRemoteSource | undefined {
  const origin = resolvePythonExpressionOrigin(lines, expression, beforeLine);
  if (origin === undefined) return undefined;
  const value = origin.expression.trim();
  const literal = pythonLiteralStringValue(value);
  if (literal !== undefined) {
    const colon = literal.indexOf(":");
    if (colon <= 0 || /^[A-Za-z]:/u.test(literal)) return undefined;
    return { expression: value, line: origin.line, route: "host-path" };
  }
  if (
    !value.startsWith("(") ||
    matchingCallParenthesis(value, 0) !== value.length - 1
  ) {
    return undefined;
  }
  const tuple = splitPythonArguments(value.slice(1, -1));
  if (
    tuple.length !== 2 ||
    tuple.some(
      (entry) => entry.trim() === "" || entry.trim().startsWith("*"),
    ) ||
    /^(?:None|False|0(?:\.0+)?|["']["'])$/u.test(tuple[0]!.trim())
  ) {
    return undefined;
  }
  return { expression: value, line: origin.line, route: "connection-tuple" };
}

function pythonAsyncSshLocalDestination(
  lines: readonly string[],
  expression: string,
  beforeLine: number,
): PythonAsyncSshLocalDestination | undefined {
  const origin = resolvePythonExpressionOrigin(lines, expression, beforeLine);
  if (origin === undefined) return undefined;
  const value = origin.expression.trim();
  const literal = pythonLiteralStringValue(value);
  if (literal !== undefined) {
    const colon = literal.indexOf(":");
    if (colon >= 0) return undefined;
    return { expression: value, line: origin.line };
  }
  const pathCall =
    /^(?:pathlib\s*\.\s*)?(?:Path|PurePath)\s*\(([\s\S]*)\)$/u.exec(value);
  if (pathCall?.[1] === undefined) return undefined;
  const arguments_ = splitPythonArguments(pathCall[1]);
  if (
    arguments_.length > 1 ||
    arguments_.some((argument) => argument.trim().startsWith("*"))
  ) {
    return undefined;
  }
  if (arguments_.length === 1) {
    const path = pythonLiteralStringValue(arguments_[0]!);
    if (path === undefined) return undefined;
  }
  return { expression: value, line: origin.line };
}

function pythonAsyncSshScpCandidateLines(
  lines: readonly string[],
  limit: number,
): Array<{ kind: string; line: number }> {
  const bindings = pythonAsyncSshScpBindings(lines);
  const structuralLines = pythonStructuralLines(lines);
  const matches: Array<{ kind: string; line: number }> = [];
  for (
    let index = 0;
    index < structuralLines.length && matches.length < limit;
    index += 1
  ) {
    const line = index + 1;
    const wrapper = exportedPythonFunctions(lines).find(
      (candidate) => line >= candidate.startLine && line <= candidate.endLine,
    );
    if (
      bindings.some(
        (binding) =>
          pythonMemberBindingIsLive(lines, binding, line, wrapper) &&
          pythonMemberBindingCallee(binding).test(structuralLines[index] ?? ""),
      )
    ) {
      matches.push({ kind: "asyncssh-scp-download-local-file-write", line });
    }
  }
  return matches;
}

function pythonAsyncSshScpDownloadSink(
  files: readonly SourceFileSnapshot[],
  sourcePath: string,
  lines: readonly string[],
  line: number,
): PythonTypedSink | undefined {
  if (
    javascriptTestOrExamplePath(sourcePath) ||
    pythonLocalModuleCouldShadow(files, sourcePath, "asyncssh")
  ) {
    return undefined;
  }
  const wrapper = exportedPythonFunctions(lines).find(
    (candidate) => line >= candidate.startLine && line <= candidate.endLine,
  );
  for (const binding of pythonAsyncSshScpBindings(lines)) {
    if (!pythonMemberBindingIsLive(lines, binding, line, wrapper)) continue;
    const callee = pythonMemberBindingCallee(binding);
    if (!callee.test(pythonStructuralLines(lines)[line - 1] ?? "")) continue;
    const arguments_ = pythonCallArgumentsForCalleeAtLine(lines, line, callee);
    if (
      arguments_ === undefined ||
      arguments_.some((argument) => argument.trim().startsWith("*"))
    ) {
      continue;
    }
    const positional = pythonPositionalArguments(arguments_);
    const sourceKeyword = pythonKeywordArgument(arguments_, "srcpaths");
    const destinationKeyword = pythonKeywordArgument(arguments_, "dstpath");
    if (
      positional.length > 2 ||
      (sourceKeyword !== undefined && positional.length > 0) ||
      (destinationKeyword !== undefined && positional.length > 1)
    ) {
      continue;
    }
    const sourceExpression = sourceKeyword ?? positional[0];
    const destinationExpression = destinationKeyword ?? positional[1];
    if (sourceExpression === undefined || destinationExpression === undefined) {
      continue;
    }
    const remote = pythonAsyncSshRemoteSource(lines, sourceExpression, line);
    const destination = pythonAsyncSshLocalDestination(
      lines,
      destinationExpression,
      line,
    );
    if (remote === undefined || destination === undefined) continue;
    const pinned = pythonPinnedRequirement(files, sourcePath, "asyncssh");
    if (
      pinned === undefined ||
      !/^\d+\.\d+\.\d+$/u.test(pinned.version) ||
      !pythonPackageVersionAtMost(pinned.version, [2, 23, 0])
    ) {
      continue;
    }
    return {
      sourceExpression: "asyncssh.scp(",
      kind: "asyncssh-affected-scp-download-path-traversal",
      propagators: [
        {
          kind: "asyncssh-scp-binding",
          path: sourcePath,
          line: binding.originLine ?? binding.line,
          symbol: `${binding.imported} as ${pythonAsyncSshBindingExpression(binding)}`,
        },
        ...(binding.originLine === undefined
          ? []
          : [
              {
                kind: "asyncssh-scp-callable-alias",
                path: sourcePath,
                line: binding.line,
                symbol: binding.local,
              },
            ]),
        {
          kind: "asyncssh-runtime-dependency",
          path: pinned.path,
          line: pinned.line,
          symbol: `asyncssh@${pinned.version}:requirements-exact`,
        },
        {
          kind: "asyncssh-remote-scp-source",
          path: sourcePath,
          line: remote.line,
          symbol: `${remote.route}:${remote.expression}`,
        },
        {
          kind: "asyncssh-local-download-destination",
          path: sourcePath,
          line: destination.line,
          symbol: destination.expression,
        },
        {
          kind: "intrinsic-scp-server-filename-control",
          path: sourcePath,
          line,
          symbol: "scp -f -> C/D filename fields",
        },
        {
          kind: "intrinsic-asyncssh-traversal-write",
          path: sourcePath,
          line,
          symbol: "_parse_cd_args -> posixpath.join -> _recv_file open(wb)",
        },
      ],
    };
  }
  return undefined;
}

interface PythonPyyamlBindingContext {
  receivers: PythonModuleImportBinding[];
  functions: PythonModuleImportBinding[];
  loaders: PythonModuleImportBinding[];
}

const PYTHON_PYYAML_UNSAFE_LOADERS = new Set([
  "Loader",
  "UnsafeLoader",
  "CLoader",
  "CUnsafeLoader",
]);

function pythonPyyamlBindings(
  lines: readonly string[],
): PythonPyyamlBindingContext {
  const receivers: PythonModuleImportBinding[] = [];
  const functions: PythonModuleImportBinding[] = [];
  const loaders: PythonModuleImportBinding[] = [];
  const structuralLines = pythonStructuralLines(lines);
  for (let index = 0; index < structuralLines.length; index += 1) {
    const structural = structuralLines[index] ?? "";
    const receiver = /^\s*import\s+yaml(?:\s+as\s+([A-Za-z_]\w*))?\s*$/u.exec(
      structural,
    );
    if (receiver !== null) {
      receivers.push({
        imported: "yaml",
        local: receiver[1] ?? "yaml",
        line: index + 1,
      });
      continue;
    }
    const fromImport = /^\s*from\s+yaml\s+import\s+(.+?)\s*$/u.exec(structural);
    if (fromImport?.[1] === undefined) continue;
    let importedText = fromImport[1].trim();
    if (importedText.startsWith("(") && !importedText.endsWith(")")) {
      for (
        let offset = index + 1;
        offset < Math.min(structuralLines.length, index + 8);
        offset += 1
      ) {
        importedText += `\n${structuralLines[offset] ?? ""}`;
        if ((structuralLines[offset] ?? "").includes(")")) break;
      }
    }
    if (importedText.startsWith("(") !== importedText.endsWith(")")) {
      continue;
    }
    importedText = importedText.replace(/^\(([\s\S]*)\)$/u, "$1");
    for (const rawBinding of splitPythonArguments(importedText)) {
      const binding = /^([A-Za-z_]\w*)(?:\s+as\s+([A-Za-z_]\w*))?$/u.exec(
        rawBinding.trim(),
      );
      if (binding?.[1] === undefined) continue;
      const entry = {
        imported: binding[1],
        local: binding[2] ?? binding[1],
        line: index + 1,
      };
      if (entry.imported === "load" || entry.imported === "unsafe_load") {
        functions.push(entry);
      } else if (PYTHON_PYYAML_UNSAFE_LOADERS.has(entry.imported)) {
        loaders.push(entry);
      }
    }
  }
  return { receivers, functions, loaders };
}

function pythonLocalModuleCouldShadow(
  files: readonly SourceFileSnapshot[],
  sourcePath: string,
  moduleName: string,
): boolean {
  const candidates = new Set<string>();
  let directory = posix.dirname(sourcePath.replaceAll("\\", "/"));
  while (true) {
    const prefix = directory === "." ? "" : `${directory}/`;
    candidates.add(`${prefix}${moduleName}.py`.toLowerCase());
    candidates.add(`${prefix}${moduleName}/__init__.py`.toLowerCase());
    if (directory === ".") break;
    const parent = posix.dirname(directory);
    if (parent === directory) break;
    directory = parent;
  }
  return files.some((file) =>
    candidates.has(file.path.replaceAll("\\", "/").toLowerCase()),
  );
}

function pythonImportedBindingReassigned(
  lines: readonly string[],
  binding: PythonModuleImportBinding,
  member: string | undefined,
  callLine: number,
): boolean {
  if (
    pythonIdentifierReassignedBetween(
      lines,
      binding.local,
      binding.line,
      callLine,
    )
  ) {
    return true;
  }
  if (member === undefined) return false;
  const replacement = new RegExp(
    `^\\s*${escapeRegularExpression(binding.local)}\\s*\\.\\s*${escapeRegularExpression(member)}\\s*(?:[+\\-*/%&|^]?=|:=)`,
    "u",
  );
  return pythonStructuralLines(lines)
    .slice(binding.line, Math.max(binding.line, callLine - 1))
    .some((candidate) => replacement.test(candidate));
}

function pythonCallArgumentsForCalleeAtLine(
  lines: readonly string[],
  line: number,
  callee: RegExp,
): string[] | undefined {
  const callLines = lines.slice(line - 1, Math.min(lines.length, line + 12));
  const original = callLines.join("\n");
  const structural = pythonStructuralLines(callLines).join("\n");
  const match = callee.exec(structural);
  if (match === null) return undefined;
  const firstLineEnd = structural.indexOf("\n");
  if (firstLineEnd >= 0 && match.index >= firstLineEnd) return undefined;
  const open = structural.indexOf("(", match.index);
  if (open < 0) return undefined;
  const close = matchingCallParenthesis(original, open);
  if (close < 0) return undefined;
  return splitPythonArguments(original.slice(open + 1, close));
}

function pythonKeywordArgument(
  arguments_: readonly string[],
  name: string,
): string | undefined {
  const expression = new RegExp(
    `^${escapeRegularExpression(name)}\\s*=\\s*([\\s\\S]+)$`,
    "u",
  );
  for (const argument of arguments_) {
    const match = expression.exec(argument.trim());
    if (match?.[1] !== undefined) return match[1].trim();
  }
  return undefined;
}

function pythonPositionalArguments(arguments_: readonly string[]): string[] {
  return arguments_
    .map((argument) => argument.trim())
    .filter(
      (argument) =>
        argument !== "" &&
        !/^[A-Za-z_]\w*\s*=/u.test(argument) &&
        !argument.startsWith("**"),
    );
}

function pythonNumpyAllowPickleUnsafeSink(
  files: readonly SourceFileSnapshot[],
  sourcePath: string,
  lines: readonly string[],
  line: number,
): PythonTypedSink | undefined {
  if (pythonLocalModuleCouldShadow(files, sourcePath, "numpy")) {
    return undefined;
  }
  const context = pythonNumpyBindings(lines);
  const wrapper = exportedPythonFunctions(lines).find(
    (candidate) => line >= candidate.startLine && line <= candidate.endLine,
  );
  const calls = [
    ...context.receivers.map((binding) => ({ binding, receiverCall: true })),
    ...context.functions.map((binding) => ({ binding, receiverCall: false })),
  ];
  for (const call of calls) {
    if (
      call.binding.line >= line ||
      wrapper?.parameters.includes(call.binding.local) === true ||
      pythonImportedBindingReassigned(
        lines,
        call.binding,
        call.receiverCall ? "load" : undefined,
        line,
      )
    ) {
      continue;
    }
    const callee = call.receiverCall
      ? new RegExp(
          `\\b${escapeRegularExpression(call.binding.local)}\\s*\\.\\s*load\\s*\\(`,
          "u",
        )
      : new RegExp(
          `\\b${escapeRegularExpression(call.binding.local)}\\s*\\(`,
          "u",
        );
    const arguments_ = pythonCallArgumentsForCalleeAtLine(lines, line, callee);
    if (arguments_ === undefined) continue;
    if (arguments_.some((argument) => argument.trim().startsWith("*"))) {
      continue;
    }
    const positional = pythonPositionalArguments(arguments_);
    const sourceExpression =
      pythonKeywordArgument(arguments_, "file") ?? positional[0];
    const allowPickleExpression =
      pythonKeywordArgument(arguments_, "allow_pickle") ?? positional[2];
    if (
      sourceExpression === undefined ||
      sourceExpression.trim() === "" ||
      sourceExpression.trim().startsWith("*") ||
      allowPickleExpression === undefined ||
      pythonStructuralCode(allowPickleExpression).trim() !== "True"
    ) {
      continue;
    }
    return {
      sourceExpression,
      kind: "numpy-load-allow-pickle-untrusted-file",
      propagators: [
        {
          kind: "numpy-load-binding",
          path: sourcePath,
          line: call.binding.line,
          symbol: `${call.binding.imported} as ${call.binding.local}`,
        },
        {
          kind: "explicit-numpy-allow-pickle",
          path: sourcePath,
          line,
          symbol: "allow_pickle=True",
        },
        {
          kind: "intrinsic-numpy-object-array-unpickling",
          path: sourcePath,
          line,
          symbol: "numpy.load",
        },
      ],
    };
  }
  return undefined;
}

